def format_red_contract(marker, findings_by_category):
    normalized = {}
    for category, findings in findings_by_category.items():
        assert re.fullmatch(r"[A-Z][A-Z0-9_]*", category)
        details = tuple(sorted({str(finding) for finding in findings if str(finding)}))
        if details:
            normalized[category] = details
    categories = tuple(sorted(normalized))
    summary = (
        f"{marker} categories={','.join(categories)} "
        f"category_count={len(categories)}"
    )
    details = tuple(
        f"{category}: {finding}"
        for category in categories
        for finding in normalized[category]
    )
    return summary, details


def ascii_safe_red_detail(detail):
    """Keep RED evidence printable under the plain Windows pytest command."""
    return str(detail).encode("ascii", errors="backslashreplace").decode("ascii")


def fail_red_contract(marker, findings_by_category):
    summary, details = format_red_contract(marker, findings_by_category)
    for detail in details:
        print(ascii_safe_red_detail(f"{marker}_DETAIL {detail}"))
    assert not details, summary


def test_red_contract_detail_printing_is_ascii_safe_and_identifiable(capsys):
    with pytest.raises(AssertionError, match="categories=WRITER"):
        fail_red_contract("RED_CONTRACT_TEST", {
            "WRITER": ["plot.py:VISIBLE:CΨ_com"],
        })
    output = capsys.readouterr().out
    assert output.isascii()
    assert "RED_CONTRACT_TEST_DETAIL WRITER: plot.py:VISIBLE:" in output
    assert r"C\u03a8_com" in output
    assert "CΨ_com" not in output


def read_host(path):
    return (ROOT / path).read_text(encoding="utf-8-sig").replace("\r\n", "\n").replace("\r", "\n")


def artifact_hashes():
    return {path: hashlib.sha256((ROOT / path).read_bytes()).hexdigest()
            for path in RED_TRACKED_ARTIFACTS}


