FROZEN_CAPSULE_RECOVERY_PLAN_FIXTURE = """\
  $stateRecords = foreach ($line in Get-Content -LiteralPath $repairPlanPath) {
    $fields = $line.Split('|')
    if ($fields.Count -eq 7 -and
        $fields[3] -eq 'HASH' -and
        $fields[4].StartsWith(
          'docs/superpowers/plans/.old-document-label-repair-state/',
          [StringComparison]::Ordinal
        ) -and
        $fields[4].EndsWith('.clixml', [StringComparison]::Ordinal) -and
        $fields[6] -match '^[0-9A-F]{64}$') {
      [pscustomobject]@{ Path = $fields[4]; Hash = $fields[6] }
    }
  }
  if (@($stateRecords).Count -eq 0) {
    throw 'No complete session-state record exists; do not resume.'
  }
"""


def _capsule_recovery_selector_condition(plan):
    recovery = plan.split("$stateRecords = foreach", 1)[1].split(
        "if (@($stateRecords).Count -eq 0)", 1
    )[0]
    match = re.search(r"(?ms)^\s*if \((.*?)\) \{\s*$", recovery)
    assert match is not None
    return recovery, match.group(1)


def _evaluate_capsule_recovery_selector(condition, rows):
    powershell = shutil.which("pwsh") or shutil.which("powershell")
    assert powershell is not None
    row_literals = "\n".join(
        "  '" + row.replace("'", "''") + "'" for row in rows
    )
    script = (
        "$rows = @(\n"
        f"{row_literals}\n"
        ")\n"
        "$selected = @(foreach ($line in $rows) {\n"
        "  $fields = $line.Split('|')\n"
        f"  if ({condition}) {{ $fields[4] }}\n"
        "})\n"
        "$selected | ForEach-Object { Write-Output $_ }\n"
    )
    completed = subprocess.run(
        [powershell, "-NoProfile", "-NonInteractive", "-Command", script],
        cwd=ROOT,
        text=True,
        capture_output=True,
        check=False,
    )
    assert completed.returncode == 0, completed.stderr
    return tuple(line.strip() for line in completed.stdout.splitlines() if line.strip())


def _assert_capsule_recovery_selector_is_clixml_only(plan):
    recovery, condition = _capsule_recovery_selector_condition(plan)
    assert "old-document-label-repair-state/" in recovery
    assert "$fields[3] -eq 'HASH'" in recovery
    assert "$fields[4].EndsWith('.clixml', [StringComparison]::Ordinal)" in recovery
    assert "$fields[6] -match '^[0-9A-F]{64}$'" in recovery
    assert len(re.findall(r"(?i)(?<!\w)-and\b", condition)) == 4
    assert re.search(r"(?i)(?<!\w)-or\b", condition) is None
    assert re.search(
        r"(?s)\$fields\[4\]\.EndsWith\('\.clixml',\s*"
        r"\[StringComparison\]::Ordinal\)\s+-and\s+\$fields\[6\]\s+-match",
        condition,
    )

    prefix = "docs/superpowers/plans/.old-document-label-repair-state/"
    capsule_path = prefix + "synthetic.clixml"
    json_path = prefix + "synthetic.json"
    rows = (
        "000001|2026-09-15T00:00:00Z|synthetic|HASH|"
        + capsule_path
        + "|-|"
        + "A" * 64,
        "000002|2026-09-15T00:00:01Z|synthetic|HASH|"
        + json_path
        + "|-|"
        + "B" * 64,
    )
    assert _evaluate_capsule_recovery_selector(condition, rows) == (capsule_path,)


def test_capsule_recovery_selector_rejects_non_clixml_hash_rows():
    plan = FROZEN_CAPSULE_RECOVERY_PLAN_FIXTURE
    _assert_capsule_recovery_selector_is_clixml_only(plan)
    mutant = plan.replace(
        "$fields[4].EndsWith('.clixml', [StringComparison]::Ordinal) -and\n",
        "",
        1,
    )
    assert mutant != plan
    with pytest.raises(AssertionError):
        _assert_capsule_recovery_selector_is_clixml_only(mutant)


def test_capsule_recovery_selector_rejects_or_bypass():
    plan = FROZEN_CAPSULE_RECOVERY_PLAN_FIXTURE
    mutant = plan.replace(
        "$fields[4].EndsWith('.clixml', [StringComparison]::Ordinal) -and\n"
        "        $fields[6] -match",
        "$fields[4].EndsWith('.clixml', [StringComparison]::Ordinal) -or\n"
        "        $fields[6] -match",
        1,
    )
    assert mutant != plan
    _, mutant_condition = _capsule_recovery_selector_condition(mutant)
    prefix = "docs/superpowers/plans/.old-document-label-repair-state/"
    json_path = prefix + "synthetic.json"
    rows = (
        "000001|2026-09-15T00:00:00Z|synthetic|HASH|"
        + prefix
        + "synthetic.clixml|-|"
        + "A" * 64,
        "000002|2026-09-15T00:00:01Z|synthetic|HASH|"
        + json_path
        + "|-|"
        + "B" * 64,
    )
    assert json_path in _evaluate_capsule_recovery_selector(mutant_condition, rows)
    with pytest.raises(AssertionError):
        _assert_capsule_recovery_selector_is_clixml_only(mutant)


