def _task5_outer(ket, bra=None):
    bra = ket if bra is None else bra
    return ket * bra.conjugate().T


def _task5_dissipator(jump, rho):
    adjoint = jump.conjugate().T
    return sp.simplify(
        jump * rho * adjoint
        - (adjoint * jump * rho + rho * adjoint * jump) / 2
    )


def _task5_rhs(rho, hamiltonian, jumps):
    result = -sp.I * (hamiltonian * rho - rho * hamiltonian)
    for jump in jumps:
        result += _task5_dissipator(jump, rho)
    return sp.simplify(result)


def _task5_l1(rho):
    dimension = rho.rows
    return sp.simplify(sum(
        sp.Abs(rho[i, j])
        for i in range(dimension)
        for j in range(dimension)
        if i != j
    ))


def _task5_cpsi(rho):
    dimension = rho.rows
    assert dimension == 4
    denominator = dimension - 1
    assert denominator == 3
    return sp.simplify(sp.trace(rho * rho) * _task5_l1(rho) / denominator)


def _task5_assert_density(rho):
    assert rho == rho.conjugate().T
    assert sp.simplify(sp.trace(rho)) == 1
    assert all(eigenvalue.is_nonnegative is True for eigenvalue in rho.eigenvals())


def _task5_directional_tuple(rho, rho_dot):
    dimension = rho.rows
    purity = sp.simplify(sp.trace(rho * rho))
    l1 = _task5_l1(rho)
    purity_dot = sp.simplify(2 * sp.re(sp.trace(rho * rho_dot)))
    l1_dot = 0
    for i in range(dimension):
        for j in range(dimension):
            if i == j:
                continue
            if rho[i, j] == 0:
                # Keep the l1 directional derivative differentiable: none of
                # these three exact germs may create a new coherence at t=0.
                assert sp.simplify(rho_dot[i, j]) == 0
            else:
                l1_dot += sp.re(
                    sp.conjugate(rho[i, j]) * rho_dot[i, j]
                ) / sp.Abs(rho[i, j])
    l1_dot = sp.simplify(l1_dot)
    cpsi_dot = sp.simplify((purity_dot * l1 + purity * l1_dot) / 3)
    return purity_dot, l1_dot, cpsi_dot


def _task5_pointwise_fixture():
    identity = sp.eye(2)
    x = sp.Matrix([[0, 1], [1, 0]])
    y = sp.Matrix([[0, -sp.I], [sp.I, 0]])
    z = sp.diag(1, -1)
    zero = sp.zeros(4)
    ket0 = sp.Matrix([1, 0])
    projector0 = _task5_outer(ket0)
    rho1 = (identity + x / 2 + z / 2) / 2
    rho = sp.kronecker_product(rho1, projector0)
    hamiltonian = sp.kronecker_product(y, identity)
    z_first = sp.kronecker_product(z, identity)
    gamma_first = sp.Rational(1, 4)
    assert gamma_first == sp.Rational(1, 4)
    dephasing_jump = z_first / 2
    return identity, x, z, projector0, rho, hamiltonian, zero, z_first, dephasing_jump


def _task5_assert_positive_pointwise_germ(rho, hamiltonian, dephasing_jump):
    rho_dot = _task5_rhs(rho, hamiltonian, (dephasing_jump,))
    exact = _task5_directional_tuple(rho, rho_dot)
    assert exact == (
        sp.Rational(-1, 8),
        sp.Rational(3, 4),
        sp.Rational(1, 6),
    )


def test_monotonicity_exact_pointwise_counterexample_and_h_zero_mutation():
    _, _, _, _, rho, hamiltonian, zero, _, jump = _task5_pointwise_fixture()
    _task5_assert_density(rho)
    assert _task5_cpsi(rho) == sp.Rational(1, 8)
    _task5_assert_positive_pointwise_germ(rho, hamiltonian, jump)

    h_zero_tuple = _task5_directional_tuple(rho, _task5_rhs(rho, zero, (jump,)))
    assert h_zero_tuple == (
        sp.Rational(-1, 8),
        sp.Rational(-1, 4),
        sp.Rational(-1, 12),
    )
    with pytest.raises(AssertionError):
        _task5_assert_positive_pointwise_germ(rho, zero, jump)


def test_monotonicity_hadamard_change_and_same_lab_h_z_pulse_are_exact():
    identity, x, z, projector0, rho, hamiltonian, _, z_first, jump = (
        _task5_pointwise_fixture()
    )
    rho00 = sp.kronecker_product(projector0, projector0)
    hadamard = (x + z) / sp.sqrt(2)
    local_hadamard = sp.kronecker_product(hadamard, identity)
    after_hadamard = sp.simplify(local_hadamard * rho00 * local_hadamard.conjugate().T)
    _task5_assert_density(after_hadamard)
    assert _task5_cpsi(rho00) == 0
    assert _task5_cpsi(after_hadamard) == sp.Rational(1, 3)

    pulsed = sp.simplify(z_first * rho * z_first)
    assert _task5_cpsi(pulsed) == sp.Rational(1, 8)
    active_tuple = _task5_directional_tuple(
        pulsed, _task5_rhs(pulsed, hamiltonian, (jump,))
    )
    assert active_tuple == (
        sp.Rational(-1, 8),
        sp.Rational(-5, 4),
        sp.Rational(-1, 3),
    )
    passive_hamiltonian = sp.simplify(z_first * hamiltonian * z_first)
    passive_tuple = _task5_directional_tuple(
        pulsed, _task5_rhs(pulsed, passive_hamiltonian, (jump,))
    )
    assert passive_tuple == (
        sp.Rational(-1, 8),
        sp.Rational(3, 4),
        sp.Rational(1, 6),
    )


def _task5_liouvillian_nullity(dimension, jumps):
    columns = []
    for i in range(dimension):
        for j in range(dimension):
            basis = sp.zeros(dimension)
            basis[i, j] = 1
            columns.append(sp.Matrix(list(_task5_rhs(basis, sp.zeros(dimension), jumps))))
    return len(sp.Matrix.hstack(*columns).nullspace())


def _task5_assert_unique_stationary_target(first_jump, second_jump, target, expected_cpsi):
    _task5_assert_density(target)
    assert _task5_dissipator(first_jump, target) == sp.zeros(4)
    assert _task5_dissipator(second_jump, target) == sp.zeros(4)
    assert _task5_liouvillian_nullity(4, (first_jump, second_jump)) == 1
    assert _task5_cpsi(target) == expected_cpsi


def test_absorber_local_markov_stationary_state_and_axis_mutation_are_exact():
    identity = sp.eye(2)
    ket0 = sp.Matrix([1, 0])
    ket1 = sp.Matrix([0, 1])
    plus = (ket0 + ket1) / sp.sqrt(2)
    minus = (ket0 - ket1) / sp.sqrt(2)
    projector0 = _task5_outer(ket0)
    coherent_axis_jump = sp.kronecker_product(_task5_outer(plus, minus), identity)
    second_jump = sp.kronecker_product(identity, _task5_outer(ket0, ket1))
    rho_star = sp.kronecker_product(_task5_outer(plus), projector0)
    _task5_assert_unique_stationary_target(
        coherent_axis_jump, second_jump, rho_star, sp.Rational(1, 3)
    )

    computational_axis_jump = sp.kronecker_product(_task5_outer(ket0, ket1), identity)
    rho00 = sp.kronecker_product(projector0, projector0)
    assert _task5_rhs(rho00, sp.zeros(4), (computational_axis_jump, second_jump)) == sp.zeros(4)
    assert _task5_cpsi(rho00) == 0
    with pytest.raises(AssertionError):
        _task5_assert_unique_stationary_target(
            computational_axis_jump, second_jump, rho00, sp.Rational(1, 3)
        )


def _task5_rank_one_damping_state(target, source, initial, q):
    assert sp.simplify((target.conjugate().T * target)[0]) == 1
    assert sp.simplify((source.conjugate().T * source)[0]) == 1
    assert sp.simplify((target.conjugate().T * source)[0]) == 0
    aa = sp.simplify((target.conjugate().T * initial * target)[0])
    ab = sp.simplify((target.conjugate().T * initial * source)[0])
    ba = sp.simplify((source.conjugate().T * initial * target)[0])
    bb = sp.simplify((source.conjugate().T * initial * source)[0])
    return sp.simplify(
        (aa + (1 - q) * bb) * _task5_outer(target)
        + q * bb * _task5_outer(source)
        + sp.sqrt(q) * ab * _task5_outer(target, source)
        + sp.sqrt(q) * ba * _task5_outer(source, target)
    )


def _task5_cpsi_on_open_unit_interval(rho, q):
    l1 = sp.simplify(sum(
        sp.refine(sp.Abs(rho[i, j]), sp.Q.lt(q, 1))
        for i in range(rho.rows)
        for j in range(rho.cols)
        if i != j
    ))
    return sp.factor(sp.trace(rho * rho) * l1 / 3)


def _task5_assert_exact_upward_crossing_for_axis(target, source):
    # q=e^(-t), so d/dt = -q d/dq for the unit-rate local semigroup.
    t = sp.symbols("t", nonnegative=True)
    q_of_t = sp.exp(-t)
    assert sp.diff(q_of_t, t) == -q_of_t
    q = sp.symbols("q", positive=True)
    identity = sp.eye(2)
    ket0 = sp.Matrix([1, 0])
    ket1 = sp.Matrix([0, 1])
    projector0 = _task5_outer(ket0)
    rho00 = sp.kronecker_product(projector0, projector0)
    first_jump = sp.kronecker_product(_task5_outer(target, source), identity)
    second_jump = sp.kronecker_product(identity, _task5_outer(ket0, ket1))
    rho_first = _task5_rank_one_damping_state(target, source, projector0, q)
    rho_q = sp.kronecker_product(rho_first, projector0)
    assert sp.simplify(rho_q.subs(q, 1) - rho00) == sp.zeros(4)
    _task5_assert_density(rho_q.subs(q, sp.Rational(1, 8)))
    rhs = _task5_rhs(rho_q, sp.zeros(4), (first_jump, second_jump))
    assert sp.simplify(-q * rho_q.diff(q) - rhs) == sp.zeros(4)

    cpsi_q = _task5_cpsi_on_open_unit_interval(rho_q, q)
    expected = (1 - q) * (q ** 2 - q + 2) / 6
    assert sp.simplify(cpsi_q - expected) == 0
    rise_derivative = sp.factor(-q * sp.diff(cpsi_q, q))
    assert rise_derivative == q * (3 * q ** 2 - 4 * q + 3) / 6
    assert sp.discriminant(3 * q ** 2 - 4 * q + 3, q) == -20
    assert cpsi_q.subs(q, 1) == 0
    assert cpsi_q.subs(q, sp.Rational(1, 8)) == sp.Rational(847, 3072)
    assert sp.Rational(847, 3072) - sp.Rational(1, 4) == sp.Rational(79, 3072)
    assert cpsi_q.subs(q, 0) == sp.Rational(1, 3)
    return cpsi_q


def test_absorber_exact_upward_crossing_from_below_under_fixed_local_semigroup():
    q = sp.symbols("q", positive=True)
    identity = sp.eye(2)
    ket0 = sp.Matrix([1, 0])
    ket1 = sp.Matrix([0, 1])
    plus = (ket0 + ket1) / sp.sqrt(2)
    minus = (ket0 - ket1) / sp.sqrt(2)
    projector0 = _task5_outer(ket0)

    coherent_curve = _task5_assert_exact_upward_crossing_for_axis(plus, minus)
    assert coherent_curve.subs(q, sp.Rational(1, 8)) == sp.Rational(847, 3072)

    # The mutated axis generates the stationary |00><00| curve itself; it never crosses upward.
    mutated_first = _task5_rank_one_damping_state(ket0, ket1, projector0, q)
    mutated_rho = sp.kronecker_product(mutated_first, projector0)
    mutated_curve = _task5_cpsi_on_open_unit_interval(mutated_rho, q)
    assert mutated_rho == sp.kronecker_product(projector0, projector0)
    assert mutated_curve == 0
    assert mutated_curve.subs(q, sp.Rational(1, 8)) < sp.Rational(1, 4)
    with pytest.raises(AssertionError):
        _task5_assert_exact_upward_crossing_for_axis(ket0, ket1)


