_TASK5_EXPECTED_DIRECT_PARENT_PROPERTIES = [
    ("F25", "F25CPsiBellPlusPi2Inheritance"),
    ("Quarter", "QuarterAsBilinearMaxvalClaim"),
]


def _task5_direct_parent_property_pairs(claim_source):
    property_pattern = re.compile(
        r"public\s+(?!static\b)"
        r"(?P<type>[A-Za-z_]\w*(?:Claim|Inheritance))\s+"
        r"(?P<name>[A-Za-z_]\w*)\s*"
        r"(?:\{\s*get;\s*\}|=>)"
    )
    return sorted(
        (match.group("name"), match.group("type"))
        for match in property_pattern.finditer(claim_source)
    )


def _task5_assert_exact_direct_parent_properties(claim_source):
    properties = _task5_direct_parent_property_pairs(claim_source)
    assert len(properties) == 2
    assert properties == _TASK5_EXPECTED_DIRECT_PARENT_PROPERTIES


def test_envelope_direct_parent_guards_are_exact_and_not_transitive():
    claim = read_host("compute/RCPsiSquared.Core/Symmetry/CpsiEnvelopeTheoremClaim.cs")
    core_tests = read_host(
        "compute/RCPsiSquared.Core.Tests/Symmetry/CpsiEnvelopeTheoremClaimTests.cs"
    )
    runtime_tests = read_host(
        "compute/RCPsiSquared.Runtime.Tests/PolarityArchitecture/"
        "CpsiEnvelopeTheoremClaimRegistrationTests.cs"
    )

    _task5_assert_exact_direct_parent_properties(claim)
    f25_property = "public F25CPsiBellPlusPi2Inheritance F25 { get; }"
    assert claim.count(f25_property) == 1
    alias_mutation = claim.replace(
        f25_property,
        f25_property + "\n    public F25CPsiBellPlusPi2Inheritance F25Alias => F25;",
        1,
    )
    mutated_properties = _task5_direct_parent_property_pairs(alias_mutation)
    legacy_type_set = {property_type for _, property_type in mutated_properties}
    assert legacy_type_set == {
        "F25CPsiBellPlusPi2Inheritance",
        "QuarterAsBilinearMaxvalClaim",
    }
    with pytest.raises(AssertionError):
        _task5_assert_exact_direct_parent_properties(alias_mutation)

    direct_parent_test = core_tests.split(
        "public void Claim_PublicDirectParentProperties_AreExactlyF25AndQuarter()", 1
    )[1].split("[Fact]", 1)[0]
    assert ".ToHashSet()" not in direct_parent_test
    assert "BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly" in core_tests
    assert "typeof(Claim).IsAssignableFrom(property.PropertyType)" in core_tests
    assert "PropertyInfo[] directParents = typeof(CpsiEnvelopeTheoremClaim)" in direct_parent_test
    assert "Assert.Equal(2, directParents.Length);" in direct_parent_test
    assert "(Name: property.Name, PropertyType: property.PropertyType)" in direct_parent_test
    assert ".OrderBy(parent => parent.Name, StringComparer.Ordinal)" in direct_parent_test
    assert '(Name: "F25", PropertyType: typeof(F25CPsiBellPlusPi2Inheritance))' in direct_parent_test
    assert '(Name: "Quarter", PropertyType: typeof(QuarterAsBilinearMaxvalClaim))' in direct_parent_test
    assert "Assert.Equal(expected, actual);" in direct_parent_test
    assert "directParentTypes" not in direct_parent_test
    assert "EdgesInto<CpsiEnvelopeTheoremClaim>()" in runtime_tests
    assert "AncestorsOf<CpsiEnvelopeTheoremClaim>()" not in runtime_tests
    assert "Assert.Equal(2, directParentTypes.Count);" in runtime_tests


