def _task5_assert_named_01_solution(a, v, j, gamma, t):
    """Gate the displayed solution through the ODE that owns its coefficient."""
    assert sp.simplify(a.subs(t, 0) - 1) == 0
    assert sp.simplify(v.subs(t, 0)) == 0
    assert sp.simplify(sp.diff(a, t) + 4 * j * v) == 0
    assert sp.simplify(sp.diff(v, t) + 4 * gamma * v + 2 * j * (1 - 2 * a)) == 0


def test_task5_named_01_exact_solution_uses_two_gamma_over_omega_and_mutates_through_ode():
    j, gamma, t = sp.symbols("J gamma t", positive=True)
    omega = 2 * sp.sqrt(4 * j ** 2 - gamma ** 2)
    v = (
        j / sp.sqrt(4 * j ** 2 - gamma ** 2)
        * sp.exp(-2 * gamma * t)
        * sp.sin(omega * t)
    )
    exact_a = sp.Rational(1, 2) + sp.Rational(1, 2) * sp.exp(-2 * gamma * t) * (
        sp.cos(omega * t) + 2 * gamma / omega * sp.sin(omega * t)
    )
    _task5_assert_named_01_solution(exact_a, v, j, gamma, t)

    stale_a = sp.Rational(1, 2) + sp.Rational(1, 2) * sp.exp(-2 * gamma * t) * (
        sp.cos(omega * t) + gamma / omega * sp.sin(omega * t)
    )
    assert sp.simplify(sp.diff(stale_a, t).subs(t, 0)) == -gamma / 2
    with pytest.raises(AssertionError):
        _task5_assert_named_01_solution(stale_a, v, j, gamma, t)

    proof = read_host("docs/proofs/PROOF_MONOTONICITY_CPSI.md")
    part4 = proof.split("## Part 4:", 1)[1].split("## Part 5:", 1)[0]
    assert "a(t) = 1/2 + (1/2)e^{-2γt}[cos(ωt) + (2γ/ω)sin(ωt)]" in part4
    assert "extra (γ/ω)" not in part4


def _task5_real_and_physical_roots(c, psi):
    if c == 0:
        return [sp.Integer(0)], [sp.Integer(0)]
    discriminant = sp.simplify(1 - 4 * c * psi)
    if discriminant < 0:
        return [], []
    roots = [
        sp.simplify((1 - 2 * c * psi - sp.sqrt(discriminant)) / (2 * c)),
        sp.simplify((1 - 2 * c * psi + sp.sqrt(discriminant)) / (2 * c)),
    ]
    physical = [root for root in roots if 0 <= root <= 1]
    return roots, physical


