def _task5_assert_period_two_algebra(iterate):
    z, c = sp.symbols("z c", real=True)
    fixed_factor = sp.expand(iterate(z, c) - z)
    second_iterate = sp.expand(iterate(iterate(z, c), c) - z)
    period_two_factor = sp.cancel(second_iterate / fixed_factor)

    expected_nonfixed = z**2 + z + c + 1
    assert sp.expand(
        second_iterate - fixed_factor * expected_nonfixed
    ) == 0
    assert sp.expand(period_two_factor - expected_nonfixed) == 0

    discriminant = sp.discriminant(period_two_factor, z)
    assert discriminant == -4 * c - 3
    assert sp.solve_univariate_inequality(discriminant >= 0, c) == (
        c <= -sp.Rational(3, 4)
    )

    roots = sp.solve(period_two_factor, z)
    multiplier = sp.simplify(4 * roots[0] * roots[1])
    assert multiplier == 4 * (c + 1)
    stable_window = sp.solve_univariate_inequality(sp.Abs(multiplier) < 1, c)
    assert stable_window.as_set() == sp.Interval.open(
        -sp.Rational(5, 4), -sp.Rational(3, 4)
    )


