def _task5_coordinate_shape_scalar(metric, coordinate):
    return sp.simplify(
        -sp.diff(sp.log(metric), coordinate, 2) / (2 * metric)
    )


def _task5_intrinsic_riemann_scalar_1d(metric, coordinate):
    christoffel = sp.simplify(sp.diff(metric, coordinate) / (2 * metric))
    ricci_11 = sp.simplify(
        sp.diff(christoffel, coordinate)
        - sp.diff(christoffel, coordinate)
        + christoffel**2
        - christoffel**2
    )
    return sp.simplify(ricci_11 / metric)


def _task5_assert_flat_line_reparameterization(x_of_y):
    x, y = sp.symbols("x y", positive=True)
    g_x = sp.Integer(1)
    g_y = sp.simplify(sp.diff(x_of_y, y) ** 2)

    assert _task5_intrinsic_riemann_scalar_1d(1 + x**2, x) == 0
    assert _task5_coordinate_shape_scalar(g_x, x) == 0
    assert g_y == 1 / (4 * y)
    assert _task5_coordinate_shape_scalar(g_y, y) == -2 / y
    assert _task5_coordinate_shape_scalar(g_y, y).subs(y, 1) == -2


