def mutate_real_local_surface(path, source, sentence, surface):
    if path.endswith(".py"):
        tree = ast.parse(source)
        if surface == "docstring":
            node = tree.body[0]
            assert isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)
            node.value.value = sentence
        else:
            # Mutate a literal actually consumed by a plotting/text call. Its
            # remaining source and numerical expressions are preserved.
            names = {"suptitle", "set_title", "text", "text2D", "annotate"}
            calls = [n for n in ast.walk(tree) if isinstance(n, ast.Call)
                     and isinstance(n.func, ast.Attribute) and n.func.attr in names]
            call = next(n for n in calls if any(isinstance(a, ast.Constant)
                        and isinstance(a.value, str) for a in n.args))
            literal = next(a for a in call.args if isinstance(a, ast.Constant)
                           and isinstance(a.value, str))
            literal.value = sentence
        return ast.unparse(ast.fix_missing_locations(tree))
    if surface == "alt":
        altered, count = re.subn(r"!\[[\s\S]*?\]\(", lambda _: "!["+sentence+"](",
                                 source, count=1)
        assert count == 1
        return altered
    paragraphs = source.split("\n\n")
    index = next(i for i,p in enumerate(paragraphs) if p.startswith("We met "))
    paragraphs[index] = sentence
    return "\n\n".join(paragraphs)


@pytest.mark.parametrize("path", WHIRLPOOL_HOSTS)
@pytest.mark.parametrize("rule,sentence", MUTATIONS)
def test_real_whirlpool_local_mutations_cannot_hide_behind_caveat(path, rule, sentence):
    source = read_host(path)
    surfaces = ("docstring", "caption") if path.endswith(".py") else ("paragraph", "alt")
    for surface in surfaces:
        mutant = mutate_real_local_surface(path, source, sentence, surface)
        # A true statement elsewhere must not rescue the contradictory local assertion.
        if path.endswith(".py"):
            mutant += "\n# Bell+ remains entangled at every finite time.\n"
        else:
            mutant += "\n\nBell+ remains entangled at every finite time.\n"
        findings = semantic_findings(path, mutant)
        assert any(f":{rule}:" in finding and sentence in finding for finding in findings)


