def task6_local_story_findings(path, source):
    contract = TASK6_LOCAL_STORY_CONTRACTS[path]
    flattened = re.sub(r"\s+", " ", source)
    findings = []
    for required in contract["required"]:
        if required.lower() not in flattened.lower():
            findings.append(f"{path}: missing local positive control: {required}")
    for label, pattern in contract["forbidden"]:
        if re.search(pattern, flattened, re.I):
            findings.append(f"{path}: restored local overclaim: {label}")
    return tuple(findings)


