def current_truth_findings(tmp_path):
    buckets = defaultdict(list)
    for path in QUARTER_DYNAMICS_HOSTS:
        if not (ROOT / path).is_file():
            buckets["API_CLAIM_SCOPE"].append(f"{path}: required host is absent")
            continue
        source = read_host(path)
        buckets["CURRENT_LABEL"].extend(semantic_findings(path, source))
        # Every retained host needs an explicit positive local current reading.
        if path == "simulations/results/dimension_field_interior.txt":
            # This is a deterministic CLI tree capture, not authored prose.  Its
            # frozen writer contract starts with the rendered object title, so
            # classify it through the object-specific positive contract below
            # instead of inventing a QUARTER-CURRENT preamble the writer cannot
            # reproduce.
            buckets["CURRENT_LABEL"].extend(interior_capture_scope_findings(path, source))
        elif path.endswith((".md", ".txt")):
            buckets["CURRENT_LABEL"].extend(quarter_region_scope_findings(path, source))
    for path in WHIRLPOOL_HOSTS:
        buckets["CURRENT_LABEL"].extend(positive_whirlpool_scope_findings(path, read_host(path)))
    for path in COMMIT_A_IMPORT_SAFE_WRITERS + (
            "simulations/theta_palindrome_echo.py", "simulations/axis_modes.py"):
        buckets["IMPORT_SAFETY"].extend(import_safety_findings(path, read_host(path)))
    f95 = read_host(F95_SOURCE)
    if re.search(r"class F95AngleAtQuadraticZeroPi2Inheritance\s*:\s*Claim,\s*IZ2AxisClaim", f95):
        buckets["API_CLAIM_SCOPE"].append(f"{F95_SOURCE}: F95 still implements IZ2AxisClaim")
    for parent in ("PolynomialFoundationClaim", "HalfAsStructuralFixedPointClaim",
                   "QuarterAsBilinearMaxvalClaim", "NinetyDegreeMirrorMemoryClaim"):
        if re.search(r"public\s+"+parent+r"\s+\w+\s*\{\s*get;", f95):
            buckets["API_CLAIM_SCOPE"].append(f"{F95_SOURCE}: unsupported typed parent {parent}")
    pairing = read_host("simulations/pairing_structure.py")
    names = {n.name for n in ast.parse(pairing).body if isinstance(n, ast.FunctionDef)}
    if not {"f1_partner", "maximum_cardinality_f1_match"} <= names:
        buckets["API_CLAIM_SCOPE"].append("simulations/pairing_structure.py: missing shared holomorphic multiset matcher")
    else:
        copied = source_copy_definitions(pairing, {"f1_partner", "maximum_cardinality_f1_match"}, tmp_path,
            prelude="import numpy as np\nfrom scipy.sparse import csr_matrix\nfrom scipy.sparse.csgraph import maximum_bipartite_matching\n")
        for values, sigma, tolerance, expected in F1_CASES:
            actual = copied["maximum_cardinality_f1_match"](values, sigma, tolerance)
            if actual != expected:
                buckets["API_CLAIM_SCOPE"].append(f"F1 matcher sigma={sigma} tol={tolerance}: {actual} != {expected}")
    for artifact, producer in RENDER_PRODUCERS.items():
        source = read_host(producer)
        if not explicit_output_seam(source):
            buckets["ARTIFACT_PROVENANCE"].append(f"{artifact}: {producer} lacks explicit temporary output seam")
        if semantic_findings(producer, source):
            buckets["ARTIFACT_PROVENANCE"].append(f"{artifact}: generating source retains unsupported local labels")
        # Read every frame; dimensions, duration and RGBA bytes define the image
        # object, independently of PNG/GIF container metadata.
        from PIL import Image, ImageSequence
        with Image.open(ROOT / artifact) as img:
            frames = tuple((frame.size, frame.info.get("duration", 0),
                            hashlib.sha256(frame.convert("RGBA").tobytes()).hexdigest())
                           for frame in ImageSequence.Iterator(img))
        if not frames or any(w <= 0 or h <= 0 for (w,h), _, _ in frames):
            buckets["ARTIFACT_PROVENANCE"].append(f"{artifact}: empty normalized raster")
    captured = ("simulations/results/born_rule_shadow.txt", "simulations/results/subsystem_crossing.txt",
                "simulations/results/rescued_arcs_menu.txt", "simulations/results/theta_palindrome_echo.txt",
                "simulations/results/both_sides_visible.txt", "simulations/results/ibm_q98_crossing_pattern.txt")
    for path in captured:
        source = read_host(path)
        if not re.search(r"current.reading|QUARTER-CURRENT", source, re.I):
            buckets["ARTIFACT_PROVENANCE"].append(f"{path}: captured historical payload lacks current-reading wrapper")
    return buckets


def test_red_contract_has_no_current_truth_findings(tmp_path):
    fail_red_contract("RED_CONTRACT_CURRENT_TRUTH", current_truth_findings(tmp_path))


def interior_capture_scope_findings(path, source):
    text = re.sub(r"\s+", " ", source).lower()
    findings = []
    required = {
        "recurrence-coordinate title": "interiorhorizonfield (recurrence coordinate near ¼",
        "fixed stopping rule": "fixed stopping rule",
        "separate setup reading": "separate setup-specific reading",
        "non-regime marks": "not state-regime labels",
        "complex-root coordinate": "complex-root coordinate",
        "two-real-root coordinate": "two-real-root side",
        "finite Kingston comparison": "saved kingston rows report finite crossings",
        "non-isolated hardware cause": "does not isolate the cause",
        "no recurrence/Liouvillian identity": "neither the scalar crossing nor that association identifies a recurrence root with a liouvillian mode",
    }
    for label, phrase in required.items():
        if phrase not in text:
            findings.append(f"{path}: missing {label}")
    forbidden = {
        "time-stops mechanism": "time stops",
        "quantum/classical regime split": "the compass on the quantum side",
        "structural-horizon label": "structural horizon",
        "blanket Kingston confirmation": "kingston-confirmed",
        "hardware-observed scalar marks": "hardware-observed",
    }
    for label, phrase in forbidden.items():
        if phrase in text:
            findings.append(f"{path}: retains {label}")
    return tuple(findings)


def test_task8_interior_capture_uses_its_deterministic_tree_contract():
    path = "simulations/results/dimension_field_interior.txt"
    raw = (ROOT / path).read_bytes()
    assert not raw.startswith(b"\xef\xbb\xbf")
    assert b"\r" not in raw
    assert raw.endswith(b"\n") and not raw.endswith(b"\n\n")
    assert b"# MKL:" not in raw and b"\x1b" not in raw
    source = raw.decode("utf-8")
    assert source.startswith("InteriorHorizonField ")
    assert "[curve[" in source
    assert not interior_capture_scope_findings(path, source)


