TASK8_EQ021_METADATA_KEYS = {"current_reading", "evidence_scope", "provenance"}
TASK8_EQ021_SUMMARY = "simulations/results/eq021_mode_decomposition/decomposition_summary.txt"
TASK8_EQ021_SUMMARY_SHA256 = "C42690F97845088948EFFF38BC2D3AF38E79B193D0F168DF6C442D571F409B34"


def task8_eq021_payload_digest(document):
    payload = {key: value for key, value in document.items()
               if key not in TASK8_EQ021_METADATA_KEYS}
    canonical = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest().upper()


@pytest.mark.parametrize("path,expected", TASK8_EQ021_CAPTURED_JSON.items())
def test_task8_eq021_json_keeps_numeric_payload_beneath_current_metadata(path, expected):
    document = json.loads((ROOT / path).read_text(encoding="utf-8"))
    assert TASK8_EQ021_METADATA_KEYS <= set(document)
    assert "finite" in document["current_reading"].lower()
    scope = document["evidence_scope"].lower()
    assert "does not demonstrate convergence" in scope
    assert "not a prediction" in scope
    assert task8_eq021_payload_digest(document) == expected


def test_task8_eq021_json_contract_rejects_numeric_and_scope_mutations():
    path, expected = next(iter(TASK8_EQ021_CAPTURED_JSON.items()))
    document = json.loads((ROOT / path).read_text(encoding="utf-8"))
    numeric_mutant = json.loads(json.dumps(document))
    numeric_mutant["c_1_alpha_fit"] += 1e-6
    assert task8_eq021_payload_digest(numeric_mutant) != expected
    for key in TASK8_EQ021_METADATA_KEYS:
        mutant = json.loads(json.dumps(document))
        del mutant[key]
        assert not TASK8_EQ021_METADATA_KEYS <= set(mutant)


def task8_unwrap_eq021_summary(raw):
    assert not raw.startswith(b"\xef\xbb\xbf")
    assert b"\r" not in raw
    begin = b"=== BEGIN HISTORICAL NUMERIC BODY ===\n"
    end = b"=== END HISTORICAL NUMERIC BODY ===\n"
    assert raw.count(begin) == raw.count(end) == 1
    before, rest = raw.split(begin, 1)
    payload, after = rest.split(end, 1)
    assert after == b""
    current = before.decode("utf-8")
    assert current.startswith("QUARTER-CURRENT\n")
    assert "Current reading:" in current
    assert "finite N=4 and N=5" in current
    assert "does not demonstrate convergence" in current
    return payload


def test_task8_eq021_summary_preserves_exact_historical_numeric_body():
    raw = (ROOT / TASK8_EQ021_SUMMARY).read_bytes()
    payload = task8_unwrap_eq021_summary(raw)
    assert len(payload) == 351
    assert payload.count(b"\n") == 10
    assert hashlib.sha256(payload).hexdigest().upper() == TASK8_EQ021_SUMMARY_SHA256


def test_task8_eq021_summary_contract_rejects_payload_and_scope_mutations():
    raw = (ROOT / TASK8_EQ021_SUMMARY).read_bytes()
    payload = task8_unwrap_eq021_summary(raw)
    assert hashlib.sha256(payload.replace(b"+0.8979", b"+0.8978", 1)).hexdigest().upper() \
        != TASK8_EQ021_SUMMARY_SHA256
    with pytest.raises(AssertionError):
        task8_unwrap_eq021_summary(
            raw.replace(b"does not demonstrate convergence", b"predicts convergence", 1)
        )

