CROSSING_RELEVANT = re.compile(
    r"crossing.taxonomy|type[ -]?[abc]\b|observer.{0,65}(?:crossing|boundary)|"
    r"measurement event|crossing (?:is|event)|quantum.classical|"
    r"palindrom.{0,60}taxonomy|relay.{0,100}(?:improv|MI|stage|schedule)|"
    r"(?:K.?invarian|\bF14\b|gamma\s*[*×·]\s*t\b|γ\s*[*×·]?\s*t\b|K/gamma)",
    re.I,
)
# A coordinated noun list is recognized as a complete negative proposition;
# it never supplies an exemption to a different later proposition.
RELAY_NEGATIVE_ITEM = (
    r"(?:current\s+)?(?:matched[- ]time(?:/dose)?(?:\s+or\s+matched[- ]dose)?\s+comparison|"
    r"matched[- ]dose\s+comparison|isolated\s+(?:\+[\d.]+%\s+)?staging\s+(?:benefit|effect)|"
    r"isolated\s+mediator/order\s+benefit|optimized\s+(?:schedule|transfer\s+protocol)|"
    r"physical-observer\s+clock|MI\s+bound|gain|channel\s+bound|optimization|schedule\s+optimum|"
    r"palindrome(?:-based)?\s+timing(?:\s+claim)?)"
)
RELAY_NEGATIVE_PROPOSITION = (
    r"(?:No|not\s+an?)\s+"+RELAY_NEGATIVE_ITEM+
    r"(?:\s*(?:,\s*(?:or\s+|and\s+)?|\s+or\s+|\s+and\s+)"+RELAY_NEGATIVE_ITEM+r")*"
)
CROSSING_BAD = {
    "OBSERVER_EVENT": r"(?:crossing(?: event)?\s+(?:is|marks|constitutes)\s+(?:(?:an?|the)\s+)?(?:measurement(?:\s+event)?|(?:physical|observable)\s+event|handshake|delivery|message|synchronization|detectable\s+click)|different observers?\b.{0,30}different realit(?:y|ies)|both\s+separated\s+observers\s+see\s+(?:the\s+)?crossing)",
    "ADDITIVE_COLLECTIVE_EQUIVALENCE": r"Z\s*⊗\s*I\s*\+\s*I\s*⊗\s*Z\s+is\s+(?:mathematically\s+)?equivalent\s+to\s+two\s+independent\s+local\s+Z\s+jumps",
    "PALINDROME_TAXONOMY": r"(?:palindrom.{0,110}(?:causes?|explains?|preserves?|determines?|induces?).{0,30}taxonomy|taxonomy.{0,80}consequence.{0,50}palindrom)",
    "NOISE_UNIVERSAL": r"jump.operator independent|identical under all three Pauli|span all single.qubit noise|any local single.qubit noise preserves|taxonomy is preserved, but decay rates differ|taxonomy[^.!?\n]{0,60}holds? for every local noise channel|X, Y and Z[^.!?\n]{0,30}exhaust all one.qubit noise processes|taxonomy[^.!?\n]{0,40}independent of (?:the )?jump operator|all Pauli channels[^.!?\n]{0,40}same taxonomy",
    "RELAY_COMPARISON": r"Relay[^.!?\n]{0,120}(?:matched in time|(?:equal|matched) (?:dose|exposure)|(?:upper |lower )?bound on mutual information|schedule[^.!?\n]{0,20}(?:optimal|optimized)|timing[^.!?\n]{0,30}derived from[^.!?\n]{0,25}palindromic spectrum|staging (?:benefit|effect)[^.!?\n]{0,20}isolated)",
    "RELAY_CAUSAL": RELAY_NEGATIVE_PROPOSITION+r"|(?:staging gives|staging effect|MI bound|natural timescale|full standing.wave period|purely spatial|complementary optimizations)",
    "RELAY_TIMING": r"(?:actually (?:integrated|executed)\s+0\.78(?:\s+per stage|/stage)?|(?:schedule|timing)[^.!?\n]{0,35}(?:derived from|follows from|determined by|set by)[^.!?\n]{0,30}palindrom(?:e|ic spectrum)|information[^.!?\n]{0,15}(?:must|has to|needs to)\s+cross\s+before[^.!?\n]{0,35}(?:scalar )?quarter equality|(?:logged|printed)\s+(?:t=)?4[.,]7\s+is[^.!?\n]{0,20}propagated time)",
    "F14_UNIVERSAL": r"(?:gamma.time|K.invariance|decoherence envelope).{0,40}model.independent|model.independent.{0,35}(?:gamma.time|K.invariance|decoherence envelope)|universal (?:gamma.t curve|curve|progress coordinate)|F14.extended|invariant under change of bridge|linear iff Markovian|Eigenstates of H.{0,70}no dynamics|K\s*=\s*γ\s*t.{0,50}invariant for every Hamiltonian|product of illumination and experience is always the same",
}


def crossing_local_fence(prefix, suffix="", matched=""):
    # A negation belongs to this clause/object, not any nearby word "No".
    if re.fullmatch(RELAY_NEGATIVE_PROPOSITION,matched,re.I):
        return True
    matched_clause = re.split(r"[.!?:;]\s+|\b(?:but|however|yet|and)\b", matched, flags=re.I)[-1]
    if re.search(r"\b(?:is|are|does|do|can)\s+(?:not|never)\s+(?:an?\s+)?(?:invariant|model.independent|measurement|experience|see|cause|explain|preserve|determine|induce|matched|receive|establish|optimal|optimized|derived|isolated|hold|exhaust|independent|have|equivalent|prove|provide|propagated)\b", matched_clause, re.I):
        return True
    if re.match(r"\s+is\s+not\s+(?:a\s+)?(?:current\s+)?claim\b", suffix, re.I):
        return True
    # The only pre-match denial allowed is an immediately attached determiner:
    # 'no MI bound', 'not a universal curve'. No search through preceding prose.
    attached = re.search(r"\b(?:not|never|no|neither|without)\s+(?:(?:a|an|any|current|physical|isolated|general|universal|matched|demonstrated)\s+)*$", prefix, re.I)
    retrospective_label = re.search(r"\bCalling(?:\s+it)?\s+(?:an?\s+)?$", prefix, re.I) and re.match(
        r"\s+is an? (?:untested |explicitly )?interpretation\b", suffix, re.I)
    return attached or retrospective_label


def crossing_scope_findings(path, source):
    """Validate local dispositions; a later disclaimer cannot classify earlier prose."""
    problems = []
    problems.extend(task4_crossing_only_positive_findings(path, source))
    problems.extend(task4_quality_scope_findings(path, source))
    if path == "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md":
        problems.extend(path+":"+finding for finding in task4_proposal_status_findings(source))
    if path == "experiments/BRIDGE_CLOSURE.md":
        problems.extend(task4_bridge_resource_comparison_findings(source))
    if path in TASK4_SOURCE_SURFACE_HASHES:
        problems.extend(task4_source_claim_surface_findings(path,source))
    if path not in TASK4_EDIT_HOSTS:
        return problems
    if path == "experiments/CRITICAL_SLOWING_AT_THE_CUSP.md":
        # Only this exact gloss is assigned; the rest is the Task6 object.
        if source.count(CUSP_CURRENT_GLOSS) != 1:
            problems.append(path + ":K-Dosimetry gloss:CUSP_K_DOSIMETRY_SCOPE")
        return problems
    if path.endswith((".py", ".cs")):
        units = local_units(path, source) if path.endswith(".py") else (
            (f"line:{i}", line) for i, line in enumerate(source.splitlines(), 1)
            if "//" in line or '"' in line)
        for location, text in units:
            for rule, pattern in CROSSING_BAD.items():
                for match in re.finditer(pattern, text, re.I):
                    prefix = text[:match.start()]
                    if not crossing_local_fence(prefix, text[match.end():], match.group()):
                        problems.append(f"{path}:{location}:{rule}:{match.group()}")
        return problems
    mode = None
    has_current = False
    for index, paragraph in enumerate(re.split(r"\n\s*\n", source)):
        marker = re.fullmatch(r"<!-- (?:CROSSING|F14)-(CURRENT|HISTORICAL|INTERPRETIVE) -->", paragraph.strip())
        if marker:
            mode = marker.group(1)
            has_current |= mode == "CURRENT"
            continue
        if not paragraph.strip() or paragraph.lstrip().startswith(("```", "<a id=")):
            continue
        relevant = CROSSING_RELEVANT.search(paragraph) or any(
            re.search(pattern, paragraph, re.I) for pattern in CROSSING_BAD.values())
        if not relevant:
            continue
        if mode is None:
            problems.append(f"{path}:paragraph:{index}:UNCLASSIFIED")
        elif mode == "HISTORICAL":
            # A visible banner must occur between the marker and the first claim.
            before = "\n\n".join(re.split(r"\n\s*\n", source)[:index+1])
            region = re.split(r"<!-- (?:CROSSING|F14)-HISTORICAL -->", before)[-1]
            if not re.search(r"Historical (?:nomenclature|record|reading):", region, re.I):
                problems.append(f"{path}:paragraph:{index}:MISSING_HISTORICAL_BANNER")
        elif mode == "INTERPRETIVE":
            before = "\n\n".join(re.split(r"\n\s*\n", source)[:index+1])
            region = re.split(r"<!-- (?:CROSSING|F14)-INTERPRETIVE -->", before)[-1]
            if "Interpretive invitation" not in region or "not a result" not in region:
                problems.append(f"{path}:paragraph:{index}:MISSING_INTERPRETIVE_BANNER")
        else:
            for rule, pattern in CROSSING_BAD.items():
                for match in re.finditer(pattern, paragraph, re.I):
                    prefix = paragraph[:match.start()]
                    if not crossing_local_fence(prefix, paragraph[match.end():], match.group()):
                        problems.append(f"{path}:paragraph:{index}:{rule}:{match.group()}")
    if not has_current:
        problems.append(f"{path}:missing local CROSSING-CURRENT/F14-CURRENT region")
    return problems


def test_task4_crossing_f14_relay_scope():
    findings = {p: crossing_scope_findings(p, read_host(p)) for p in TASK4_EDIT_HOSTS}
    assert not {p: rows for p, rows in findings.items() if rows}


def test_crossing_collective_jump_objects_are_distinct_exactly():
    z = sp.diag(1,-1)
    a, b = sp.kronecker_product(z,sp.eye(2)), sp.kronecker_product(sp.eye(2),z)
    rho = sp.Matrix([[sp.Rational(1,2),0,0,sp.Rational(1,2)],[0,0,0,0],
                     [0,0,0,0],[sp.Rational(1,2),0,0,sp.Rational(1,2)]])
    def dissipator(jump):
        square = jump.H*jump
        return jump*rho*jump.H-(square*rho+rho*square)/2
    product, collective, local = dissipator(a*b), dissipator(a+b), dissipator(a)+dissipator(b)
    assert product == sp.zeros(4)
    assert collective != local
    assert [sum(abs(x)**2 for x in matrix) for matrix in (product,collective,local)] == [0,32,8]


def test_f14_markovian_log_coherence_can_curve_exactly():
    x, y, z = sp.Matrix([[0,1],[1,0]]), sp.Matrix([[0,-sp.I],[sp.I,0]]), sp.diag(1,-1)
    rho = (sp.eye(2)+x/2+z/2)/2
    def derivatives(h):
        def generator(state):
            return -sp.I*(h*state-state*h)+(z*state*z-state)/4
        first, second = generator(rho), generator(generator(rho))
        l, dl, ddl = 2*rho[0,1], 2*first[0,1], 2*second[0,1]
        return dl/l, sp.simplify(ddl/l-(dl/l)**2)
    assert derivatives(y) == (sp.Rational(3,2), -7)
    assert derivatives(sp.zeros(2)) == (-sp.Rational(1,2), 0)


