def relay_stored_comparison():
    from decimal import Decimal
    source = read_host("simulations/results/pull_principle.txt")
    # Parse the retained production lines, never numbers in the current wrapper.
    passive = re.search(r"^  Passive:.*MI\(A:D\)=([0-9,.]+)", source, re.M).group(1)
    staged = re.search(r"^  Relay\+2:1.*MI\(A:D\)=([0-9,.]+)", source, re.M).group(1)
    values = tuple(Decimal(x.replace(",", ".")) for x in (passive, staged))
    assert values == (Decimal("0.071576"), Decimal("0.131700"))
    return values, 100*(values[1]/values[0]-1)


def relay_exposures():
    from decimal import Decimal as D
    n,gamma,quiet,nominal,dt,receivers = relay_clock_inputs(
        read_host("compute/RCPsiSquared.Propagate/Program.cs"))
    steps = int(nominal/dt)
    executed = steps*dt
    staged = sum(((n-len(sites))*gamma+len(sites)*quiet)*executed for sites in receivers)
    horizon=executed*len(receivers)
    return steps, executed, nominal*len(receivers), horizon, n*gamma*D("4.00"), staged, n*gamma*horizon


def test_task4_relay_decimal_books_are_distinct():
    from decimal import Decimal as D
    values, percent = relay_stored_comparison()
    assert format(percent, ".1f") == "84.0"
    assert relay_exposures() == (15,D("0.75"),D("4.68"),D("4.50"),D("2.200"),D("2.17125"),D("2.475"))
    assert D("1.3068") < 100*(1-D("2.17125")/D("2.200")) < D("1.3069")
    assert D("12.2727") < 100*(1-D("2.17125")/D("2.475")) < D("12.2728")
    assert values[0] != D("0.072")  # the old coarse display is not the denominator


