def task4_legacy_payload_findings(path, source):
    entry = next(row for row in TASK4_LEGACY_PAYLOADS if row[0] == path)
    _, first_line, count, expected = entry
    lines = source.rstrip("\n").splitlines()
    payload = "\n".join(lines[-count:])
    if (not payload.startswith(first_line+"\n")
            or hashlib.sha256(payload.encode()).hexdigest() != expected):
        return [path+":HISTORICAL_PAYLOAD_CHANGED"]
    return []


