def task4_compute_ownership_findings(source):
    findings=[]
    before, separator, after=source.partition("## Related standalone analyses (no Compute dependency)")
    if not separator:
        return ["COMPUTE_STANDALONE_HEADING"]
    table=before.split("| Experiment document | Uses Compute for |")[-1]
    for name in ("Crossing Taxonomy","Cavity Mode Localization"):
        if name in table:
            findings.append("COMPUTE_FALSE_DEPENDENCY:"+name)
    for producer in ("crossing_taxonomy_books.py","cavity_mode_localization.py"):
        if producer not in after:
            findings.append("COMPUTE_MISSING_PRODUCER:"+producer)
    return findings


