    assert len(task4_table_rows(source,"## 6.","## 6a."))-1==2
    assert len(task4_table_rows(source,"## 6a.","## 7."))-1==6
    assert "52 (39 rows in §2 + 13 finite J>0 rows in §9" in source
    assert "Universal noise independence" not in source.split("## 8b.",1)[1].split("## 9.",1)[0]
    assert "not a falsified" in source
    # Each edited J>0 row has exactly three columns; escaped ket bars are content.
    for row in task4_table_rows(source,"| Prediction | Result | Source |","## Summary"):
        assert len(re.split(r"(?<!\\)\|",row))==5,row


