def task4_region_parts(source):
    pattern=r"<!-- (?:CROSSING|F14)-(CURRENT|HISTORICAL|INTERPRETIVE) -->"
    parts=re.split(pattern,source)
    yield None,parts[0]
    for i in range(1,len(parts),2):
        yield parts[i],parts[i+1]


def task4_bridge_resource_comparison_findings(source):
    """No-signalling does not prove equivalence of quantum/classical resources."""
    pattern = (
        r"This document proves it|"
        r"(?:resource|pre.shared.key) comparison (?:is |was )?(?:proved|proven)|"
        r"entangled correlations (?:are|is) equivalent to shared classical randomness|"
        r"Quantum and classical pre.shared resources[^.!?\n]{0,30}equivalent|"
        r"No.signalling[^.!?\n]{0,25}proves?[^.!?\n]{0,40}shared randomness[^.!?\n]{0,20}sufficient|"
        r"Entanglement[^.!?\n]{0,25}provides? nothing beyond[^.!?\n]{0,20}pre.shared key"
    )
    findings = []
    for mode, block in task4_region_parts(source):
        if mode != "CURRENT":
            continue
        for match in re.finditer(pattern, block, re.I):
            if not crossing_local_fence(block[:match.start()], block[match.end():], match.group()):
                findings.append("experiments/BRIDGE_CLOSURE.md:RESOURCE_COMPARISON_PROOF:"+match.group())
    return findings


def test_task4_bridge_resource_comparison_is_not_proved_by_no_signalling():
    assert not task4_bridge_resource_comparison_findings(read_host("experiments/BRIDGE_CLOSURE.md"))


@pytest.mark.parametrize("slogan", (
    "The answer is **no**. This document proves it and closes the bridge hypothesis permanently.",
    "The resource comparison is proved.",
    "Entangled correlations are equivalent to shared classical randomness.",
))
def test_task4_bridge_resource_comparison_repromotion_fails_in_same_current_region(slogan):
    path = "experiments/BRIDGE_CLOSURE.md"
    source = read_host(path)
    anchor = "## 1. What This Document Settles"
    assert anchor in source
    mutant = source.replace(anchor, anchor+"\n\n"+slogan, 1)
    # Keep the real no-signalling and no-demonstrated-advantage positives intact.
    assert not task4_positive_scope_findings(path, mutant)
    assert any(":RESOURCE_COMPARISON_PROOF:" in f for f in crossing_scope_findings(path, mutant))


def test_task4_bridge_resource_comparison_explicit_denial_is_not_a_proof_claim():
    source = "<!-- CROSSING-CURRENT -->\n\nThe resource comparison is not proved. " \
             "Entangled correlations are not equivalent to shared classical randomness in general."
    assert not task4_bridge_resource_comparison_findings(source)


def task4_positive_scope_findings(path,source):
    problems=[]
    current="\n".join(block for mode,block in task4_region_parts(source) if mode=="CURRENT")
    for required in TASK4_POSITIVE_SCOPES.get(path,()):
        expected = 3 if (path,required)==("experiments/BRIDGE_CLOSURE.md","trace-preserving operation on B") else 1
        if current.count(required) != expected:
            problems.append(path+":MISSING_CURRENT_SCOPE:"+required)
    if path in TASK4_FULL_HOSTS:
        for mode,block in task4_region_parts(source):
            if mode is None and block.strip():
                problems.append(path+":UNCLASSIFIED_FULL_HOST_FRONT")
            if mode in ("HISTORICAL","INTERPRETIVE") and block.strip():
                required="Historical" if mode=="HISTORICAL" else "Interpretive invitation"
                if required not in block:
                    problems.append(path+":MISSING_VISIBLE_REGION_BANNER")
    return problems


@pytest.mark.parametrize("path",tuple(TASK4_POSITIVE_SCOPES))
def test_task4_positive_scope_and_full_host_classification(path):
    assert not task4_positive_scope_findings(path,read_host(path))


@pytest.mark.parametrize("path,required",tuple(
    (path,fragment) for path,fragments in TASK4_POSITIVE_SCOPES.items() for fragment in fragments))
def test_task4_deleting_one_positive_fact_cannot_be_hidden_by_other_fences(path,required):
    source=read_host(path)
    assert required in source
    mutant=source.replace(required,"[scope removed]",1)
    assert path+":MISSING_CURRENT_SCOPE:"+required in task4_positive_scope_findings(path,mutant)


@pytest.mark.parametrize("path",TASK4_FULL_HOSTS)
def test_task4_blank_current_plus_historical_whole_host_is_not_a_repair(path):
    source=read_host(path)
    source=re.sub(r"<!-- (?:CROSSING|F14)-(?:CURRENT|HISTORICAL|INTERPRETIVE) -->","",source)
    mutant=("<!-- CROSSING-CURRENT -->\n\n<!-- CROSSING-HISTORICAL -->\n\n"
            "Historical nomenclature: everything that follows.\n\n"+source)
    assert any("MISSING_CURRENT_SCOPE" in f for f in task4_positive_scope_findings(path,mutant))


