    ["simulations/gamma_unit_scaling_gate.py","# F14 (K = gamma * t_cross = constant) and GAMMA_TIME_DISTINCTION Part 3 @ HEAD:272","d4b03fd8111e43b5a8b8d7dde6496655520d32c7e151ff7f03cefc15c5915fea","F14/mixed","CURRENT","77f9430284056c551bac0318746444b2e138bd3521dd2bc5d7774c118a65ffc1","# F14 (K = gamma * t_cross = constant) and GAMMA_TIME_DISTINCTION Part 3"],
