F14_BLOCK_PATTERN = re.compile(
    r"(?<![A-Za-z0-9])F14(?![0-9])|K.?invarian|F14.extended|"
    r"universal[ -](?:curve|dial|gamma|progress coordinate)|"
    r"(?:K(?:_i)?\s*=.{0,60}(?:gamma|γ|\bt\b))|"
    r"(?:gamma|γ)\s*(?:times|[*×·])?\s*t\b|K\s*(?:\([^)]*\)|_\w+)?\s*/\s*(?:gamma|γ)|"
    r"\bK(?:_\w+)?\s+is\s+(?:γ|gamma)[ -]invariant|"
    r"depends? only on.{0,30}(?:gamma|γ)|linear iff Markovian|"
    r"nothing.{0,50}outrun|(?:xi|ξ).{0,40}(?:clock|linear)|"
    r"decoherence.clock|Hamiltonian.independent.{0,25}l1|"
    r"illumination.{0,50}(?:invariant|always the same)", re.I)


def f14_current_inventory(path,source):
    records=[]
    heading="front"
    mode="SOURCE" if path.endswith((".py",".cs")) else "UNCLASSIFIED"
    for line in source.splitlines():
        marker=re.fullmatch(r"<!-- (?:CROSSING|F14)-(CURRENT|HISTORICAL|INTERPRETIVE) -->",line.strip())
        if marker:
            mode=marker.group(1)
            continue
        if line.startswith("#"):
            heading=line
        if not F14_BLOCK_PATTERN.search(line) or line.startswith("<a id="):
            continue
        disposition=mode
        if path not in TASK4_EDIT_HOSTS:
            disposition="CONTROL"
        elif path=="experiments/CRITICAL_SLOWING_AT_THE_CUSP.md" and line not in CUSP_CURRENT_GLOSS.splitlines():
            disposition="CONTROL"  # user explicitly reserved the rest for Task6
        if path=="docs/ANALYTICAL_FORMULAS.md" and (
            line.startswith("(spectral, state-independent") or line.startswith("    Q_k = 2*J/gamma")):
            disposition="OTHER-OBJECT"  # F2b spectral Q and F7 Q spectrum, not F14 time
        records.append([path,heading,hashlib.sha256(line.encode()).hexdigest(),disposition])
    return records


def f14_block_inventory_findings(path,source):
    expected=[list(row) for row in F14_CURRENT_BLOCKS if row[0]==path]
    actual=f14_current_inventory(path,source)
    if actual!=expected:
        return [path+":F14_BLOCK_INVENTORY:new, missing, changed, or reclassified hit"]
    return []


def f14_required_current_findings(path,source):
    row=next((r for r in F14_REQUIRED_CURRENT_BLOCKS if r[0]==path),None)
    if row is None:
        return []
    _,fragment,_=row
    if path.endswith(".py"):
        current=ast.get_docstring(ast.parse(source)) or ""
    elif path.endswith(".cs") or path=="experiments/CRITICAL_SLOWING_AT_THE_CUSP.md":
        current=source
    else:
        current="\n".join(block for mode,block in task4_region_parts(source) if mode=="CURRENT")
    if fragment not in current:
        return [path+":F14_REQUIRED_CURRENT_SCOPE"]
    return []


def test_task4_frozen_original_lineage_is_complete_and_not_self_rebaselined():
    assert not task4_entry_lineage_findings(F14_ORIGINAL_BLOCKS)
    assert len(F14_ORIGINAL_BLOCKS)==395
    assert len(F14_CURRENT_BLOCKS)==328
    assert len(F14_REQUIRED_CURRENT_BLOCKS)==55
    assert sum(row[4]=="F14-OTHER-OBJECT" for row in F14_ORIGINAL_BLOCKS)==20
    current_scopes={row[0]:row[2] for row in F14_REQUIRED_CURRENT_BLOCKS}
    for path,anchor,digest,obj,disposition,required,fragment in F14_ORIGINAL_BLOCKS:
        assert "@ HEAD:" in anchor
        assert hashlib.sha256(fragment.encode()).hexdigest()==digest
        assert disposition in ("CURRENT","HISTORICAL","INTERPRETIVE","SOURCE","CONTROL","F14-OTHER-OBJECT","OTHER-OBJECT")
        if disposition=="F14-OTHER-OBJECT":
            assert obj!="F14/mixed" and required=="OTHER:"+obj
            assert not re.search(r"\bF14\b",fragment)
        elif path in current_scopes:
            assert required==current_scopes[path]
        else:
            assert required=="CONTROL:"+digest
    for _,fragment,digest in F14_REQUIRED_CURRENT_BLOCKS:
        assert hashlib.sha256(fragment.encode()).hexdigest()==digest


@pytest.mark.parametrize("path",F14_K_HOSTS)
def test_task4_every_bounded_f14_block_has_its_frozen_disposition(path):
    source=read_host(path)
    assert not f14_block_inventory_findings(path,source)
    assert not f14_required_current_findings(path,source)


def test_task10_f14_ptf_f65_anchor_restoration_fails_frozen_inventory():
    path="hypotheses/PERSPECTIVAL_TIME_FIELD.md"
    source=read_host(path)
    current=(
        "[F65](../docs/ANALYTICAL_FORMULAS.md#f65-single-excitation-spectrum-of-"
        "uniform-open-xx-chain-tier-1-proven-verified-n3-30) site-amplitudes"
    )
    stale=current.replace("verified-n3-30", "verified-n330")
    assert source.count(current)==1
    mutant=source.replace(current,stale,1)
    assert mutant!=source
    assert f14_block_inventory_findings(path,mutant)==[
        path+":F14_BLOCK_INVENTORY:new, missing, changed, or reclassified hit"
    ]


@pytest.mark.parametrize("path",tuple(row[0] for row in F14_REQUIRED_CURRENT_BLOCKS))
def test_task4_deleting_a_host_positive_scope_is_not_a_disposition(path):
    source=read_host(path)
    fragment=next(row[1] for row in F14_REQUIRED_CURRENT_BLOCKS if row[0]==path)
    if path.endswith(".py"):
        # Replace the module docstring via its exact source span, without importing.
        node=ast.parse(source).body[0]
        lines=source.splitlines(keepends=True)
        mutant="".join(lines[:node.lineno-1])+repr("scope deleted")+"\n"+"".join(lines[node.end_lineno:])
    else:
        assert fragment in source
        mutant=source.replace(fragment,"[scope deleted]",1)
    assert f14_required_current_findings(path,mutant)==[path+":F14_REQUIRED_CURRENT_SCOPE"]


@pytest.mark.parametrize("path",(
    "experiments/METRIC_DISCRIMINATION.md","hypotheses/GAMMA_IS_LIGHT.md",
    "hypotheses/PERSPECTIVAL_TIME_FIELD.md","experiments/K_DOSIMETRY.md",
    "simulations/k_dosimetry.py","simulations/k_scaling_and_renyi.py",
    "simulations/observer_gravity_cross.py","simulations/observer_time_rescale.py",
    "simulations/information_geometry.py",
))
def test_task4_real_old_fragment_restorations_fail_inventory(path):
    source=read_host(path)
    candidates=[r for r in F14_ORIGINAL_BLOCKS if r[0]==path and r[3]=="F14/mixed" and r[6] not in source]
    assert candidates,(path,"no genuine removed old fragment")
    # Each old summary/headline/slogan is restored independently in the real host.
    for row in candidates:
        old=row[6]
        if path.endswith(".py"):
            mutant=source+"\n# "+old+"\n"
        else:
            mutant=source+"\n<!-- F14-CURRENT -->\n\n"+old+"\n"
        assert f14_block_inventory_findings(path,mutant)==[
            path+":F14_BLOCK_INVENTORY:new, missing, changed, or reclassified hit"],row[1]


