def test_task4_fragment_fixtures_cannot_be_silently_rebaselined():
    import json
    for name,expected in F14_FIXTURE_SEALS.items():
        encoded=json.dumps(globals()[name],ensure_ascii=True,separators=(",",":")).encode()
        assert hashlib.sha256(encoded).hexdigest()==expected,name


def relay_percentage_inventory(source, *, source_file=False):
    mode="SOURCE" if source_file else "UNCLASSIFIED"
    hits=[]
    for line in source.splitlines():
        marker=re.fullmatch(r"<!-- (?:CROSSING|F14)-(CURRENT|HISTORICAL|INTERPRETIVE) -->",line.strip())
        if marker:
            mode=marker.group(1)
        if re.search(r"\+83%|\+84\.0%",line):
            hits.append([mode,line])
    return hits


def relay_percentage_findings(path,source):
    expected=next(row[1] for row in RELAY_PERCENTAGE_FRAGMENTS if row[0]==path)
    if relay_percentage_inventory(source,source_file=path.endswith((".py",".cs")))!=expected:
        return [path+":RELAY_PERCENTAGE_DISPOSITION"]
    return []


