def relay_association_findings(path,source):
    normalized=re.sub(r"\s+"," ",source.replace("**","").replace(chr(96),""))
    return [path+":RELAY_STATISTIC_ASSOCIATION:"+fragment
            for fragment in RELAY_ASSOCIATIONS[path] if fragment not in normalized]


@pytest.mark.parametrize("path",tuple(RELAY_ASSOCIATIONS))
def test_task4_relay_labels_bind_each_number_to_its_statistic(path):
    assert not relay_association_findings(path,read_host(path))


@pytest.mark.parametrize("path",tuple(RELAY_ASSOCIATIONS))
@pytest.mark.parametrize("before,after",(
    ("2.200","2.475"),("2.475","2.200"),("t=4.00","t=4.50"),
))
def test_task4_swapping_a_relay_exposure_book_does_not_hide_behind_same_tokens(path,before,after):
    source=read_host(path)
    if before=="t=4.00" and before not in source:
        before,after="at 4.00","at 4.50"
    assert before in source
    mutant=source.replace(before,after)+"\nHistorical token inventory: 2.200 2.475 2.17125 t=4.00 t=4.50\n"
    assert relay_association_findings(path,mutant)


@pytest.mark.parametrize("path",("simulations/minimum_energy.py","simulations/gamma_unit_scaling_gate.py"))
def test_task4_actual_isolated_import_is_silent_and_cannot_touch_tracked_results(tmp_path,path):
    import subprocess,sys
    source=read_host(path)
    assert not import_safety_findings(path,source)
    before=artifact_hashes()
    copied=tmp_path/Path(path).name
    copied.write_text(source,encoding="utf-8")
    runner=(
        "import importlib.util,sys;"
        "sys.path.insert(0,sys.argv[2]);"
        "spec=importlib.util.spec_from_file_location('isolated_task4_producer',sys.argv[1]);"
        "module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)"
    )
    result=subprocess.run([sys.executable,"-B","-c",runner,str(copied),str(ROOT/"simulations")],
                          cwd=tmp_path,capture_output=True,text=True,timeout=30)
    assert result.returncode==0,result.stderr
    assert result.stdout=="" and result.stderr=="",result.stdout+result.stderr
    assert artifact_hashes()==before
    assert sorted(p.name for p in tmp_path.iterdir())==[copied.name]


def test_task4_question_noise_rows_keep_the_operator_and_open_status():
    source=read_host("review/OPEN_QUESTIONS_INDEX.md")
    for number,status,operator in (
        (144,"resolved","Z⊗Z"),(145,"resolved","Z⊗Z"),(146,"open","Z1+Z2"),
        (147,"open","amplitude damping"),(148,"open","amplitude damping"),
        (150,"open","never bridge"),
    ):
        block=source.split("### OQ-"+str(number)+"\n",1)[1].split("\n### ",1)[0]
        assert "**Status:** "+status in block,(number,status)
        assert operator in block,(number,operator)


@pytest.mark.parametrize("number",(146,147,148,150))
def test_task4_a_different_noise_question_cannot_be_promoted_to_resolved(monkeypatch,number):
    source=read_host("review/OPEN_QUESTIONS_INDEX.md")
    anchor="### OQ-"+str(number)+"\n"
    prefix,rest=source.split(anchor,1)
    block,tail=rest.split("\n### ",1)
    assert "**Status:** open" in block
    mutant=prefix+anchor+block.replace("**Status:** open","**Status:** resolved",1)+"\n### "+tail
    monkeypatch.setitem(globals(),"read_host",lambda _:mutant)
    with pytest.raises(AssertionError):
        test_task4_question_noise_rows_keep_the_operator_and_open_status()


