# Entry-commit authority is independent of the mutable fixture rows and seals.
TASK4_ENTRY_COMMIT = "211154bd2d87202c6c0df30dee68e7e4a3a84127"


def task4_entry_blob(path):
    import subprocess
    result = subprocess.run(["git", "show", TASK4_ENTRY_COMMIT+":"+path],
                            cwd=ROOT, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode != 0:
        raise AssertionError("ENTRY_BLOB_READ_FAILED:"+path+":"+str(result.returncode))
    return result.stdout.decode("utf-8-sig").replace("\r\n", "\n").replace("\r", "\n")


def task4_entry_lineage_findings(rows):
    blobs = {}
    findings = []
    for path, anchor, digest, obj, disposition, required, fragment in rows:
        if path not in blobs:
            blobs[path] = task4_entry_blob(path).splitlines()
        match = re.fullmatch(r"(.*) @ HEAD:(\d+)", anchor)
        if not match:
            findings.append(path+":ENTRY_ANCHOR_FORMAT")
            continue
        number = int(match.group(2))
        lines = blobs[path]
        if not 1 <= number <= len(lines):
            findings.append(path+":ENTRY_LINE_RANGE:"+anchor)
            continue
        heading = "front"
        for line in lines[:number]:
            if line.startswith("#"):
                heading = line
        actual = lines[number-1]
        if (heading != match.group(1) or actual != fragment
                or hashlib.sha256(actual.encode("utf-8")).hexdigest() != digest):
            findings.append(path+":ENTRY_FRAGMENT_MISMATCH:"+anchor)
    return findings


def test_task4_forging_original_fragment_row_and_aggregate_seal_still_fails(monkeypatch):
    import copy
