    rows = copy.deepcopy(F14_ORIGINAL_BLOCKS)
    row = next(row for row in rows if row[0] == "experiments/CRITICAL_SLOWING_AT_THE_CUSP.md"
               and "under pure Z-dephasing" in row[6])
    row[6] = row[6].replace("under pure Z-dephasing", "under arbitrary dynamics")
    row[2] = hashlib.sha256(row[6].encode()).hexdigest()
    monkeypatch.setitem(globals(), "F14_ORIGINAL_BLOCKS", rows)
    monkeypatch.setitem(F14_FIXTURE_SEALS, "F14_ORIGINAL_BLOCKS",
        hashlib.sha256(json.dumps(rows,ensure_ascii=True,separators=(",",":")).encode()).hexdigest())
    test_task4_fragment_fixtures_cannot_be_silently_rebaselined()
    with pytest.raises(AssertionError, match="ENTRY_FRAGMENT_MISMATCH"):
        test_task4_frozen_original_lineage_is_complete_and_not_self_rebaselined()


