def task4_relay_inventory_contract(rows):
    # The copy manifest already has its own exact frozen membership guard.
    # These seven named owners are the complete additional relation, not a
    # count derived from whichever fixture rows happened to survive.
    extras = {
        "compute/RCPsiSquared.Propagate/Program.cs",
        "compute/RCPsiSquared.Propagate.Test/Program.cs",
        "docs/ANALYTICAL_FORMULAS.md",
        "experiments/RELAY_PROTOCOL.md",
        "simulations/results/pull_principle.txt",
        "simulations/results/resonant_return.txt",
        "simulations/results/temporal_sacrifice_protocol.txt",
    }
    paths = [row[0] for row in rows]
    assert len(RELAY_COPY_HOSTS) == 20 and len(set(RELAY_COPY_HOSTS)) == 20
    assert len(rows) == 27 and len(set(paths)) == 27, "RELAY_INVENTORY_COUNT"
    assert sum(len(row[1]) for row in rows) == 48, "RELAY_INVENTORY_ROW_SUM"
    assert not set(RELAY_COPY_HOSTS) & extras
    assert set(paths) == set(RELAY_COPY_HOSTS) | extras, "RELAY_INVENTORY_SET"
    import json
    digest = hashlib.sha256(json.dumps(rows,ensure_ascii=True,separators=(",",":")).encode()).hexdigest()
    assert digest == "e7334fe51dc273c67fb726f793fb0f4ac2e9996d6b17d43c19b126221af1fe5b", "RELAY_INVENTORY_CANONICAL"


