def task4_legacy_structure(source, path):
    tree = ast.parse(source)
    allowed = set(TASK4_ALLOWED_DISPLAY_LINES[path])

    class LabelsOnly(ast.NodeTransformer):
        def strip_docstring(self, node):
            if (node.body and isinstance(node.body[0], ast.Expr)
                    and isinstance(node.body[0].value, ast.Constant)
                    and isinstance(node.body[0].value.value, str)):
                node.body = node.body[1:]
            return self.generic_visit(node)

        visit_Module = strip_docstring
        visit_FunctionDef = strip_docstring
        visit_AsyncFunctionDef = strip_docstring
        visit_ClassDef = strip_docstring

        def visit_Expr(self, node):
            value = node.value
            if (isinstance(value, ast.Call) and isinstance(value.func, ast.Name)
                    and value.func.id == "log" and len(value.args) == 1
                    and not value.keywords):
                argument = value.args[0]
                if isinstance(argument, ast.Constant) and argument.value in allowed:
                    return None
                if path == "simulations/resonant_return.py" and isinstance(argument, ast.JoinedStr):
                    pairs = {
                        "    Palindrome stage time (pi/rate): ": "candidate-duration-label",
                        "    Deferred candidate duration (pi/rate): ": "candidate-duration-label",
                        "    Fixed stage time (K/gamma): ": "nominal-heuristic-label",
                        "    Historical nominal heuristic (0.039/gamma): ": "nominal-heuristic-label",
                    }
                    for part in argument.values:
                        if isinstance(part, ast.Constant) and part.value in pairs:
                            part.value = pairs[part.value]
            return self.generic_visit(node)

    return ast.dump(LabelsOnly().visit(tree), include_attributes=False)


