def test_task4_removing_eigensystem_transpose_fails_structural_door():
    path = "simulations/k_dosimetry.py"
    source = read_host(path)
    assert source.count("np.linalg.eig(L.T)") == 1
    mutant = source.replace("np.linalg.eig(L.T)", "np.linalg.eig(L)", 1)
    # This exact attack is invisible to the old numeric-only checker.
    assert task4_numeric_source_digest(mutant) == task4_numeric_source_digest(source)
    assert task4_legacy_structure(mutant,path) != task4_legacy_structure(task4_entry_blob(path),path)


@pytest.mark.parametrize("before,after", (
    ("np.linalg.eig(L.T)", "np.linalg.eig(L.conj())"),
    ("np.outer", "np.inner"),
    ("'k_dosimetry.txt'", "'other_output.txt'"),
))
def test_task4_legacy_nonlabel_calls_attributes_and_strings_are_structural(before,after):
    path = "simulations/k_dosimetry.py"
    source = read_host(path)
    if before not in source:
        before,after = before.replace("'",'"'),after.replace("'",'"')
    assert before in source
    mutant = source.replace(before,after,1)
    assert task4_legacy_structure(mutant,path) != task4_legacy_structure(task4_entry_blob(path),path)


