def task4_source_claim_surface_digest(source):
    import json
    strings = [node.value for node in ast.walk(ast.parse(source))
               if isinstance(node,ast.Constant) and isinstance(node.value,str)]
    comments = [token.string for token in tokenize.generate_tokens(io.StringIO(source).readline)
                if token.type == tokenize.COMMENT]
    # Includes complete module/function docstrings, every display/format string,
    # computational strings, and ordered comments; nothing may be re-promoted
    # by inserting an old line after an otherwise correct current disclaimer.
    payload = json.dumps([strings,comments],ensure_ascii=True,separators=(",",":")).encode()
    return hashlib.sha256(payload).hexdigest()


def task4_source_claim_surface_findings(path,source):
    if task4_source_claim_surface_digest(source) != TASK4_SOURCE_SURFACE_HASHES[path]:
        return [path+":SOURCE_LABEL_SURFACE"]
    return []


