def task4_crossing_only_positive_findings(path, source):
    row = next((r for r in TASK4_CROSSING_ONLY_POSITIVES if r[0] == path), None)
    if row is None:
        return []
    _, mode, fragment, digest = row
    selected = "\n".join(block for kind, block in task4_region_parts(source) if kind == mode)
    if hashlib.sha256(fragment.encode("utf-8")).hexdigest() != digest or selected.count(fragment) != 1:
        return [path + ":CROSSING_REQUIRED_POSITIVE_SCOPE"]
    if path == "hypotheses/TUNING_PROTOCOL.md":
        current = "\n".join(block for kind, block in task4_region_parts(source) if kind == "CURRENT")
        if ("Historical nomenclature:" not in selected or
                "**Does not establish:** That this protocol has been tested on humans or biological systems" not in current):
            return [path + ":CROSSING_REQUIRED_POSITIVE_SCOPE"]
    return []


