def task4_quality_scope_findings(path, source):
    if path not in TASK4_QUALITY_POSITIVES:
        return []
    if path.startswith("review/"):
        hit = re.search(r"(?ms)^### OQ-165\n(.*?)(?=^### OQ-|\Z)", source)
        if not hit:
            return [path + ":QUALITY_OQ165_MISSING"]
        selected = hit.group(1)
    elif path.endswith(".py"):
        selected = source
    else:
        selected = "\n".join(block for mode, block in task4_region_parts(source) if mode == "CURRENT")
    problems = [
        path + ":QUALITY_POSITIVE_SCOPE:" + required
        for required in TASK4_QUALITY_POSITIVES[path] if required not in selected
    ]
    patterns = {}
    if path == "experiments/OBSERVER_GRAVITY_BRIDGE.md":
        patterns["OBSERVER_FINITE_J_RANGE"] = (
            r"(?:interval\s+)?shift\s+has\s+no\s+threshold|"
            r"any (?:coupling )?j\s*>\s*0 produces a measurable|"
            r"continuous in j, no threshold|"
            r"Δt\s*<\s*0\s+for\s+every\s+j\s*>\s*0(?!\s+tested)|"
            r"easily detectable|unmeasurable|"
            r"too weak by 25 orders of magnitude to\s+be measurable"
        )
    elif path.startswith("review/"):
        patterns["QUALITY_OQ165_MECHANISM"] = (
            r"\banswered\b|(?:shift is|Δt\s*<\s*0)\s+universally|"
            r"destroys nonlocal coherence reservoir|explicitly answered with full mechanism"
        )
    elif path == "simulations/resonant_return.py":
        patterns["QUALITY_RESONANT_DEFERRED"] = (
            r"test 3:\s*palindrome-timed relay|"
            r"3\.\s*palindrome-timed relay outperforms fixed"
        )
    elif path == "simulations/observer_gravity_cross.py":
        patterns["QUALITY_OBSERVER_MI_TABLE"] = (
            r"test 2:\s*(?:sweep α, show )?k\(conc\)/k\(mi\) is state-dependent"
        )
    elif path == "experiments/BRIDGE_CLOSURE.md":
        patterns["QUALITY_BRIDGE_PURITY"] = r"\|\s*t_after\s*\|\s*ρ_a\(nothing\)"
    for rule, pattern in patterns.items():
        for match in re.finditer(pattern, selected, re.I):
            # Only attached grammatical denial, not an unrelated earlier caveat.
            if crossing_local_fence(selected[:match.start()], selected[match.end():], match.group()):
                continue
            problems.append(path + ":" + rule + ":" + match.group())
    return problems


