def task4_authorized_table_labels(path, index, fragment):
    # Preserve the complete original table fingerprint, allowing only the
    # reviewed scalar-label correction. Numeric rows and norm column are exact.
    if (path, index) == ("experiments/BRIDGE_CLOSURE.md", 1):
        old = "| t_after | ρ_A(nothing) | ρ_A(B→Z) | ρ_A(B→X) |"
        new = "| t_after | purity_A(nothing) | purity_A(B→Z) | purity_A(B→X) |"
        assert fragment.count(old) == 1
        return fragment.replace(old, new, 1)
    return fragment


def test_task4_quality_bridge_header_transition_preserves_every_numeric_row():
    path, index, original, digest = next(
        row for row in TASK4_IMMUTABLE_NUMERIC_TABLES
        if row[:2] == ["experiments/BRIDGE_CLOSURE.md", 1])
    current = task4_authorized_table_labels(path, index, original)
    assert current.splitlines()[1:] == original.splitlines()[1:]
    assert hashlib.sha256(original.encode()).hexdigest() == digest



TASK4_PROPOSAL_PARTITION = {
    "open": 19, "resolved": 10, "partially-resolved": 3,
    "obsolete": 4, "needs-human": 2, "superseded": 0,
}


def task4_proposal_status_findings(source):
    from collections import Counter
    problems = []
    entries = re.findall(r"(?ms)^### (OQ-\d+)\n(.*?)(?=^### OQ-|\Z)", source)
    if len(entries) != 38 or len({key for key, _ in entries}) != 38:
        problems.append("PROPOSAL_ENTRY_COUNT")
    normalized = []
    for key, body in entries:
        statuses = re.findall(r"(?m)^\*\*Proposed Status:\*\* (.+)$", body)
        if len(statuses) != 1:
            problems.append(key + ":PROPOSAL_STATUS_CARDINALITY")
            continue
        raw = statuses[0].strip()
        # Parenthetical qualifications retain one classification. A slash is
        # an unresolved classification, even when placed inside parentheses.
        match = re.fullmatch(
            r"(open|resolved|partially-resolved|obsolete|needs-human|superseded)"
            r"(?: \([^()/\n]*\))?", raw)
        if match is None:
            problems.append(key + ":PROPOSAL_STATUS_NORMALIZATION:" + raw)
            continue
        normalized.append(match.group(1))
    actual = {key: Counter(normalized)[key] for key in TASK4_PROPOSAL_PARTITION}
    if actual != TASK4_PROPOSAL_PARTITION:
        problems.append("PROPOSAL_ENTRY_PARTITION:" + repr(actual))
    summary = re.search(r"(?ms)^## Summary\n(.*?)(?=^---|^## |\Z)", source)
    rows = [] if summary is None else re.findall(
        r"(?m)^\| ([a-z-]+) \| (\d+) \|$", summary.group(1))
    if len(rows) != 6 or len({key for key, _ in rows}) != 6:
        problems.append("PROPOSAL_SUMMARY_CARDINALITY")
    counts = {key: int(value) for key, value in rows}
    if counts != actual or counts != TASK4_PROPOSAL_PARTITION:
        problems.append("PROPOSAL_SUMMARY_COUNTS:" + repr(counts))
    if "**Entries in batch:** 38" not in source:
        problems.append("PROPOSAL_DECLARED_TOTAL")
    return problems


def test_task4_proposal_status_partition_matches_all_38_entries():
    path = "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md"
    assert not task4_proposal_status_findings(read_host(path))


