def task6_captured_source_static_findings(path, source):
    findings = list(import_safety_findings(path, source))
    tree = ast.parse(source)
    mains = [node for node in tree.body
             if isinstance(node, ast.FunctionDef) and node.name == "main"]
    if len(mains) != 1:
        findings.append(f"{path}: expected one top-level main")
        return tuple(findings)
    main = mains[0]
    args = main.args.posonlyargs + main.args.args + main.args.kwonlyargs
    if "output_path" not in {arg.arg for arg in args}:
        findings.append(f"{path}: main lacks output_path")
    destination_assignments = [
        node for node in ast.walk(main)
        if isinstance(node, (ast.Assign, ast.AnnAssign))
        and any(isinstance(target, ast.Name) and target.id == "destination"
                for target in (node.targets if isinstance(node, ast.Assign)
                               else [node.target]))
    ]
    if len(destination_assignments) != 1:
        findings.append(f"{path}: expected one destination assignment")
    else:
        value = destination_assignments[0].value
        if ast.unparse(value) != "Path(output_path)":
            findings.append(f"{path}: destination must be Path(output_path)")
    writes = [node for node in ast.walk(main)
              if isinstance(node, ast.Call)
              and ast.unparse(node.func) == "destination.write_text"]
    if len(writes) != 1:
        findings.append(f"{path}: expected one destination.write_text call")
    all_file_writes = [
        node for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and (ast.unparse(node.func) == "open"
             or (isinstance(node.func, ast.Attribute)
                 and node.func.attr in {"write_text", "write_bytes"}))
    ]
    if len(all_file_writes) != 1 or ast.unparse(all_file_writes[0].func) != \
            "destination.write_text":
        findings.append(f"{path}: every file write must use destination.write_text")
    output_options = [
        node for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "add_argument"
        and node.args
        and isinstance(node.args[0], ast.Constant)
        and node.args[0].value == "--output"
    ]
    if len(output_options) != 1:
        findings.append(f"{path}: expected one --output CLI option")
    guarded_main_calls = [
        call for node in tree.body
        if isinstance(node, ast.If)
        and ast.unparse(node.test) in (
            "__name__ == '__main__'", "'__main__' == __name__"
        )
        for call in ast.walk(node)
        if isinstance(call, ast.Call) and ast.unparse(call.func) == "main"
    ]
    if len(guarded_main_calls) != 1 or \
            ast.unparse(guarded_main_calls[0]) != "main(args.output)":
        findings.append(f"{path}: guarded CLI must call main(args.output)")
    return tuple(findings)


def task6_captured_source_semantic_findings(path, source):
    contract = TASK6_CAPTURED_SOURCE_WRITERS[path]
    lowered = re.sub(r"\s+", " ", source).lower()
    findings = [
        f"{path}: missing {required}"
        for required in contract["required"]
        if required.lower() not in lowered
    ]
    findings.extend(
        f"{path}: restored {pattern}"
        for pattern in contract["forbidden"]
        if re.search(pattern, source, re.I)
    )
    return tuple(findings)


@pytest.mark.parametrize("path", TASK6_CAPTURED_SOURCE_WRITERS)
def test_task6_captured_result_sources_are_inert_scoped_writers(path):
    source = read_host(path)
    assert not task6_captured_source_static_findings(path, source), \
        task6_captured_source_static_findings(path, source)
    assert not task6_captured_source_semantic_findings(path, source), \
        task6_captured_source_semantic_findings(path, source)


@pytest.mark.parametrize("path", TASK6_CAPTURED_SOURCE_WRITERS)
def test_task6_captured_source_required_and_restored_label_mutations_fail(path):
    source = read_host(path)
    contract = TASK6_CAPTURED_SOURCE_WRITERS[path]
    for required in contract["required"]:
        flexible = r"\s+".join(map(re.escape, required.split()))
        mutant, count = re.subn(flexible, "", source, flags=re.I)
        assert count >= 1, (path, required)
        assert task6_captured_source_semantic_findings(path, mutant)
    tree = ast.parse(source)
    doc = tree.body[0]
    assert isinstance(doc, ast.Expr) and isinstance(doc.value, ast.Constant)
    for forbidden in contract["forbidden"]:
        literal = re.sub(r"\\([()])", r"\1", forbidden)
        mutant_tree = ast.parse(source)
        mutant_doc = mutant_tree.body[0]
        mutant_doc.value.value += "\n" + literal
        mutant = ast.unparse(ast.fix_missing_locations(mutant_tree))
        assert task6_captured_source_semantic_findings(path, mutant)


