def task6_f94_source_findings(path, source):
    ast.parse(source)
    contract = TASK6_F94_SOURCE_CONTRACTS[path]
    normalized = re.sub(r"\s+", " ", source)
    findings = [
        f"{path}: missing {text}"
        for text in contract["required"]
        if text.lower() not in normalized.lower()
    ]
    findings.extend(
        f"{path}: restored {text}"
        for text in contract["forbidden"]
        if text.lower() in normalized.lower()
    )
    if path in (*TASK6_F94_EXECUTED_DIAGNOSTICS,
                *TASK6_F94_IMPORT_SAFE_VERIFICATION):
        findings.extend(import_safety_findings(path, source))
    findings.extend(task6_f94_active_output_findings(path, source))
    findings.extend(task6_f94_body_findings(path, source))
    return tuple(findings)


def task6_f94_print_literals(source, function_names):
    tree = ast.parse(source)
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    chunks = []

    def literal_chunks(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return [node.value]
        if isinstance(node, ast.JoinedStr):
            return [
                part.value
                for part in node.values
                if isinstance(part, ast.Constant) and isinstance(part.value, str)
            ]
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            return literal_chunks(node.left) + literal_chunks(node.right)
        return []

    for function_name in function_names:
        function = functions.get(function_name)
        if function is None:
            continue
        for node in ast.walk(function):
            if not isinstance(node, ast.Call):
                continue
            callee = node.func.id if isinstance(node.func, ast.Name) else None
            if callee not in {"print", "report"}:
                continue
            for argument in node.args:
                chunks.extend(literal_chunks(argument))
    return re.sub(r"\s+", " ", " ".join(chunks)).strip()


def task6_f94_active_output_findings(path, source):
    contract = TASK6_F94_ACTIVE_OUTPUT_CONTRACTS.get(path)
    if contract is None:
        return ()
    active = task6_f94_print_literals(source, contract["functions"])
    findings = [
        f"{path}: active output missing {text}"
        for text in contract["required"]
        if text.lower() not in active.lower()
    ]
    findings.extend(
        f"{path}: active output restored {text}"
        for text in contract["forbidden"]
        if text.lower() in active.lower()
    )
    return tuple(findings)


def task6_f94_body_findings(path, source):
    normalized = re.sub(r"\s+", " ", source).strip()
    return tuple(
        f"{path}: computation/output body missing {snippet}"
        for snippet in TASK6_F94_BODY_CONTRACTS.get(path, ())
        if re.sub(r"\s+", " ", snippet).strip() not in normalized
    )


