def test_task6_f94_source_labels_and_dispositions_are_scoped(path):
    source = read_host(path)
    assert not task6_f94_source_findings(path, source), \
        task6_f94_source_findings(path, source)


@pytest.mark.parametrize("path", TASK6_F94_SOURCE_CONTRACTS)
def test_task6_f94_required_and_restored_label_mutations_fail(path):
    source = read_host(path)
    contract = TASK6_F94_SOURCE_CONTRACTS[path]
    for required in contract["required"]:
        flexible = r"\s+".join(map(re.escape, required.split()))
        mutant, count = re.subn(flexible, "", source, flags=re.I)
        assert count >= 1, (path, required)
        assert task6_f94_source_findings(path, mutant)
    tree = ast.parse(source)
    doc = tree.body[0]
    assert isinstance(doc, ast.Expr) and isinstance(doc.value, ast.Constant)
    for forbidden in contract["forbidden"]:
        mutant_tree = ast.parse(source)
        mutant_doc = mutant_tree.body[0]
        mutant_doc.value.value += "\n" + forbidden
        mutant = ast.unparse(ast.fix_missing_locations(mutant_tree))
        assert task6_f94_source_findings(path, mutant)


def test_task6_f94_execution_disposition_is_an_exact_partition():
    executed = set(TASK6_F94_EXECUTED_DIAGNOSTICS)
    syntax_only = set(TASK6_F94_SYNTAX_ONLY)
    import_safe = set(TASK6_F94_IMPORT_SAFE_VERIFICATION)
    assert (len(executed), len(syntax_only), len(import_safe)) == (4, 2, 3)
    assert not (executed & syntax_only)
    assert not (executed & import_safe)
    assert not (syntax_only & import_safe)
    assert executed | syntax_only | import_safe == set(TASK6_F94_SOURCE_CONTRACTS)


@pytest.mark.parametrize(
    "path",
    (*TASK6_F94_EXECUTED_DIAGNOSTICS, *TASK6_F94_IMPORT_SAFE_VERIFICATION),
)
def test_task6_f94_nonheavy_sources_import_silently_in_fresh_process(path):
    code = (
        "import importlib.util,sys; "
        "spec=importlib.util.spec_from_file_location('task6_probe',sys.argv[1]); "
        "module=importlib.util.module_from_spec(spec); "
        "spec.loader.exec_module(module)"
    )
    completed = subprocess.run(
        [sys.executable, "-c", code, str(ROOT / path)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="strict",
        timeout=60,
        check=False,
    )
    assert completed.returncode == 0, (path, completed.stderr)
    assert completed.stdout == "", (path, completed.stdout)
    assert completed.stderr == "", (path, completed.stderr)


