def task6_f94_fresh_stdout_findings(path, stdout):
    normalized = re.sub(r"\s+", " ", stdout).strip()
    findings = [
        f"{path}: fresh stdout missing {required}"
        for required in TASK6_F94_FRESH_STDOUT_REQUIRED[path]
        if required.lower() not in normalized.lower()
    ]
    contract = TASK6_F94_ACTIVE_OUTPUT_CONTRACTS[path]
    findings.extend(
        f"{path}: fresh stdout restored {forbidden}"
        for forbidden in contract["forbidden"]
        if forbidden.lower() in normalized.lower()
    )
    if path == "simulations/born_rule_tier1_derivation.py":
        match = re.search(r"sym3 ρ_0\].*?=\s*([-+0-9.eE]+)", stdout)
        if match is None or abs(float(match.group(1)) - 8.0) > 1e-12:
            findings.append(f"{path}: fresh sym3 row is not the finite reconstruction of 8")
    if path == "simulations/born_rule_subdominant_dyson.py":
        match = re.search(
            r"absolute sym3 vector from this body:\s*(\([^\r\n]+\))",
            stdout,
        )
        if match is None:
            findings.append(f"{path}: fresh absolute sym3 row is missing")
        else:
            values = ast.literal_eval(match.group(1))
            if len(values) != 4 or any(
                abs(actual - expected) > 1e-9
                for actual, expected in zip(values, (8.0, -4.0, -4.0, 0.0))
            ):
                findings.append(f"{path}: fresh absolute sym3 row is not (8,-4,-4,0)")
    return tuple(findings)


@pytest.mark.skipif(
    os.environ.get("RUN_TASK6_F94_DIAGNOSTICS") != "1",
    reason="explicit interlock for the four approved Task 6 diagnostics",
)
@pytest.mark.parametrize("path", TASK6_F94_EXECUTED_DIAGNOSTICS)
def test_task6_f94_approved_diagnostics_have_fresh_scoped_stdout(path):
    completed = subprocess.run(
        [sys.executable, str(ROOT / path)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="strict",
        timeout=240,
        check=False,
    )
    assert completed.returncode == 0, (path, completed.stderr)
    assert not task6_f94_fresh_stdout_findings(path, completed.stdout), \
        task6_f94_fresh_stdout_findings(path, completed.stdout)


def test_task6_f94_f96_exact_rational_controls_are_distinct():
    ring_sym3 = tuple(map(Fraction, (8, -4, -4, 0)))
    chain_sym3 = tuple(map(Fraction, (5, -4, -1, 0)))
    assert sum(ring_sym3) == sum(chain_sym3) == 0
    assert ring_sym3[0] / 6 == Fraction(4, 3)
    assert ring_sym3[1] / (3 * Fraction(3, 4)) == Fraction(-16, 9)
    assert ring_sym3[2] / (3 * Fraction(3, 4)) == Fraction(-16, 9)
    assert Fraction(-20) / (5 * Fraction(3, 2)) == Fraction(-8, 3)
    assert chain_sym3[2] / (3 * Fraction(1, 4)) == Fraction(-4, 3)
    assert Fraction(40, 27) != Fraction(4, 3)


def test_task6_f94_formula_helpers_feed_the_named_controls(tmp_path):
    tier1 = source_copy_definitions(
        read_host("simulations/born_rule_tier1_derivation.py"),
        {"leading_delta_coefficient"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    assert tier1["leading_delta_coefficient"](
        Fraction(8), Fraction(1)
    ) == Fraction(4, 3)

    sub = source_copy_definitions(
        read_host("simulations/born_rule_subdominant_dyson.py"),
        {"normalized_dyson_slope"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    slope = sub["normalized_dyson_slope"]
    assert slope(Fraction(-4), 3, Fraction(3, 4)) == Fraction(-16, 9)
    assert slope(Fraction(-20), 5, Fraction(3, 2)) == Fraction(-8, 3)
    assert slope(Fraction(-1), 3, Fraction(1, 4)) == Fraction(-4, 3)


def test_task6_topology_and_constructed_dictionary_helpers_can_be_mutated(tmp_path):
    topology_source = read_host("simulations/f94_topology_visibility_probe.py")
    topology = source_copy_definitions(
        topology_source, {"normalized_dyson_slope"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    slope = topology["normalized_dyson_slope"]
    assert slope(Fraction(-4), 3, Fraction(3, 4)) == Fraction(-16, 9)
    assert slope(Fraction(-1), 3, Fraction(1, 4)) == Fraction(-4, 3)
    topology_mutant = topology_source.replace(
        "return dyson_element / (order * unitary_element)",
        "return dyson_element / ((order + 1) * unitary_element)", 1,
    )
    assert topology_mutant != topology_source
    copied_mutant = source_copy_definitions(
        topology_mutant, {"normalized_dyson_slope"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    assert copied_mutant["normalized_dyson_slope"](
        Fraction(-1), 3, Fraction(1, 4)
    ) != Fraction(-4, 3)

    carrier_source = read_host("simulations/where_the_carrier_hides.py")
    carrier = source_copy_definitions(
        carrier_source, {"constructed_angle_dictionary"}, tmp_path,
    )
    q = np.array([0.0, 0.5, 1.0, np.sqrt(3.0)])
    c, theta_pair, theta_quadratic = carrier["constructed_angle_dictionary"](q)
    np.testing.assert_allclose(c, 0.25 + q*q/4, rtol=0, atol=0)
    np.testing.assert_allclose(theta_pair, theta_quadratic, rtol=0, atol=2e-16)
    carrier_mutant = carrier_source.replace("q_values ** 2 / 4.0", "q_values ** 2 / 3.0", 1)
    assert carrier_mutant != carrier_source
    mutated = source_copy_definitions(
        carrier_mutant, {"constructed_angle_dictionary"}, tmp_path,
    )["constructed_angle_dictionary"]
    _, left, right = mutated(q)
    assert np.max(np.abs(left - right)) > 1e-3


def test_task6_qutrit_closed_form_is_40_over_27_without_running_producer(tmp_path):
    source = read_host("simulations/f94_qutrit_born_mirror.py")
    copied = source_copy_definitions(
        source, {"c_closed"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    assert copied["c_closed"](2) == Fraction(4, 3)
    assert copied["c_closed"](3) == Fraction(40, 27)
    mutant = source.replace("3 * d * d", "4 * d * d", 1)
    assert mutant != source
    mutated = source_copy_definitions(
        mutant, {"c_closed"}, tmp_path,
        prelude="from fractions import Fraction\n",
    )
    assert mutated["c_closed"](3) != Fraction(40, 27)


