def task6_batch3_print_literals(path, source):
    contract = TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS[path]
    function_names = contract["functions"]
    tree = ast.parse(source)
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    chunks = []

    def literal_chunks(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return [node.value]
        if isinstance(node, ast.JoinedStr):
            return [part.value for part in node.values
                    if isinstance(part, ast.Constant)
                    and isinstance(part.value, str)]
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            return literal_chunks(node.left) + literal_chunks(node.right)
        return []

    def collect_expression(node):
        for child in ast.walk(node):
            if not isinstance(child, ast.Call):
                continue
            callee = child.func.id if isinstance(child.func, ast.Name) else None
            if callee != "print":
                continue
            for argument in child.args:
                chunks.extend(literal_chunks(argument))

    def collect_statements(statements):
        for statement in statements:
            if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef,
                                      ast.ClassDef)):
                continue
            if isinstance(statement, ast.If):
                if isinstance(statement.test, ast.Constant):
                    branch = statement.body if statement.test.value else statement.orelse
                    collect_statements(branch)
                else:
                    collect_expression(statement.test)
                    collect_statements(statement.body)
                    collect_statements(statement.orelse)
            elif isinstance(statement, (ast.For, ast.AsyncFor, ast.While)):
                collect_expression(statement.iter if hasattr(statement, "iter")
                                   else statement.test)
                collect_statements(statement.body)
                collect_statements(statement.orelse)
            elif isinstance(statement, (ast.With, ast.AsyncWith)):
                collect_expression(statement)
                collect_statements(statement.body)
            elif isinstance(statement, ast.Try):
                collect_statements(statement.body)
                for handler in statement.handlers:
                    collect_statements(handler.body)
                collect_statements(statement.orelse)
                collect_statements(statement.finalbody)
            else:
                collect_expression(statement)
            if isinstance(statement, (ast.Return, ast.Raise, ast.Break,
                                      ast.Continue)):
                break

    roots = function_names if function_names is not None else tuple(functions)
    for function_name in roots:
        function = functions.get(function_name)
        if function is not None:
            collect_statements(function.body)
    return re.sub(r"\s+", " ", " ".join(chunks)).strip()


def task6_batch3_active_output_findings(path, source):
    contract = TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS[path]
    active = task6_batch3_print_literals(path, source)
    findings = [f"{path}: active output missing {text}"
                for text in contract["required"]
                if text.lower() not in active.lower()]
    findings.extend(f"{path}: active output restored {text}"
                    for text in contract["forbidden"]
                    if text.lower() in active.lower())
    return tuple(findings)


def task6_batch3_bridge_dataflow_findings(source):
    tree = ast.parse(source)
    run_test = next((node for node in tree.body
                     if isinstance(node, ast.FunctionDef)
                     and node.name == "run_test"), None)
    if run_test is None:
        return ("bridge:RUN_TEST",)
    normalized = re.sub(r"\s+", " ", ast.unparse(run_test))
    required = (
        "operator_pi = apply_pi(rho, N)",
        "operator01_pi = partial_trace(operator_pi, N, [0, 1])",
        "operator02_pi = partial_trace(operator_pi, N, [0, 2])",
        "operator12_pi = partial_trace(operator_pi, N, [1, 2])",
        "scalar01_pi = selected_scalar_readout(operator01_pi)",
        "scalar02_pi = selected_scalar_readout(operator02_pi)",
        "scalar12_pi = selected_scalar_readout(operator12_pi)",
        "adjacent_sum_mi = mi01 + mi12",
        "rows.append(row)",
        "best_index = max(range(len(rows)), key=lambda index: rows[index]['adjacent_sum_mi'])",
        "marker = ' <-- GLOBAL ARGMAX OF ADJACENT-PAIR SUM' if index == best_index else ''",
        "best = rows[best_index]",
    )
    findings = [f"bridge:DATAFLOW:{snippet}" for snippet in required
                if snippet not in normalized]

    assignments = {}
    for node in ast.walk(run_test):
        if not isinstance(node, ast.Assign) or len(node.targets) != 1:
            continue
        target = node.targets[0]
        if isinstance(target, ast.Name):
            assignments.setdefault(target.id, []).append(node.value)

    def exact_assignment(name, expression):
        values = assignments.get(name, ())
        expected = ast.dump(ast.parse(expression, mode="eval").body,
                            include_attributes=False)
        return len(values) == 1 and ast.dump(
            values[0], include_attributes=False,
        ) == expected

    if not exact_assignment("adjacent_sum_mi", "mi01 + mi12"):
        findings.append("bridge:ADJACENT_SUM_ASSIGNMENT")
    if not exact_assignment("best", "rows[best_index]"):
        findings.append("bridge:BEST_ROW_ASSIGNMENT")
    if not exact_assignment("original", "row['original']"):
        findings.append("bridge:ORIGINAL_ROW_ASSIGNMENT")
    if not exact_assignment("pi_operator", "row['pi_operator']"):
        findings.append("bridge:PI_OPERATOR_ROW_ASSIGNMENT")

    row_values = assignments.get("row", ())
    if len(row_values) != 1 or not isinstance(row_values[0], ast.Dict):
        findings.append("bridge:ROW_DICT")
    else:
        row = row_values[0]
        entries = {
            key.value: value
            for key, value in zip(row.keys, row.values)
            if isinstance(key, ast.Constant) and isinstance(key.value, str)
        }
        expected_entries = {
            "adjacent_sum_mi": "adjacent_sum_mi",
            "pi_operator": "(scalar01_pi, scalar02_pi, scalar12_pi)",
        }
        for key, expression in expected_entries.items():
            expected = ast.dump(ast.parse(expression, mode="eval").body,
                                include_attributes=False)
            actual = entries.get(key)
            if actual is None or ast.dump(
                    actual, include_attributes=False) != expected:
                findings.append(f"bridge:ROW:{key}")

    best_reads = {
        node.slice.value
        for node in ast.walk(run_test)
        if isinstance(node, ast.Subscript)
        and isinstance(node.value, ast.Name)
        and node.value.id == "best"
        and isinstance(node.slice, ast.Constant)
        and isinstance(node.slice.value, str)
    }
    if not {"adjacent_sum_mi", "t"} <= best_reads:
        findings.append("bridge:BEST_ROW_OUTPUT")

    table_print_bound = False
    for node in ast.walk(run_test):
        if (not isinstance(node, ast.Call)
                or not isinstance(node.func, ast.Name)
                or node.func.id != "print"):
            continue
        names = {child.id for child in ast.walk(node)
                 if isinstance(child, ast.Name)}
        if {"original", "pi_operator", "marker"} <= names:
            table_print_bound = True
            break
    if not table_print_bound:
        findings.append("bridge:TABLE_PRINT_ROW_BINDING")
    return tuple(findings)


def task6_batch3_water_model_findings(source):
    tree = ast.parse(source)
    assignments = {
        target.id: node.value
        for node in tree.body
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        for target in node.targets
        if isinstance(target, ast.Name)
    }
    findings = []
    expected_matrices = {
        "SX": "np.array([[0, 1], [1, 0]], dtype=complex)",
        "SY": "np.array([[0, -1j], [1j, 0]], dtype=complex)",
        "SZ": "np.array([[1, 0], [0, -1]], dtype=complex)",
    }
    for name, expression in expected_matrices.items():
        expected = ast.dump(ast.parse(expression, mode="eval").body,
                            include_attributes=False)
        actual = assignments.get(name)
        if actual is None or ast.dump(
                actual, include_attributes=False) != expected:
            findings.append(f"water:MODEL:{name}")
    expected_parity = ast.dump(
        ast.parse("(0, 0, 1, 1)", mode="eval").body,
        include_attributes=False,
    )
    parity = assignments.get("LETTER_PARITY")
    if parity is None or ast.dump(
            parity, include_attributes=False) != expected_parity:
        findings.append("water:MODEL:LETTER_PARITY")

    functions = {
        node.name: node for node in tree.body if isinstance(node, ast.FunctionDef)
    }
    function_contracts = {
        "heisenberg_chain": (
            "for operator in (SX, SY, SZ)",
            "J / 4.0",
            "site_op(operator, bond, N) @ site_op(operator, bond + 1, N)",
        ),
        "z_dephasing_lindblad": (
            "for site in range(N)",
            "z_site = site_op(SZ, site, N)",
            "np.kron(z_site.conj(), z_site) - super_identity",
        ),
    }
    for function_name, snippets in function_contracts.items():
        function = functions.get(function_name)
        if function is None:
            findings.append(f"water:MODEL:{function_name}:MISSING")
            continue
        normalized = re.sub(r"\s+", " ", ast.unparse(function))
        findings.extend(
            f"water:MODEL:{function_name}:{snippet}"
            for snippet in snippets if snippet not in normalized
        )
    return tuple(findings)


