def task6_batch3_runtime_stdout_findings(path, stdout):
    if path not in TASK6_BATCH3_RUNTIME_VALUE_MUTATIONS:
        return (f"runtime:{path}:UNAPPROVED",)
    normalized = re.sub(r"\s+", " ", stdout).strip()
    contract = TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS[path]
    findings = [f"runtime:{path}:MISSING:{text}"
                for text in contract["required"]
                if text.lower() not in normalized.lower()]
    findings.extend(f"runtime:{path}:RESTORED:{text}"
                    for text in contract["forbidden"]
                    if text.lower() in normalized.lower())

    def require(condition, label):
        if not condition:
            findings.append(f"runtime:{path}:{label}")

    if path == "simulations/subsystem_crossing_pairs.py":
        require("concurrence book  R=f^2/3" in stdout, "BOOK_CONCURRENCE")
        require("purity book       R=f(1+f^2)/6" in stdout, "BOOK_PURITY")
        require("constant book     R=f/3" in stdout, "BOOK_CONSTANT")
        require("concurrence=0.500, selected readout=0.083333" in stdout,
                "ENTANGLEMENT_COUNTEREXAMPLE")
        ratio = re.search(
            r"([0-9]+\.[0-9]{4}) / ([0-9]+\.[0-9]{4}) = "
            r"([0-9]+\.[0-9]{3})\. It is a finite comparison",
            stdout,
        )
        require(ratio is not None, "RATIO_FORMAT")
        if ratio is not None:
            values = tuple(float(value) for value in ratio.groups())
            require(values == pytest.approx(
                (0.7192, 0.0797, 9.023), rel=0, abs=5e-7,
            ), "RATIO_VALUES")
        for value in ("0.7192", "0.7470", "1.4384"):
            require(f"t = {value}" in stdout, f"ISOLATED_TIME:{value}")

    elif path == "simulations/axis_modes_n4.py":
        require("basis-layer reference dimension: 96" in stdout,
                "LAYER_REFERENCE")
        require("94 observed at tolerance 1e-9; basis-layer reference is 96; "
                "arithmetic gap 2 is not a leakage count" in stdout,
                "OBSERVED_REFERENCE_GAP")
        require("finite |Im(lambda)|<1e-9 count: 18" in stdout,
                "REAL_CENTRE_COUNT")
        require("even=58, odd=36, ambiguous=0" in stdout,
                "CENTRE_REFLECTION_COUNTS")

    elif path == "simulations/test_bidirectional_bridge.py":
        require("Gammas: ['0.148', '0.001', '0.001']" in stdout,
                "GAMMA_PROFILE")
        require("Sum_gamma = 0.1500" in stdout, "GAMMA_SUM")
        marker = "<-- GLOBAL ARGMAX OF ADJACENT-PAIR SUM"
        marker_lines = [line for line in stdout.splitlines() if marker in line]
        require(len(marker_lines) == 1, "UNIQUE_ARGMAX_MARKER")
        summary = re.search(
            r"Global argmax of adjacent-pair SumMI = ([0-9]+\.[0-9]{6}) "
            r"at t = ([0-9]+\.[0-9]{2})",
            stdout,
        )
        require(summary is not None, "ARGMAX_SUMMARY")
        if len(marker_lines) == 1 and summary is not None:
            row_values = [float(value) for value in re.findall(
                r"[-+]?[0-9]+\.[0-9]+", marker_lines[0],
            )]
            require(len(row_values) >= 4, "ARGMAX_ROW")
            if len(row_values) >= 4:
                summary_value, summary_time = map(float, summary.groups())
                require(row_values[0] == pytest.approx(
                    summary_time, rel=0, abs=5e-7,
                ), "ARGMAX_TIME_BINDING")
                require(row_values[1] + row_values[3] == pytest.approx(
                    summary_value, rel=0, abs=1.1e-4,
                ), "ARGMAX_VALUE_BINDING")

    elif path == "simulations/formula_four_classification.py":
        require("N=4: d=2 -> 256; d=3 -> 6561" in stdout,
                "OPERATOR_DIMENSION")
        require("N=4: d2=[0.0, 0.1, 0.2, 0.3, 0.4]; "
                "d3=[0.0, 0.1, 0.2, 0.3, 0.4]" in stdout,
                "RATE_LADDER")
        require("N=5: distinct bands equal=True; flavour multiplicities=1,2; "
                "radius=1.732050808" in stdout,
                "FLAVOUR_BAND")
        require("40/27 = 40/27; refutes typed a_-1 ancestry" in stdout,
                "QUTRIT_COUNTEREXAMPLE")

    elif path == "simulations/cardioid_parametrization_tier1.py":
        require("phi=1.570796326795: c=+0.250000000000+0.500000000000i" in stdout,
                "PI_OVER_TWO_POINT")
        require("2.236067977500 = sqrt(5)" in stdout,
                "OTHER_ROOT_MULTIPLIER")
        require("c=0 has distinct roots 0 and 1" in stdout,
                "ZERO_ROOTS")
        require("Only c=+1/4 is the cardioid cusp; |c| varies along the curve"
                in stdout, "CUSP_AND_RADIAL_SCOPE")
    return tuple(findings)


def task6_batch3_runtime_stdout_mutants(path, stdout):
    contract = TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS[path]
    required = contract["required"][0]
    missing_label = re.sub(
        re.escape(required), "REMOVED_RUNTIME_LABEL", stdout,
        flags=re.IGNORECASE,
    )
    old_value, new_value = TASK6_BATCH3_RUNTIME_VALUE_MUTATIONS[path]
    wrong_value = stdout.replace(old_value, new_value, 1)
    restored = stdout + "\n" + contract["forbidden"][0] + "\n"
    return missing_label, wrong_value, restored


@pytest.mark.parametrize("path", TASK6_BATCH3_SOURCE_CONTRACTS)
def test_task6_batch3_source_labels_and_dispositions_are_scoped(path):
    source = read_host(path)
    assert not task6_batch3_source_findings(path, source), \
        task6_batch3_source_findings(path, source)


def test_task6_batch3_execution_disposition_is_exact():
    executed = set(TASK6_BATCH3_EXECUTED_DIAGNOSTICS)
    bounded_axis = set(TASK6_BATCH3_BOUNDED_AXIS_EXECUTED)
    syntax_only = set(TASK6_BATCH3_IMPORT_SAFE_SYNTAX_ONLY)
    heavy = set(TASK6_BATCH3_HEAVY_SYNTAX_ONLY)
    assert not executed & bounded_axis
    assert not executed & syntax_only
    assert not executed & heavy
    assert not bounded_axis & syntax_only
    assert not bounded_axis & heavy
    assert not syntax_only & heavy
    assert executed | bounded_axis | syntax_only | heavy == set(TASK6_BATCH3_SOURCE_CONTRACTS)
    assert set(TASK6_BATCH3_IMPORT_SAFE) == executed | bounded_axis | syntax_only
    assert set(TASK6_BATCH3_EXECUTED_DIAGNOSTICS +
               TASK6_BATCH3_BOUNDED_AXIS_EXECUTED) == {
        "simulations/subsystem_crossing_pairs.py",
        "simulations/axis_modes_n4.py",
        "simulations/test_bidirectional_bridge.py",
        "simulations/formula_four_classification.py",
        "simulations/cardioid_parametrization_tier1.py",
    }
    assert set(TASK6_BATCH3_RUNTIME_VALUE_MUTATIONS) == set(
        TASK6_BATCH3_EXECUTED_DIAGNOSTICS
        + TASK6_BATCH3_BOUNDED_AXIS_EXECUTED
    )
    assert TASK6_BATCH3_IMPORT_SAFE_SYNTAX_ONLY == (
        "simulations/axis_modes.py",
    )
    assert TASK6_BATCH3_HEAVY_SYNTAX_ONLY == (
        "simulations/water/proton_chain_dicke_anchor.py",
    )


@pytest.mark.parametrize("path", TASK6_BATCH3_IMPORT_SAFE)
def test_task6_batch3_nonheavy_sources_import_silently_in_fresh_process(path):
    code = (
        "import importlib.util,sys; "
        "spec=importlib.util.spec_from_file_location('task6_batch3_probe',sys.argv[1]); "
        "module=importlib.util.module_from_spec(spec); "
        "spec.loader.exec_module(module)"
    )
    completed = subprocess.run(
        [sys.executable, "-c", code, str(ROOT / path)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="strict",
        timeout=60,
        check=False,
    )
    assert completed.returncode == 0, (path, completed.stderr)
    assert completed.stdout == "", (path, completed.stdout)
    assert completed.stderr == "", (path, completed.stderr)


@pytest.mark.parametrize("path", TASK6_BATCH3_SOURCE_CONTRACTS)
def test_task6_batch3_required_and_restored_label_mutations_fail(path):
    source = read_host(path)
    assert not task6_batch3_source_findings(path, source)
    contract = TASK6_BATCH3_SOURCE_CONTRACTS[path]
    for required in contract["required"]:
        mutant = re.sub(re.escape(required), "REMOVED_CURRENT_SCOPE", source,
                        flags=re.IGNORECASE)
        if mutant == source or not task6_batch3_source_findings(path, mutant):
            for token in sorted(set(re.findall(r"[A-Za-z0-9_]+", required)),
                                key=len, reverse=True):
                candidate = re.sub(re.escape(token), "REMOVED_CURRENT_SCOPE",
                                   source, flags=re.IGNORECASE)
                if candidate != source and task6_batch3_source_findings(path, candidate):
                    mutant = candidate
                    break
        assert mutant != source, (path, required)
        assert task6_batch3_source_findings(path, mutant), (path, required)
    restored = source + "\n# " + contract["forbidden"][0] + "\n"
    assert task6_batch3_source_findings(path, restored)


@pytest.mark.parametrize("path", TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS)
def test_task6_batch3_active_output_cannot_hide_in_dead_source(path):
    source = read_host(path)
    contract = TASK6_BATCH3_ACTIVE_OUTPUT_CONTRACTS[path]
    required = contract["required"][0]

    def remove_required_print(tree):
        removed = 0
        functions = {
            node.name: node for node in tree.body
            if isinstance(node, ast.FunctionDef)
        }
        for function_name in contract["functions"]:
            function = functions.get(function_name)
            if function is None:
                continue
            for call in ast.walk(function):
                if (not isinstance(call, ast.Call)
                        or not isinstance(call.func, ast.Name)
                        or call.func.id != "print"):
                    continue
                for argument in call.args:
                    for node in ast.walk(argument):
                        if (isinstance(node, ast.Constant)
                                and isinstance(node.value, str)
                                and required.lower() in node.value.lower()):
                            node.value = re.sub(
                                re.escape(required), "REMOVED_ACTIVE_OUTPUT",
                                node.value, flags=re.IGNORECASE,
                            )
                            removed += 1
        assert removed, (path, required)
        return functions

    doc_tree = ast.parse(source)
    remove_required_print(doc_tree)
    if (doc_tree.body and isinstance(doc_tree.body[0], ast.Expr)
            and isinstance(doc_tree.body[0].value, ast.Constant)
            and isinstance(doc_tree.body[0].value.value, str)):
        doc_tree.body[0].value.value += "\n" + required
    else:
        doc_tree.body.insert(0, ast.Expr(value=ast.Constant(required)))
    doc_mutant = ast.unparse(ast.fix_missing_locations(doc_tree))
    assert task6_batch3_active_output_findings(path, doc_mutant)

    dead_tree = ast.parse(source)
    functions = remove_required_print(dead_tree)
    root = functions[contract["functions"][0]]
    root.body.insert(0, ast.If(
        test=ast.Constant(False),
        body=[ast.Expr(value=ast.Call(
            func=ast.Name(id="print", ctx=ast.Load()),
            args=[ast.Constant(required)], keywords=[],
        ))],
        orelse=[],
    ))
    dead_mutant = ast.unparse(ast.fix_missing_locations(dead_tree))
    assert task6_batch3_active_output_findings(path, dead_mutant)

    forbidden_tree = ast.parse(source)
    functions = {
        node.name: node for node in forbidden_tree.body
        if isinstance(node, ast.FunctionDef)
    }
    root = functions[contract["functions"][0]]
    root.body.insert(0, ast.Expr(value=ast.Call(
        func=ast.Name(id="print", ctx=ast.Load()),
        args=[ast.Constant(contract["forbidden"][0])], keywords=[],
    )))
    forbidden_mutant = ast.unparse(ast.fix_missing_locations(forbidden_tree))
    assert task6_batch3_active_output_findings(path, forbidden_mutant)


def test_task6_batch3_pair_readout_keeps_entanglement_below_quarter(tmp_path):
    source = read_host("simulations/subsystem_crossing_pairs.py")
    functions = source_copy_definitions(
        source,
        {"bell_plus_dephased_pair", "isolated_bell_readout_books",
         "l1_coherence", "concurrence", "selected_pair_readout"},
        tmp_path,
        prelude=(
            "import numpy as np\n"
            "Y = np.array([[0, -1j], [1j, 0]], dtype=complex)\n"
        ),
    )
    rho = functions["bell_plus_dephased_pair"](0.5)
    assert functions["concurrence"](rho) == pytest.approx(0.5, rel=0, abs=1e-14)
    assert functions["selected_pair_readout"](rho) == pytest.approx(
        1/12, rel=0, abs=1e-14,
    )
    assert 0 < functions["concurrence"](rho)
    assert functions["selected_pair_readout"](rho) < 1/4
    books = functions["isolated_bell_readout_books"](0.5)
    assert books == pytest.approx({
        "concurrence": 1/12,
        "purity": 5/48,
        "constant": 1/6,
    }, rel=0, abs=1e-15)
    assert len(set(books.values())) == 3

    mutant = source.replace("return concurrence(rho) * l1_coherence(rho) / 3.0",
                            "return concurrence(rho) * l1_coherence(rho) / 2.0", 1)
    assert mutant != source
    changed = source_copy_definitions(
        mutant,
        {"bell_plus_dephased_pair", "isolated_bell_readout_books",
         "l1_coherence", "concurrence", "selected_pair_readout"},
        tmp_path,
        prelude=(
            "import numpy as np\n"
            "Y = np.array([[0, -1j], [1j, 0]], dtype=complex)\n"
        ),
    )
    assert changed["selected_pair_readout"](rho) != pytest.approx(1/12)


def test_task6_batch3_pair_crossing_time_has_direction_threshold_and_order(tmp_path):
    path = "simulations/subsystem_crossing_pairs.py"
    source = read_host(path)
    crossing_time = source_copy_definitions(
        source, {"crossing_time"}, tmp_path,
    )["crossing_time"]
    ts = np.array([0.0, 1.0, 2.0, 3.0])
    down = np.array([0.50, 0.20, 0.40, 0.10])
    up = np.array([0.10, 0.20, 0.40, 0.10])
    assert crossing_time(ts, down) == pytest.approx(5/6, rel=0, abs=1e-15)
    assert crossing_time(ts, up, level=0.25, direction="up") == pytest.approx(
        1.25, rel=0, abs=1e-15,
    )
    assert crossing_time(ts, down, level=0.55, direction="down") is None

    mutations = (
        ("vals[k - 1] > level >= vals[k]",
         "vals[k - 1] < level <= vals[k]"),
        ("range(1, len(vals))", "range(len(vals) - 1, 0, -1)"),
        ("level=0.25", "level=0.5"),
    )
    expected = (
        crossing_time(ts, down),
        crossing_time(ts, up, level=0.25, direction="up"),
        crossing_time(ts, down, level=0.55, direction="down"),
    )
    for old, new in mutations:
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        changed = source_copy_definitions(
            mutant, {"crossing_time"}, tmp_path,
        )["crossing_time"]
        observed = (
            changed(ts, down),
            changed(ts, up, level=0.25, direction="up"),
            changed(ts, down, level=0.55, direction="down"),
        )
        assert observed != expected, old

    assert not task6_batch3_pair_dataflow_findings(source)
    for old, new in (
        ("tc = crossing_time(ts, traj[p], level=0.25, direction=\"down\")",
         "tc = None"),
        ("ts, isolated_books[book_name], level=0.25, direction=\"down\",",
         "ts, isolated_books[\"concurrence\"], level=0.25, direction=\"down\","),
        ("row[\"pair\"] == (0, 1)", "row[\"pair\"] == (0, 2)"),
        ("isolated_times[\"concurrence\"] / ring_reference_time",
         "isolated_times[\"purity\"] / ring_reference_time"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        assert task6_batch3_pair_dataflow_findings(mutant), old


def test_task6_batch3_pair_finite_ring_and_isolated_time_oracles(tmp_path):
    from scipy.linalg import expm

    path = "simulations/subsystem_crossing_pairs.py"
    source = read_host(path)
    prelude = """import numpy as np
from scipy.linalg import expm
I2 = np.eye(2, dtype=complex)
X = np.array([[0, 1], [1, 0]], dtype=complex)
Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
Z = np.array([[1, 0], [0, -1]], dtype=complex)
"""
    functions = source_copy_definitions(
        source,
        {"site_op", "liouvillian", "heisenberg_ring", "heisenberg_chain",
         "ptrace_pair", "l1_coherence", "concurrence",
         "selected_pair_readout", "isolated_bell_readout_books",
         "crossing_time"},
        tmp_path,
        prelude=prelude,
    )

    gamma = 0.05
    isolated_ts = np.arange(0.0, 3.0, 0.0001)
    decay = np.exp(-4 * gamma * isolated_ts)
    books = functions["isolated_bell_readout_books"](decay)
    assert tuple(books) == ("concurrence", "purity", "constant")
    isolated_times = tuple(
        functions["crossing_time"](
            isolated_ts, books[name], level=0.25, direction="down",
        )
        for name in books
    )
    assert isolated_times == pytest.approx(
        (0.71920518122770627, 0.74700264995033772, 1.4384103623517899),
        rel=0, abs=5e-13,
    )
    assert isolated_times[0] < isolated_times[1] < isolated_times[2]

    up = np.array([1, 0], dtype=complex)
    down = np.array([0, 1], dtype=complex)
    bell = (np.kron(up, up) + np.kron(down, down)) / np.sqrt(2)
    state = np.kron(bell, bell)
    rho0 = np.outer(state, state.conj())
    N = 4
    dt = 0.01
    ring_ts = np.arange(0.0, 0.21, dt)

    def finite_pair_time(builder):
        generator = functions["liouvillian"](builder(N), gamma, N)
        step = expm(generator * dt)
        vector = rho0.reshape(-1)
        values = []
        for _ in ring_ts:
            rho = vector.reshape(2 ** N, 2 ** N)
            pair = functions["ptrace_pair"](rho, [0, 1], N)
            values.append(functions["selected_pair_readout"](pair))
            vector = step @ vector
        return functions["crossing_time"](
            ring_ts, np.asarray(values), level=0.25, direction="down",
        )

    ring_time = finite_pair_time(functions["heisenberg_ring"])
    chain_time = finite_pair_time(functions["heisenberg_chain"])
    assert ring_time == pytest.approx(
        0.079710695244099017, rel=0, abs=5e-13,
    )
    assert chain_time == pytest.approx(
        0.1527246972354273, rel=0, abs=5e-13,
    )
    assert chain_time != pytest.approx(ring_time, rel=0, abs=1e-3)

    topology_mutant = source.replace(
        "H = heisenberg_ring(N)", "H = heisenberg_chain(N)", 1,
    )
    assert topology_mutant != source
    assert task6_batch3_pair_dataflow_findings(topology_mutant)

    literal_mutant = source.replace(
        'f"{isolated_times[\'concurrence\']:.4f} / '
        '{ring_reference_time:.4f} "',
        '"0.7192 / 0.0797 "',
        1,
    )
    assert literal_mutant != source
    assert task6_batch3_pair_dataflow_findings(literal_mutant)


def test_task6_batch3_axis_census_is_tolerance_selected_not_a_vector_theorem(tmp_path):
    source = read_host("simulations/axis_modes_n4.py")
    functions = source_copy_definitions(
        source, {"axis_census", "reflection_parity_counts"}, tmp_path,
        prelude="import numpy as np\nfrom math import comb\n",
    )
    copied = functions["axis_census"]
    eigvals = np.array([0.0, 0.5, 1.0, 1.5], dtype=complex)
    assert copied(eigvals, 4, 0.0, 1.0) == (2, 96, 94)
    with pytest.raises(ValueError, match="N=4"):
        copied(np.array([-0.15, 0.0], dtype=complex), 3, 0.05, 1e-9)
    mutant = source.replace("< tolerance", "<= tolerance", 1)
    assert mutant != source
    mutated = source_copy_definitions(
        mutant, {"axis_census"}, tmp_path,
        prelude="import numpy as np\nfrom math import comb\n",
    )["axis_census"]
    assert mutated(eigvals, 4, 0.0, 1.0) != (2, 96, 94)

    rank_deficient = np.array([[1.0, 2.0], [0.0, 0.0]], dtype=complex)
    reflection = np.diag([1.0, -1.0]).astype(complex)
    assert functions["reflection_parity_counts"](
        rank_deficient, reflection,
    ) == (1, 0, 0)
    for old, new in (
        ("singular_values > span_tolerance", "singular_values >= 0.0"),
        ("left_vectors[:, :rank]", "left_vectors"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        changed = source_copy_definitions(
            mutant, {"reflection_parity_counts"}, tmp_path,
            prelude="import numpy as np\n",
        )["reflection_parity_counts"]
        assert changed(rank_deficient, reflection) != (1, 0, 0), old


def test_task6_batch3_pi_map_and_run_dataflow_are_live(tmp_path):
    path = "simulations/test_bidirectional_bridge.py"
    source = read_host(path)
    assert not task6_batch3_bridge_dataflow_findings(source)
    prelude = """import numpy as np
from itertools import product as iprod
I2 = np.eye(2, dtype=complex)
X = np.array([[0,1],[1,0]], dtype=complex)
Y = np.array([[0,-1j],[1j,0]], dtype=complex)
Z = np.array([[1,0],[0,-1]], dtype=complex)
PAULIS = [I2, X, Y, Z]
"""
    copied = source_copy_definitions(
        source,
        {"kron_list", "pi_map_index", "pauli_decompose", "pauli_recompose",
         "apply_pi"},
        tmp_path,
        prelude=prelude,
    )
    I2 = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    np.testing.assert_allclose(copied["apply_pi"](I2, 1), X, rtol=0, atol=0)
    np.testing.assert_allclose(copied["apply_pi"](X, 1), I2, rtol=0, atol=0)
    np.testing.assert_allclose(copied["apply_pi"](Y, 1), 1j * Z, rtol=0, atol=0)
    np.testing.assert_allclose(copied["apply_pi"](Z, 1), 1j * Y, rtol=0, atol=0)
    ket0 = np.array([1, 0], dtype=complex)
    rho0 = np.outer(ket0, ket0.conj())
    expected_nonstate = np.array([[0, 1], [0, 0]], dtype=complex)
    operator_pi = copied["apply_pi"](rho0, 1)
    np.testing.assert_allclose(operator_pi, expected_nonstate, rtol=0, atol=0)
    assert np.trace(operator_pi) == 0
    assert not np.allclose(operator_pi, operator_pi.conj().T)
    probe = np.array([[1+2j, 3-1j], [-4j, -2+0.5j]], dtype=complex)
    transformed = probe
    for _ in range(4):
        transformed = copied["apply_pi"](transformed, 1)
    np.testing.assert_allclose(transformed, probe, rtol=0, atol=2e-15)
    assert np.linalg.norm(copied["apply_pi"](probe, 1), "fro") == pytest.approx(
        np.linalg.norm(probe, "fro"), rel=0, abs=2e-15,
    )
    for old, new in (
        ("operator_pi = apply_pi(rho, N)", "operator_pi = rho"),
        ("operator01_pi = partial_trace(operator_pi, N, [0, 1])",
         "operator01_pi = partial_trace(rho, N, [0, 1])"),
        ("scalar01_pi = selected_scalar_readout(operator01_pi)",
         "scalar01_pi = selected_scalar_readout(rho01_original)"),
        ("adjacent_sum_mi = mi01 + mi12",
         "adjacent_sum_mi = mi01 + mi12 + mi02"),
        ('"adjacent_sum_mi": adjacent_sum_mi',
         '"adjacent_sum_mi": mi01 + mi02 + mi12'),
        ('"pi_operator": (scalar01_pi, scalar02_pi, scalar12_pi)',
         '"pi_operator": (scalar01_original, scalar02_original, scalar12_original)'),
        ('original = row["original"]', 'original = row["pi_operator"]'),
        ('pi_operator = row["pi_operator"]', 'pi_operator = row["original"]'),
        ("best = rows[best_index]", "best = rows[-1]"),
        ("best_index = max(range(len(rows)), key=lambda index: rows[index][\"adjacent_sum_mi\"])",
         "best_index = len(rows) - 1"),
        ('if index == best_index else ""', 'if index != best_index else ""'),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        assert task6_batch3_bridge_dataflow_findings(mutant), old

    table_mutant = source.replace("pi_operator[", "original[")
    assert table_mutant != source
    assert task6_batch3_bridge_dataflow_findings(table_mutant)

    phase_mutant = source.replace(
        "if a == 2: return 3, 1j", "if a == 2: return 3, 1.0", 1,
    )
    assert phase_mutant != source
    phase_copy = source_copy_definitions(
        phase_mutant,
        {"kron_list", "pi_map_index", "pauli_decompose", "pauli_recompose",
         "apply_pi"},
        tmp_path,
        prelude=prelude,
    )
    assert not np.allclose(phase_copy["apply_pi"](Y, 1), 1j * Z)


