def test_task6_batch3_formula_four_finite_models_are_computed(tmp_path):
    source = read_host("simulations/formula_four_classification.py")
    functions = source_copy_definitions(
        source, {"all_states", "hamming", "dephasing_rate_ladder",
                 "se_band", "se_band_multiplicity"}, tmp_path,
        prelude="import itertools\nimport numpy as np\nGAMMA=0.05\nJ=1.0\n",
    )
    expected = [0.0, 0.1, 0.2]
    assert functions["dephasing_rate_ladder"](2, 2) == expected
    assert functions["dephasing_rate_ladder"](3, 2) == expected
    b2 = functions["se_band"](2, 4)
    b3 = functions["se_band"](3, 4)
    assert b2 == b3
    assert functions["se_band_multiplicity"](2, 4) == 1
    assert functions["se_band_multiplicity"](3, 4) == 2
    assert max(abs(b2[0]), abs(b2[-1])) == pytest.approx(
        2*np.cos(np.pi/5), rel=0, abs=1e-9,
    )
    for old, new in (
        ("2.0 * GAMMA * hamming(a, b)", "GAMMA * hamming(a, b)"),
        ("H[idx[s2], a] += J", "H[idx[s2], a] += 2 * J"),
        ("return d - 1", "return d"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        changed = source_copy_definitions(
            mutant, {"all_states", "hamming", "dephasing_rate_ladder",
                     "se_band", "se_band_multiplicity"}, tmp_path,
            prelude="import itertools\nimport numpy as np\nGAMMA=0.05\nJ=1.0\n",
        )
        verdict = (
            changed["dephasing_rate_ladder"](3, 2),
            changed["se_band"](3, 4),
            changed["se_band_multiplicity"](3, 4),
        )
        assert verdict != (expected, b3, 2), old


def test_task6_batch3_f97_selected_and_other_roots_are_distinct(tmp_path):
    source = read_host("simulations/cardioid_parametrization_tier1.py")
    functions = source_copy_definitions(
        source,
        {"period_one_cardioid_point", "fixed_points_at", "fixed_point_at",
         "wrapped_angle"},
        tmp_path,
    )
    radial_magnitudes = []
    for phi in (0.0, np.pi/2, np.pi, 2*np.pi - 1e-12):
        z_star, c = functions["period_one_cardioid_point"](phi)
        radial_magnitudes.append(abs(c))
        assert z_star*z_star - z_star + c == pytest.approx(0j, abs=1e-14)
        assert abs(2*z_star) == pytest.approx(1.0, rel=0, abs=1e-14)
        roots = functions["fixed_points_at"](c)
        assert min(abs(root-z_star) for root in roots) < 2e-8
        assert functions["wrapped_angle"](z_star) == pytest.approx(
            phi % (2*np.pi), rel=0, abs=2e-12,
        )
    z_star, c = functions["period_one_cardioid_point"](np.pi/2)
    other = 1 - z_star
    assert abs(2*other) == pytest.approx(np.sqrt(5), rel=0, abs=1e-14)
    assert functions["fixed_points_at"](0j) == pytest.approx((0j, 1+0j))
    assert functions["fixed_point_at"](0j, 0.1 + 0j) == 0j
    assert functions["fixed_point_at"](0j, 0.9 + 0j) == 1 + 0j
    assert max(radial_magnitudes) - min(radial_magnitudes) == pytest.approx(
        0.5, rel=0, abs=1e-14,
    )

    for old, new in (
        ("c = z_star - z_star * z_star", "c = z_star + z_star * z_star"),
        ("return (angle + 2 * np.pi) % (2 * np.pi)", "return angle"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        changed = source_copy_definitions(
            mutant,
            {"period_one_cardioid_point", "fixed_points_at", "fixed_point_at",
             "wrapped_angle"},
            tmp_path,
        )
        mz, mc = changed["period_one_cardioid_point"](np.pi/2)
        checks = (
            abs(mz*mz - mz + mc) < 1e-14,
            abs(changed["wrapped_angle"](
                changed["period_one_cardioid_point"](2*np.pi-1e-12)[0]
            ) - (2*np.pi-1e-12)) < 2e-12,
        )
        assert checks != (True, True), old

    selector_mutant = source.replace(
        "return min(fixed_points_at(c), key=lambda root: abs(root - target))",
        "return target", 1,
    )
    assert selector_mutant != source
    changed = source_copy_definitions(
        selector_mutant, {"fixed_points_at", "fixed_point_at"}, tmp_path,
        prelude="import numpy as np\n",
    )
    assert changed["fixed_point_at"](0j, 0.1 + 0j) != 0j

    consumer_mutant = source.replace(
        "selected = fixed_point_at(c, z_star)", "selected = z_star", 1,
    )
    assert consumer_mutant != source
    assert task6_batch3_source_findings(
        "simulations/cardioid_parametrization_tier1.py", consumer_mutant,
    )

    for old, new in (
        ("assert abs((max(magnitudes) - min(magnitudes)) - 0.5) < tolerance",
         "assert max(magnitudes) - min(magnitudes) > 0.5"),
        ("assert abs((max(magnitudes) - min(magnitudes)) - 0.5) < tolerance",
         "assert abs((max(magnitudes) - min(magnitudes)) - 0.4) < tolerance"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        assert task6_batch3_source_findings(
            "simulations/cardioid_parametrization_tier1.py", mutant,
        ), new


def test_task6_batch3_heavy_water_closed_form_without_execution(tmp_path):
    path = "simulations/water/proton_chain_dicke_anchor.py"
    source = read_host(path)
    functions = source_copy_definitions(
        source,
        {"classify_dicke_anchor", "alpha_infinity_closed_form",
         "alpha_total_predicted", "gamma_predicted",
         "krawtchouk_subset_sum", "odd_krawtchouk_norm"},
        tmp_path,
        prelude="from fractions import Fraction\nfrom math import comb\n",
    )
    function = functions["alpha_infinity_closed_form"]
    assert function(4) == Fraction(3, 10)
    assert function(6) == Fraction(2, 7)
    assert function(8) == Fraction(5, 18)
    assert function(10) == Fraction(3, 11)
    assert function(12) == Fraction(7, 26)
    assert function(14) == Fraction(4, 15)
    assert function(16) == Fraction(9, 34)
    assert [functions["krawtchouk_subset_sum"](4, 1, subset)
            for subset in range(5)] == [4, 2, 0, -2, -4]
    assert [functions["krawtchouk_subset_sum"](4, 2, subset)
            for subset in range(5)] == [6, 0, -2, 0, 6]
    assert [functions["krawtchouk_subset_sum"](6, 2, subset)
            for subset in range(7)] == [15, 5, -1, -3, -1, 5, 15]
    assert functions["odd_krawtchouk_norm"](4, 1) == Fraction(2, 1)
    assert functions["odd_krawtchouk_norm"](6, 2) == Fraction(15, 2)
    assert functions["classify_dicke_anchor"](3, 1) == "Mirror"
    assert functions["classify_dicke_anchor"](4, 1) == "KIntermediate"
    assert functions["classify_dicke_anchor"](6, 2) == "KIntermediate"
    assert functions["classify_dicke_anchor"](6, 1) == "Generic"
    assert tuple(functions["alpha_total_predicted"](anchor) for anchor in
                 ("Mirror", "KIntermediate", "Generic")) == (0.0, 3/8, 1/2)
    assert tuple(functions["gamma_predicted"](anchor) for anchor in
                 ("Mirror", "KIntermediate", "Generic")) == (1.0, 1/2, 0.0)
    assert not task6_batch3_water_model_findings(source)

    mutations = (
        ("Fraction(N + 2, 4 * (N + 1))",
         "Fraction(N + 1, 4 * (N + 1))"),
        ("2 * weight + 1 == N", "2 * weight == N"),
        ('"KIntermediate": 3.0 / 8.0',
         '"KIntermediate": 1.0 / 4.0'),
        ('"KIntermediate": 0.5', '"KIntermediate": 0.25'),
        ("(-1) ** intersection", "1 ** intersection"),
        ("Fraction(numerator, 2 ** N)", "Fraction(numerator, 2 ** (N - 1))"),
    )
    expected = (
        function(4),
        functions["classify_dicke_anchor"](3, 1),
        tuple(functions["krawtchouk_subset_sum"](4, 1, subset)
              for subset in range(5)),
        functions["odd_krawtchouk_norm"](6, 2),
    )
    for old, new in mutations:
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        changed = source_copy_definitions(
            mutant,
            {"classify_dicke_anchor", "alpha_infinity_closed_form",
             "alpha_total_predicted", "gamma_predicted",
             "krawtchouk_subset_sum", "odd_krawtchouk_norm"},
            tmp_path,
            prelude="from fractions import Fraction\nfrom math import comb\n",
        )
        observed = (
            changed["alpha_infinity_closed_form"](4),
            changed["classify_dicke_anchor"](3, 1),
            changed["alpha_total_predicted"]("KIntermediate"),
            changed["gamma_predicted"]("KIntermediate"),
            tuple(changed["krawtchouk_subset_sum"](4, 1, subset)
                  for subset in range(5)),
            changed["odd_krawtchouk_norm"](6, 2),
        )
        assert observed != (
            expected[0], expected[1], 3/8, 1/2, expected[2], expected[3],
        ), old

    for old, new in (
        ("[[0, 1], [1, 0]]", "[[0, -1j], [1j, 0]]"),
        ("for operator in (SX, SY, SZ)", "for operator in (SX, SY)"),
        ("(J / 4.0)", "(J / 2.0)"),
        ("for site in range(N)", "for site in range(N - 1)"),
        ("site_op(SZ, site, N)", "site_op(SX, site, N)"),
        ("LETTER_PARITY = (0, 0, 1, 1)",
         "LETTER_PARITY = (0, 1, 0, 1)"),
    ):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        assert task6_batch3_water_model_findings(mutant), old


