def task6_whirlpool_mapping_findings(rows):
    findings = []
    selected = tuple(row for row in rows if 12 <= int(row[0][-2:]) <= 18)
    expected = TASK6_PROMOTION_CONTRACTS[11:18]
    if selected != expected:
        findings.append("WHIRLPOOL_ROWS")
    producers = tuple(row[3] for row in selected)
    if len(selected) != 7 or len(set(producers)) != 6:
        findings.append("WHIRLPOOL_7_FROM_6")
    counts = {producer: producers.count(producer) for producer in set(producers)}
    if counts.get("simulations/whirlpool.py") != 2:
        findings.append("WHIRLPOOL_DOUBLE_OWNER")
    if any(count != (2 if producer == "simulations/whirlpool.py" else 1)
           for producer, count in counts.items()):
        findings.append("WHIRLPOOL_OWNER_MULTIPLICITY")
    return tuple(findings)


