def task6_render_seam_promotion_findings(
        seams=TASK6_RENDER_SEAM_CONTRACTS,
        rows=TASK6_PROMOTION_CONTRACTS):
    findings = []
    grouped = {}
    for row in rows:
        grouped.setdefault(row[3], []).append(Path(row[4]).name)
    if tuple(seams) != tuple(grouped):
        findings.append("PRODUCER_ORDER")
    if set(seams) != set(grouped):
        findings.append("PRODUCER_SET")
    for producer in set(seams) | set(grouped):
        expected = tuple(grouped.get(producer, ()))
        observed = tuple(seams.get(producer, {}).get("outputs", ()))
        if observed != expected:
            findings.append(f"{producer}:ORDERED_LEAVES")
    if sum(len(contract["outputs"]) for contract in seams.values()) != 19:
        findings.append("OUTPUT_COUNT")
    return tuple(findings)


