def task6_formula_index_sections(source):
    """Return the four real registry entries, bounded by their live headings."""
    matches = list(re.finditer(r"(?m)^### F(94|95|96|97|98)\.", source))
    labels = tuple(match.group(1) for match in matches)
    if labels != ("94", "95", "96", "97", "98"):
        return {}, (f"FORMULA_INDEX:HEADING_ORDER:{labels}",)
    sections = {
        f"F{matches[index].group(1)}": source[
            matches[index].start():matches[index + 1].start()
        ]
        for index in range(4)
    }
    return sections, ()


def task6_formula_index_findings(source):
    sections, findings = task6_formula_index_sections(source)
    findings = list(findings)
    if findings:
        return tuple(findings)
    for fid, contract in TASK6_FORMULA_INDEX_CONTRACTS.items():
        normalized = re.sub(r"\s+", " ", sections[fid]).strip()
        for phrase in contract["required"]:
            if phrase.casefold() not in normalized.casefold():
                findings.append(f"{fid}:MISSING_OWNER:{phrase}")
        for phrase in contract["forbidden"]:
            if phrase.casefold() in normalized.casefold():
                findings.append(f"{fid}:STALE_LABEL:{phrase}")

    block = "\n".join(sections.values())
    for label in TASK6_FORMULA_INDEX_TYPED_EDGE_LABELS:
        if label in block:
            findings.append(f"FORMULA_INDEX:TYPED_EDGE:{label}")
    if re.search(r"O\s*\(\s*Q(?:\^?3|³)\s*K(?:\^?4|⁴)\s*\)", block, re.I):
        findings.append("F94:FIXED_REMAINDER_MONOMIAL")
    return tuple(findings)


def _task6_formula_index_inject(source, fid, phrase):
    next_fid = int(fid.removeprefix("F")) + 1
    marker = f"\n### F{next_fid}."
    assert source.count(marker) == 1, (fid, marker)
    return source.replace(marker, f"\n{phrase}\n{marker}", 1)


def _task6_formula_index_remove_phrase(source, fid, phrase):
    next_fid = int(fid.removeprefix("F")) + 1
    match = re.search(
        rf"(?ms)^### {fid}\..*?(?=^### F{next_fid}\.)", source
    )
    assert match is not None, fid
    flexible = r"\s+".join(map(re.escape, phrase.split()))
    changed, count = re.subn(flexible, "", match.group(0), flags=re.I)
    assert count >= 1, (fid, phrase)
    return source[:match.start()] + changed + source[match.end():]


