def task6_claim_scope_findings():
    findings = []
    claims = {
        "F94": "compute/RCPsiSquared.Core/Symmetry/F94BornDeviationFourThirdsPi2Inheritance.cs",
        "F95": "compute/RCPsiSquared.Core/Symmetry/F95AngleAtQuadraticZeroPi2Inheritance.cs",
        "F96": "compute/RCPsiSquared.Core/Symmetry/F96BornSubdominantSlopesPi2Inheritance.cs",
        "F97": "compute/RCPsiSquared.Core/Symmetry/F97CardioidHalfFixedPointPi2Inheritance.cs",
    }
    for fid, path in claims.items():
        source = read_host(path)
        class_name = re.search(rf"public sealed class ({fid}\w+)\s*:\s*([^\n{{]+)", source)
        if class_name is None:
            findings.append(f"{fid}:CLASS")
            continue
        bases = class_name.group(2)
        if "Claim" not in bases or "IZ2AxisClaim" in bases:
            findings.append(f"{fid}:BASES:{bases}")
        if re.search(r"public\s+[A-Za-z0-9_]*Claim\s+\w+\s*\{\s*get;", source):
            findings.append(f"{fid}:TYPED_PARENT")
        if not re.search(rf"public\s+{re.escape(class_name.group(1))}\s*\(\s*\)", source):
            findings.append(f"{fid}:PARAMETERLESS_CTOR")
    for path in (
        "compute/RCPsiSquared.Runtime/PolarityArchitecture/PolarityCubeMapRegistration.cs",
        "compute/RCPsiSquared.Core/Knowledge/ClaimGraphWalker.cs",
    ):
        source = read_host(path)
        for fid in claims:
            if re.search(rf"\b{fid}\w*(?:Pi2Inheritance)?\b", source):
                findings.append(f"{path}:{fid}:FABRICATED_ANCESTRY")
    return findings


