def test_task6_f97_pi_over_three_label_is_source_bound_and_numerically_exact():
    source = read_host(TASK6_F97_CARDINAL_PATH)
    assert not task6_f97_cardinal_label_findings(source), \
        task6_f97_cardinal_label_findings(source)

    phi = sp.symbols("phi", real=True)
    c = sp.exp(sp.I * phi) / 2 - sp.exp(2 * sp.I * phi) / 4
    at_sixty = sp.expand_complex(c.subs(phi, sp.pi / 3))
    at_upper_max = sp.expand_complex(c.subs(phi, 2 * sp.pi / 3))
    assert sp.simplify(at_sixty - (sp.Rational(3, 8) + sp.I * sp.sqrt(3) / 8)) == 0
    assert sp.simplify(sp.atan2(sp.im(at_sixty), sp.re(at_sixty)) - sp.pi / 6) == 0
    assert sp.simplify(at_upper_max - (-sp.Rational(1, 8) + 3 * sp.I * sp.sqrt(3) / 8)) == 0

    imaginary = sp.simplify(sp.im(sp.expand_complex(c)))
    assert sp.simplify(sp.diff(imaginary, phi).subs(phi, 2 * sp.pi / 3)) == 0
    assert sp.diff(imaginary, phi, 2).subs(phi, 2 * sp.pi / 3) < 0
    assert sp.im(at_upper_max) > sp.im(at_sixty)


