def _task6_whirlpool_f25_geometry_findings(path, tree, helper_name,
                                            expected_arguments):
    reachable = _task6_reachable_functions(tree)
    live_nodes = tuple(node for function in reachable.values()
                       for node in _task6_live_nodes(function))
    bindings = [
        node for node in live_nodes if isinstance(node, ast.Assign)
        and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == "radius"
        and _task6_direct_call_signature(node.value)
        == (helper_name, expected_arguments)
    ]
    stores = [node for node in live_nodes if isinstance(node, ast.Name)
              and isinstance(node.ctx, ast.Store) and node.id == "radius"]
    live_text = "\n".join(ast.unparse(function)
                           for function in reachable.values())
    missing = tuple(fragment for fragment
                    in TASK6_WHIRLPOOL_F25_GEOMETRY_REQUIREMENTS[path]
                    if fragment not in live_text)
    if len(bindings) != 1 or len(stores) != 1 or missing:
        return [f"{path}:F25_GEOMETRY_BINDING:"
                f"bindings={len(bindings)}:stores={len(stores)}:missing={missing!r}"]
    return []


def _task6_whirlpool_active_control_findings(path, tree):
    if path not in TASK6_WHIRLPOOL_WRITERS:
        return []
    special_tags = {}
    for function in _task6_reachable_functions(tree).values():
        for node in _task6_live_nodes(function):
            if (not isinstance(node, ast.Call)
                    or _task6_call_method_name(node) not in TASK6_TEXT_METHODS):
                continue
            payloads = [part for part in ast.walk(node)
                        if isinstance(part, ast.Constant)
                        and part.value == TASK6_WHIRLPOOL_ACTIVE_CONTROL_TEXT]
            for payload in payloads:
                special_tags[id(payload)] = {"whirlpool:f25-active-controls"}
    emissions = _task6_semantic_render_emissions(
        tree, TASK6_RENDER_SEAM_CONTRACTS[path], special_tags=special_tags,
    )
    findings = []
    for leaf in TASK6_RENDER_SEAM_CONTRACTS[path]["outputs"]:
        owned = [emission for emission in emissions if emission["leaf"] == leaf]
        if (not owned or not any("whirlpool:f25-active-controls"
                                 in emission["text"] for emission in owned)):
            evidence = tuple(
                (emission["call_path"], sorted(emission["text"]))
                for emission in owned
            )
            findings.append(
                f"{path}:{leaf}:WHIRLPOOL_ACTIVE_CONTROL:{evidence!r}"
            )
    return findings


def _task6_whirlpool_integration_findings(path, tree):
    if path not in TASK6_WHIRLPOOL_WRITERS:
        return []
    findings = []
    doc = ast.get_docstring(tree, clean=False) or ""
    controls = [
        ("UNIQUE", r"(?:(?:unique|one)\s+finite[\s\S]{0,80}?crossing|"
                   r"crossing[\s\S]{0,40}?unique|unique[\s\S]{0,40}?crossing)"),
        ("CONCURRENCE", r"C=f(?:>0)?"),
        ("HALF_CONTROL", r"f=1/2[\s\S]{0,100}?r=5/48(?:<1/4)?"
                         r"[\s\S]{0,80}?C=1/2"),
    ]
    if path in {
        "simulations/whirlpool.py",
        "simulations/whirlpool_anchor_views.py",
    }:
        controls.append(("FSTAR", r"f=0\.8612240997395736"))
    for label, pattern in controls:
        if not re.search(pattern, doc):
            findings.append(f"{path}:WHIRLPOOL_CONTROL_{label}")

    findings.extend(_task6_whirlpool_active_control_findings(path, tree))

    if path != "simulations/whirlpool_4d.py":
        return findings
    frame_assignments = [
        node for node in tree.body if isinstance(node, ast.Assign)
        and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == "FRAMES"
    ]
    try:
        frames = (ast.literal_eval(frame_assignments[0].value)
                  if len(frame_assignments) == 1 else None)
    except (TypeError, ValueError):
        frames = None
    if frames != TASK6_WHIRLPOOL_4D_FRAMES:
        findings.append(f"{path}:BETA_FRAME_TABLE")
    main = _task6_top_level_functions(tree).get("main")
    nodes = () if main is None else _task6_live_nodes(main)
    frame_loops = [
        node for node in nodes if isinstance(node, ast.For)
        and ast.dump(node.target, include_attributes=False) == ast.dump(
            ast.parse("for index, (degrees, label, palette) in ():\n    pass")
            .body[0].target, include_attributes=False)
        and ast.unparse(node.iter) == "enumerate(FRAMES)"
    ]
    cosine = [
        node for node in nodes if isinstance(node, ast.Assign)
        and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == "c"
        and ast.dump(node.value, include_attributes=False) == ast.dump(
            ast.parse("np.cos(np.radians(degrees))", mode="eval").body,
            include_attributes=False,
        )
    ]
    x_collapse = [
        node for node in nodes if isinstance(node, ast.Assign)
        and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == "xr"
        and ast.dump(node.value, include_attributes=False) == ast.dump(
            ast.parse("x * c", mode="eval").body, include_attributes=False,
        )
    ]
    point_arrays = [
        node for node in nodes if isinstance(node, ast.Call)
        and ast.unparse(node.func) == "np.array" and node.args
        and ast.unparse(node.args[0]) == "[xr, y, z]"
    ]
    ring_plots = [
        node for node in nodes if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute) and node.func.attr == "plot"
        and tuple(ast.unparse(argument) for argument in node.args[:3])
        == ("ring_x * c", "ring_y", "ring_z")
    ]
    if not (len(cosine) == len(x_collapse) == len(point_arrays)
            == len(ring_plots) == len(frame_loops) == 1):
        findings.append(
            f"{path}:BETA90_YZ_BINDING:"
            f"{(len(frame_loops), len(cosine), len(x_collapse), len(point_arrays), len(ring_plots))}"
        )
    if len(cosine) == len(ring_plots) == 1:
        emissions = _task6_semantic_render_emissions(
            tree, TASK6_RENDER_SEAM_CONTRACTS[path],
            special_tags={id(ring_plots[0].args[0]): {"q16:beta-frame"}},
        )
        owned = [emission for emission in emissions
                 if emission["leaf"] == "whirlpool_4d.png"]
        if not owned or not any("q16:beta-frame" in emission["geometry"]
                                for emission in owned):
            findings.append(f"{path}:BETA_FRAME_TO_Q16")
    return findings


def _task6_source_review_findings(path, tree, source):
    findings = []
    doc = ast.get_docstring(tree, clean=False) or ""
    reachable = _task6_reachable_functions(tree)
    live_text = "\n".join(ast.unparse(function)
                           for function in reachable.values())
    visible = _task6_visible_call_text(tree)
    if path == "simulations/spiral_slowing.py":
        if re.search(r"eigenvalue\s*(?:−|-)?\s*(?:γ|gamma)[₀0]?", source,
                     re.I):
            findings.append(f"{path}:COHERENCE_NOT_GENERATOR_EIGENVALUE")
        if "decay factor ``exp(-4 gamma t)`` and rate ``4 gamma``" not in doc:
            findings.append(f"{path}:COHERENCE_RATE_SCOPE")
        if "decay factor exp(-4 gamma t); rate 4 gamma" not in visible:
            findings.append(f"{path}:COHERENCE_RATE_VISIBLE")
    elif path == "simulations/cpsi_complex_plane.py":
        if "ρ_{00,11}(0) = (1/2) · exp(-iφ)" not in doc:
            findings.append(f"{path}:INITIAL_COHERENCE_PHASE_SIGN")
        if "ρ_{00,11}(t) = (1/2) · exp[-i(φ + Ωt) - 4γt]" not in doc:
            findings.append(f"{path}:EVOLVED_COHERENCE_PHASE_SIGN")
        phase_labels = [
            node for node in ast.walk(tree) if isinstance(node, ast.JoinedStr)
            and "initial c_plot phase=" in "".join(
                part.value for part in node.values
                if isinstance(part, ast.Constant)
                and isinstance(part.value, str)
            )
        ]
        negative_phi = [] if len(phase_labels) != 1 else [
            part for part in ast.walk(phase_labels[0])
            if isinstance(part, ast.FormattedValue)
            and isinstance(part.value, ast.UnaryOp)
            and isinstance(part.value.op, ast.USub)
            and isinstance(part.value.operand, ast.Name)
            and part.value.operand.id == "phi0"
        ]
        if len(phase_labels) != 1 or len(negative_phi) != 1:
            findings.append(f"{path}:VISIBLE_INITIAL_COORDINATE_PHASE")
    elif path == "simulations/hardware_cpsi_cplane.py":
        if "not a standalone detuning or calibration estimate" not in doc:
            findings.append(f"{path}:SPARSE_PHASE_SCOPE")
        if "not standalone detuning/calibration evidence" not in visible:
            findings.append(f"{path}:SPARSE_PHASE_VISIBLE")
        if re.search(r"well[- ]calibrated|little\s+Z[- ]drift|residual\s+Z[- ]detuning",
                     live_text, re.I):
            findings.append(f"{path}:PHASE_CAUSAL_INFERENCE")
        if "do not by themselves estimate residual detuning or calibration" \
                not in live_text:
            findings.append(f"{path}:PHASE_STDOUT_SCOPE")
    return findings


def task6_writer_static_findings(path, source):
    findings = list(import_safety_findings(path, source))
    contract = TASK6_RENDER_SEAM_CONTRACTS[path]
    tree = ast.parse(source)
    functions = _task6_top_level_functions(tree)
    mains = [node for node in tree.body
             if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
             and node.name == "main"]
    main = mains[0] if len(mains) == 1 else None
    if main is None:
        findings.append(f"{path}:MAIN_COUNT:{len(mains)}")
    else:
        args = _task6_function_parameters(main)
        if args != contract["main_args"] or main.args.vararg or main.args.kwarg:
            findings.append(f"{path}:MAIN_SIGNATURE:{args!r}")
        if main.args.defaults or any(value is not None for value in main.args.kw_defaults):
            findings.append(f"{path}:DEFAULT_MAIN_ARGUMENT")

    findings.extend(_task6_argparse_findings(path, tree, contract))
    _, route_findings = _task6_output_routes(path, tree, contract)
    findings.extend(route_findings)
    findings.extend(_task6_json_findings(path, tree, contract))

    reachable_nodes = tuple(
        node for function in _task6_reachable_functions(tree).values()
        for node in _task6_live_nodes(function)
    )
    cwd_or_glob = [
        node for node in reachable_nodes if isinstance(node, ast.Call)
        and ((isinstance(node.func, ast.Attribute)
              and node.func.attr in {"cwd", "getcwd", "glob", "rglob"})
             or ast.unparse(node.func) in {"Path.cwd", "os.getcwd"})
    ]
    if cwd_or_glob:
        findings.append(f"{path}:CALLER_CWD_OR_GLOB")
    live_literals = {
        node.value for node in reachable_nodes
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    }
    tracked_literals = [artifact for artifact in QUARTER_RENDERED_ARTIFACTS
                        if artifact in live_literals]
    if tracked_literals:
        findings.append(f"{path}:TRACKED_OUTPUT_LITERAL:{tracked_literals!r}")

    visible = _task6_visible_call_text(tree)
    for required in TASK6_RENDER_VISIBLE_CONTRACTS[path]:
        if required not in visible:
            findings.append(f"{path}:VISIBLE:{required}")

    if path == "simulations/plot_cusp_precision.py":
        findings.extend(_task6_precision_gamma_findings(path, tree))
    findings.extend(_task6_quarter_primitive_findings(path, tree))
    findings.extend(_task6_spiral_decay_findings(path, tree))
    findings.extend(_task6_cpsi_dynamics_findings(path, tree))
    findings.extend(_task6_f97_render_findings(path, tree))
    findings.extend(_task6_f25_render_findings(path, tree))
    findings.extend(_task6_whirlpool_integration_findings(path, tree))
    findings.extend(_task6_source_review_findings(path, tree, source))
    return tuple(findings)


def _task6_render_static_mutants(path, source):
    """Mutate live syntax, never a comment/docstring-only decoy."""
    contract = TASK6_RENDER_SEAM_CONTRACTS[path]
    tree = ast.parse(source)
    mutants = {}

    destination_tree = ast.parse(source)
    destination_flow = _task6_render_flow(destination_tree, contract)
    path_call = next(
        node for node, argument, _function in destination_flow["path_calls"]
        if argument == ("main-argument", contract["output_arg"])
    )
    path_call.args[0] = ast.Constant("simulations/results/task6-bypass")
    mutants["destination-bypass"] = ast.unparse(
        ast.fix_missing_locations(destination_tree)
    )

    default_tree = ast.parse(source)
    default_main = _task6_top_level_functions(default_tree)["main"]
    if default_main.args.posonlyargs or default_main.args.args:
        default_main.args.defaults = [ast.Constant(None)]
    else:
        default_main.args.kw_defaults[-1] = ast.Constant(None)
    mutants["default-fallback"] = ast.unparse(ast.fix_missing_locations(default_tree))

    cli_tree = ast.parse(source)
    cli_guard = _task6_main_guard(cli_tree)
    cli_parser_binding = next(
        node for node in _task6_live_nodes(cli_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == "argparse.ArgumentParser"
    )
    cli_parser_name = cli_parser_binding.targets[0].id
    cli_call = next(
        node for node in _task6_live_nodes(cli_guard)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
        and node.func.attr == "add_argument"
        and ast.unparse(node.func.value) == cli_parser_name
        and node.args and isinstance(node.args[0], ast.Constant)
        and node.args[0].value == next(item[0] for item in contract["cli"]
                                      if item[0].startswith("--"))
    )
    required = next(keyword for keyword in cli_call.keywords
                    if keyword.arg == "required")
    required.value = ast.Constant(False)
    mutants["optional-cli-output"] = ast.unparse(ast.fix_missing_locations(cli_tree))

    parser_tree = ast.parse(source)
    parser_guard = _task6_main_guard(parser_tree)
    parser_binding = next(
        node for node in _task6_live_nodes(parser_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == "argparse.ArgumentParser"
    )
    parser_name = parser_binding.targets[0].id
    parse_assignment = next(
        node for node in _task6_live_nodes(parser_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == f"{parser_name}.parse_args"
    )
    parse_assignment.targets[0].id = "discarded_cli_namespace"
    mutants["parse-result-discarded"] = ast.unparse(ast.fix_missing_locations(parser_tree))

    rebind_tree = ast.parse(source)
    rebind_guard = _task6_main_guard(rebind_tree)
    rebind_parser = next(
        node for node in _task6_live_nodes(rebind_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == "argparse.ArgumentParser"
    ).targets[0].id
    rebind_namespace = next(
        node.targets[0].id for node in _task6_live_nodes(rebind_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == f"{rebind_parser}.parse_args"
    )
    rebind_entry_call = next(
        node for node in _task6_live_nodes(rebind_guard)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id in _task6_top_level_functions(rebind_tree)
    )
    rebind_statement = next(
        statement for statement in rebind_guard.body
        if rebind_entry_call in tuple(ast.walk(statement))
    )
    rebind_guard.body.insert(
        rebind_guard.body.index(rebind_statement),
        ast.Assign(targets=[ast.Name(id=rebind_namespace, ctx=ast.Store())],
                   value=ast.Constant(None)),
    )
    mutants["parse-result-rebound"] = ast.unparse(ast.fix_missing_locations(rebind_tree))

    attribute_tree = ast.parse(source)
    attribute_guard = _task6_main_guard(attribute_tree)
    attribute_parser = next(
        node for node in _task6_live_nodes(attribute_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == "argparse.ArgumentParser"
    ).targets[0].id
    attribute_namespace = next(
        node.targets[0].id for node in _task6_live_nodes(attribute_guard)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and isinstance(node.value, ast.Call)
        and ast.unparse(node.value.func) == f"{attribute_parser}.parse_args"
    )
    attribute_entry_call = next(
        node for node in _task6_live_nodes(attribute_guard)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id in _task6_top_level_functions(attribute_tree)
    )
    attribute_statement = next(
        statement for statement in attribute_guard.body
        if attribute_entry_call in tuple(ast.walk(statement))
    )
    attribute_guard.body.insert(
        attribute_guard.body.index(attribute_statement),
        ast.Assign(
            targets=[ast.Attribute(value=ast.Name(id=attribute_namespace,
                                                  ctx=ast.Load()),
                                   attr=contract["main_args"][-1],
                                   ctx=ast.Store())],
            value=ast.Constant("task6-bypass"),
        ),
    )
    mutants["parse-attribute-rebound"] = ast.unparse(
        ast.fix_missing_locations(attribute_tree)
    )

    for keyword_name, keyword_value in (
        ("nargs", ast.Constant("?")),
        ("default", ast.Constant("task6-fallback")),
    ):
        option_tree = ast.parse(source)
        option_guard = _task6_main_guard(option_tree)
        option_parser = next(
            node for node in _task6_live_nodes(option_guard)
            if isinstance(node, ast.Assign) and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and isinstance(node.value, ast.Call)
            and ast.unparse(node.value.func) == "argparse.ArgumentParser"
        ).targets[0].id
        option_call = next(
            node for node in _task6_live_nodes(option_guard)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
            and node.func.attr == "add_argument" and node.args
            and ast.unparse(node.func.value) == option_parser
            and isinstance(node.args[0], ast.Constant)
            and node.args[0].value.startswith("--")
        )
        option_call.keywords.append(ast.keyword(arg=keyword_name,
                                                value=keyword_value))
        mutants[f"cli-{keyword_name}"] = ast.unparse(
            ast.fix_missing_locations(option_tree)
        )

    for index, argument in enumerate(contract["main_args"]):
        omission_tree = ast.parse(source)
        omission_main = _task6_top_level_functions(omission_tree)["main"]
        omission_call = next(
            node for node in ast.walk(omission_tree)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            and node.func.id == "main"
        )
        slot = _task6_call_argument_node(omission_main, omission_call, argument)
        assert slot is not None
        collection, selected = slot
        collection.pop(selected)
        mutants[f"main-omits-{argument}"] = ast.unparse(
            ast.fix_missing_locations(omission_tree)
        )
    if len(contract["main_args"]) > 1:
        swap_tree = ast.parse(source)
        swap_main = _task6_top_level_functions(swap_tree)["main"]
        swap_call = next(
            node for node in ast.walk(swap_tree)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            and node.func.id == "main"
        )
        first_name, second_name = contract["main_args"][:2]
        first_slot = _task6_call_argument_node(swap_main, swap_call, first_name)
        second_slot = _task6_call_argument_node(swap_main, swap_call, second_name)
        assert first_slot is not None and second_slot is not None
        first_collection, first_index = first_slot
        second_collection, second_index = second_slot
        first_value = (first_collection[first_index].value
                       if first_collection is swap_call.keywords
                       else first_collection[first_index])
        second_value = (second_collection[second_index].value
                        if second_collection is swap_call.keywords
                        else second_collection[second_index])
        if first_collection is swap_call.keywords:
            first_collection[first_index].value = second_value
        else:
            first_collection[first_index] = second_value
        if second_collection is swap_call.keywords:
            second_collection[second_index].value = first_value
        else:
            second_collection[second_index] = first_value
        mutants["main-argument-swap"] = ast.unparse(
            ast.fix_missing_locations(swap_tree)
        )

    leaf_tree = ast.parse(source)
    leaf_main = _task6_top_level_functions(leaf_tree)["main"]
    if contract["output_arg"] == "output_dir":
        leaf = contract["outputs"][0]
        candidates = [
            node for function in _task6_reachable_functions(leaf_tree).values()
            for node in _task6_live_nodes(function)
            if isinstance(node, ast.Constant) and node.value == leaf
        ]
        assert candidates
        selected = None
        for index in range(len(candidates)):
            candidate_tree = ast.parse(source)
            candidate_nodes = [
                node for function in _task6_reachable_functions(
                    candidate_tree).values()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Constant) and node.value == leaf
            ]
            candidate_nodes[index].value = "task6-unexpected.png"
            if _task6_output_routes(path, candidate_tree, contract)[1]:
                selected = candidate_tree
                break
        assert selected is not None
        leaf_tree = selected
    else:
        leaf_main.body.append(ast.Expr(value=ast.Call(
            func=ast.Attribute(value=ast.Name(id="plt", ctx=ast.Load()),
                               attr="savefig", ctx=ast.Load()),
            args=[ast.Call(func=ast.Name(id="Path", ctx=ast.Load()),
                           args=[ast.Name(id=contract["output_arg"],
                                          ctx=ast.Load())], keywords=[])],
            keywords=[])))
    mutants["wrong-or-extra-output"] = ast.unparse(ast.fix_missing_locations(leaf_tree))

    if len(contract["outputs"]) > 1:
        first, second = contract["outputs"][:2]
        swap_leaf_tree = None
        base_tree = ast.parse(source)
        first_count = sum(
            isinstance(node, ast.Constant) and node.value == first
            for function in _task6_reachable_functions(base_tree).values()
            for node in _task6_live_nodes(function)
        )
        second_count = sum(
            isinstance(node, ast.Constant) and node.value == second
            for function in _task6_reachable_functions(base_tree).values()
            for node in _task6_live_nodes(function)
        )
        for first_index in range(first_count):
            for second_index in range(second_count):
                candidate_tree = ast.parse(source)
                reachable = _task6_reachable_functions(candidate_tree)
                first_nodes = [
                    node for function in reachable.values()
                    for node in _task6_live_nodes(function)
                    if isinstance(node, ast.Constant) and node.value == first
                ]
                second_nodes = [
                    node for function in reachable.values()
                    for node in _task6_live_nodes(function)
                    if isinstance(node, ast.Constant) and node.value == second
                ]
                first_nodes[first_index].value = second
                second_nodes[second_index].value = first
                if _task6_output_routes(path, candidate_tree, contract)[1]:
                    swap_leaf_tree = candidate_tree
                    break
            if swap_leaf_tree is not None:
                break
        assert swap_leaf_tree is not None
        mutants["output-leaf-swap"] = ast.unparse(
            ast.fix_missing_locations(swap_leaf_tree)
        )

    extra_tree = ast.parse(source)
    extra_main = _task6_top_level_functions(extra_tree)["main"]
    root_path = ast.Call(
        func=ast.Name(id="Path", ctx=ast.Load()),
        args=[ast.Name(id=contract["output_arg"], ctx=ast.Load())], keywords=[]
    )
    extra_target = (
        ast.BinOp(left=root_path,
                  op=ast.Div(), right=ast.Constant("task6-extra.png"))
        if contract["output_arg"] == "output_dir"
        else root_path
    )
    extra_main.body.append(ast.Expr(value=ast.Call(
        func=ast.Attribute(value=ast.Name(id="plt", ctx=ast.Load()),
                           attr="savefig", ctx=ast.Load()),
        args=[extra_target], keywords=[])))
    mutants["extra-output"] = ast.unparse(ast.fix_missing_locations(extra_tree))

    missing_tree = ast.parse(source)
    missing_call = next(
        node for node in ast.walk(missing_tree)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
        and node.func.attr in {"savefig", "save"}
    )

    class RemoveEmitter(ast.NodeTransformer):
        def visit_Call(self, node):
            if node is missing_call:
                return ast.copy_location(ast.Constant(None), node)
            return self.generic_visit(node)

    missing_tree = RemoveEmitter().visit(missing_tree)
    mutants["missing-output"] = ast.unparse(ast.fix_missing_locations(missing_tree))

    required_text = TASK6_RENDER_VISIBLE_CONTRACTS[path][0]

    def without_required_visible_call():
        candidate = ast.parse(source)
        calls = [call for call, text in _task6_visible_calls(candidate)
                 if required_text in text]
        assert len(calls) == 1
        _task6_erase_visible_call_strings(calls[0])
        return candidate

    visible_tree = without_required_visible_call()
    visible_tree.body.insert(0, ast.Expr(value=ast.Constant(required_text)))
    mutants["docstring-decoy"] = ast.unparse(ast.fix_missing_locations(visible_tree))

    keyword_tree = without_required_visible_call()
    keyword_reachable = _task6_reachable_functions(keyword_tree)
    keyword_main = keyword_reachable["main"]
    keyword_main.body.append(ast.Expr(value=ast.Call(
        func=ast.Name(id="semantic_decoy", ctx=ast.Load()), args=[],
        keywords=[ast.keyword(arg="label", value=ast.Constant(required_text))],
    )))
    mutants["unrendered-keyword-decoy"] = ast.unparse(
        ast.fix_missing_locations(keyword_tree)
    )

    dead_conditions = {
        "if-false": (ast.If, ast.Constant(False)),
        "if-zero": (ast.If, ast.Constant(0)),
        "if-none": (ast.If, ast.Constant(None)),
        "if-not-true": (
            ast.If,
            ast.UnaryOp(op=ast.Not(), operand=ast.Constant(True)),
        ),
        "if-false-and-runtime": (
            ast.If,
            ast.BoolOp(op=ast.And(), values=[
                ast.Constant(False), ast.Name(id="runtime", ctx=ast.Load()),
            ]),
        ),
        "if-one-eq-zero": (
            ast.If,
            ast.Compare(left=ast.Constant(1), ops=[ast.Eq()],
                        comparators=[ast.Constant(0)]),
        ),
        "if-empty-list": (ast.If, ast.List(elts=[], ctx=ast.Load())),
        "if-empty-tuple": (ast.If, ast.Tuple(elts=[], ctx=ast.Load())),
        "if-empty-dict": (ast.If, ast.Dict(keys=[], values=[])),
        "while-false": (ast.While, ast.Constant(False)),
        "while-empty-list": (ast.While, ast.List(elts=[], ctx=ast.Load())),
    }
    for label, (statement_type, condition) in dead_conditions.items():
        dead_tree = without_required_visible_call()
        dead_reachable = _task6_reachable_functions(dead_tree)
        dead_call = ast.Expr(value=ast.Call(
            func=ast.Attribute(value=ast.Name(id="ax", ctx=ast.Load()),
                               attr="plot", ctx=ast.Load()),
            args=[], keywords=[ast.keyword(arg="label",
                                           value=ast.Constant(required_text))],
        ))
        dead_reachable["main"].body.append(statement_type(
            test=condition, body=[dead_call], orelse=[]
        ))
        mutants[f"unreachable-{label}-decoy"] = ast.unparse(
            ast.fix_missing_locations(dead_tree)
        )
    for label, expression in (
        ("ifexp", ast.IfExp(
            test=ast.Constant(False), body=ast.Constant(required_text),
            orelse=ast.Constant("reachable neutral label"))),
        ("boolop", ast.BoolOp(
            op=ast.And(), values=[
                ast.Constant(False), ast.Constant(required_text),
            ])),
    ):
        expression_tree = without_required_visible_call()
        _task6_reachable_functions(expression_tree)["main"].body.append(
            ast.Expr(value=ast.Call(
            func=ast.Attribute(value=ast.Name(id="ax", ctx=ast.Load()),
                               attr="plot", ctx=ast.Load()),
            args=[], keywords=[ast.keyword(arg="label", value=expression)],
        )))
        mutants[f"unreachable-expression-{label}-decoy"] = ast.unparse(
            ast.fix_missing_locations(expression_tree)
        )
    empty_loop_tree = without_required_visible_call()
    _task6_reachable_functions(empty_loop_tree)["main"].body.append(ast.For(
        target=ast.Name(id="unused", ctx=ast.Store()),
        iter=ast.List(elts=[], ctx=ast.Load()),
        body=[ast.Expr(value=ast.Call(
            func=ast.Attribute(value=ast.Name(id="ax", ctx=ast.Load()),
                               attr="plot", ctx=ast.Load()),
            args=[], keywords=[ast.keyword(
                arg="label", value=ast.Constant(required_text))],
        ))],
        orelse=[],
    ))
    mutants["unreachable-empty-loop-decoy"] = ast.unparse(
        ast.fix_missing_locations(empty_loop_tree)
    )
    return mutants


@pytest.mark.parametrize("path", TASK6_IMAGE_WRITERS)
def test_task6_render_writer_static_mutations_fail(path):
    source = read_host(path)
    assert not task6_writer_static_findings(path, source)
    mutants = _task6_render_static_mutants(path, source)
    required = {
        "destination-bypass", "default-fallback", "optional-cli-output",
        "parse-result-discarded", "parse-result-rebound",
        "parse-attribute-rebound", "cli-nargs", "cli-default",
        "wrong-or-extra-output", "extra-output", "missing-output",
        "docstring-decoy",
        "unrendered-keyword-decoy",
        "unreachable-if-false-decoy", "unreachable-if-zero-decoy",
        "unreachable-if-none-decoy", "unreachable-if-not-true-decoy",
        "unreachable-if-false-and-runtime-decoy",
        "unreachable-if-one-eq-zero-decoy",
        "unreachable-if-empty-list-decoy",
        "unreachable-if-empty-tuple-decoy",
        "unreachable-if-empty-dict-decoy",
        "unreachable-while-false-decoy",
        "unreachable-while-empty-list-decoy",
        "unreachable-expression-ifexp-decoy",
        "unreachable-expression-boolop-decoy",
        "unreachable-empty-loop-decoy",
        *(f"main-omits-{argument}"
          for argument in TASK6_RENDER_SEAM_CONTRACTS[path]["main_args"]),
    }
    if len(TASK6_RENDER_SEAM_CONTRACTS[path]["main_args"]) > 1:
        required.add("main-argument-swap")
    if len(TASK6_RENDER_SEAM_CONTRACTS[path]["outputs"]) > 1:
        required.add("output-leaf-swap")
    assert set(mutants) == required
    for name, mutant in mutants.items():
        assert task6_writer_static_findings(path, mutant), (path, name)


def test_task6_cli_and_output_flow_are_name_agnostic_and_nested():
    source = '''
from pathlib import Path
import argparse

def emit(*, target):
    figure.savefig(target)

def forward(location):
    emit(target=location / "image.png")

def main(*, output_dir):
    requested = Path(output_dir)
    forward(requested)

def dispatch(configuration):
    main(output_dir=configuration.output_dir)

if __name__ == "__main__":
    cli_builder = argparse.ArgumentParser()
    cli_builder.add_argument("--output-dir", required=True)
    configuration = cli_builder.parse_args()
    dispatch(configuration)
'''
    contract = {
        "main_args": ("output_dir",), "output_arg": "output_dir",
        "cli": (("--output-dir", "output_dir", True),),
        "outputs": ("image.png",), "json": (),
    }
    tree = ast.parse(source)
    assert not _task6_argparse_findings("synthetic.py", tree, contract)
    assert _task6_output_routes("synthetic.py", tree, contract) == \
        (("image.png",), [])

    rebound = ast.parse(source)
    guard = _task6_main_guard(rebound)
    guard.body.insert(-1, ast.Assign(
        targets=[ast.Attribute(
            value=ast.Name(id="configuration", ctx=ast.Load()),
            attr="output_dir", ctx=ast.Store(),
        )], value=ast.Constant("tracked"),
    ))
    assert _task6_argparse_findings("synthetic.py", rebound, contract)


def test_task6_semantic_render_flow_is_ordered_leaf_specific_and_sink_typed():
    source = '''
from pathlib import Path

def paint_line(values, target):
    figure, axis = plt.subplots()
    axis.plot(values)
    figure.savefig(fname=target)

def paint_points(values, target):
    figure = plt.figure()
    axis = figure.add_subplot(111)
    axis.scatter(values, values)
    animation = ArtistAnimation(figure, [])
    animation.save(fp=target)

def render_both(data, root):
    rows = data["rows"]
    paint_line(rows, root / "line.png")
    paint_points(rows, root / "points.png")

def load_frozen():
    return {}

def main(output_dir):
    root = Path(output_dir)
    payload = load_frozen()
    render_both(payload, root)
'''
    contract = {
        "main_args": ("output_dir",), "output_arg": "output_dir", "cli": (),
        "outputs": ("line.png", "points.png"), "json": (),
    }
    roles = {"JSON": ("rows", ("line.png", "points.png"))}
    assert _task6_output_routes("synthetic.py", ast.parse(source), contract) == \
        (("line.png", "points.png"), [])

    def emissions(candidate):
        tree = ast.parse(candidate)
        main = _task6_top_level_functions(tree)["main"]
        loader = next(node for node in ast.walk(main)
                      if isinstance(node, ast.Call)
                      and isinstance(node.func, ast.Name)
                      and node.func.id == "load_frozen")
        failures = []
        observed = _task6_semantic_render_emissions(
            tree, contract, {id(loader): {"json:JSON"}}, roles, failures,
        )
        emissions.failures = tuple(failures)
        return observed

    observed = emissions(source)
    assert tuple(item["leaf"] for item in observed) == ("line.png", "points.png")
    assert all("json-role:JSON" in item["geometry"] for item in observed)
    assert len({item["call_path"] for item in observed}) == 2
    assert emissions.failures == ()

    overwritten = source.replace(
        '    rows = data["rows"]\n',
        '    rows = data["rows"]\n    rows = []\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(overwritten))

    used_before = source.replace(
        '    rows = data["rows"]\n    paint_line(rows, root / "line.png")',
        '    paint_line(rows, root / "line.png")\n    rows = data["rows"]', 1,
    )
    before_emissions = emissions(used_before)
    assert "json-role:JSON" not in before_emissions[0]["geometry"]
    assert "json-role:JSON" in before_emissions[1]["geometry"]

    clean_second_invocation = source.replace(
        '    paint_points(rows, root / "points.png")',
        '    paint_points([], root / "points.png")', 1,
    )
    invocation_emissions = emissions(clean_second_invocation)
    assert "json-role:JSON" in invocation_emissions[0]["geometry"]
    assert "json-role:JSON" not in invocation_emissions[1]["geometry"]

    text_only = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot([0.0])\n    axis.set_title(str(values))\n", 1,
    )
    text_emissions = emissions(text_only)
    assert "json-role:JSON" not in text_emissions[0]["geometry"]
    assert "json-role:JSON" in text_emissions[0]["text"]

    one_clean_branch = source.replace(
        "    axis.scatter(values, values)\n",
        "    if runtime_condition:\n"
        "        axis.scatter(values, values)\n"
        "    else:\n"
        "        axis.scatter([0.0], [0.0])\n", 1,
    )
    branched = [item for item in emissions(one_clean_branch)
                if item["leaf"] == "points.png"]
    assert len(branched) == 2
    assert any("json-role:JSON" not in item["geometry"] for item in branched)

    false_and = source.replace(
        "    axis.plot(values)\n", "    axis.plot(False and values)\n", 1)
    assert "json-role:JSON" not in emissions(false_and)[0]["geometry"]
    false_ifexp = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(values if False else [0.0])\n", 1,
    )
    assert "json-role:JSON" not in emissions(false_ifexp)[0]["geometry"]
    unknown_ifexp = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(values if runtime_condition else [0.0])\n", 1,
    )
    assert "json-role:JSON" not in emissions(unknown_ifexp)[0]["geometry"]
    tagged_ifexp = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(values if runtime_condition else values)\n", 1,
    )
    assert "json-role:JSON" in emissions(tagged_ifexp)[0]["geometry"]
    unknown_boolop = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(runtime_condition and values)\n", 1,
    )
    assert "json-role:JSON" not in emissions(unknown_boolop)[0]["geometry"]
    tagged_boolop = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(values and values)\n", 1,
    )
    assert "json-role:JSON" in emissions(tagged_boolop)[0]["geometry"]

    empty_loop = source.replace(
        '    rows = data["rows"]\n',
        '    rows = []\n    for unused in []:\n        rows = data["rows"]\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(empty_loop))
    unknown_loop = source.replace(
        '    rows = data["rows"]\n',
        '    rows = []\n'
        '    for unused in runtime_values:\n'
        '        rows = data["rows"]\n', 1,
    )
    loop_emissions = emissions(unknown_loop)
    for leaf in ("line.png", "points.png"):
        owned = [item for item in loop_emissions if item["leaf"] == leaf]
        assert len(owned) == 2
        assert any("json-role:JSON" not in item["geometry"] for item in owned)
    nonempty_loop = source.replace(
        '    rows = data["rows"]\n',
        '    rows = []\n'
        '    for unused in [0]:\n'
        '        rows = data["rows"]\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(nonempty_loop))
    clean_unknown_loop = source.replace(
        '    rows = data["rows"]\n',
        '    rows = data["rows"]\n'
        '    for unused in runtime_values:\n'
        '        pass\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(clean_unknown_loop))
    assert emissions.failures == ()

    pair_helper = '''
def pair(value):
    return (value, [])

'''
    tagged_unknown_loop = (pair_helper + source).replace(
        '    rows = data["rows"]\n',
        '    rows = data["rows"]\n'
        '    for rows in pair(data["rows"]):\n'
        '        pass\n', 1,
    )
    tagged_loop_emissions = emissions(tagged_unknown_loop)
    for leaf in ("line.png", "points.png"):
        owned = [item for item in tagged_loop_emissions if item["leaf"] == leaf]
        assert any("json-role:JSON" not in item["geometry"] for item in owned)
    assert "TAGGED_ITERABLE_ORDER_UNKNOWN" in emissions.failures

    destructured = source.replace(
        '    rows = data["rows"]\n',
        '    tagged, rows = (data["rows"], [])\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(destructured))
    unresolved = source.replace(
        '    rows = data["rows"]\n',
        '    tagged, rows = np.asarray(data["rows"])\n', 1,
    )
    emissions(unresolved)
    assert "TAGGED_DESTRUCTURE_UNRESOLVED" in emissions.failures

    helpers = '''
def identity(value):
    return value

def discard(value):
    return []

'''
    identity = (helpers + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(identity(data["rows"]))\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(identity))
    discarded = (helpers + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(discard(data["rows"]))\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(discarded))
    assert emissions.failures == ()
    opaque_helper = '''
def opaque(value):
    for item in value:
        pass
    return value

'''
    opaque = (opaque_helper + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(opaque(data["rows"]))\n', 1,
    )
    emissions(opaque)
    assert any(failure.startswith("TAGGED_EXPRESSION_STATEMENT:opaque")
               for failure in emissions.failures)

    conditional_helpers = '''
def maybe_identity(value):
    if runtime_condition:
        return value
    return []

def always_identity(value):
    if runtime_condition:
        return value
    return value

def partial_identity(value):
    if runtime_condition:
        return value

'''
    maybe_identity = (conditional_helpers + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(maybe_identity(data["rows"]))\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(maybe_identity))
    always_identity = (conditional_helpers + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(always_identity(data["rows"]))\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(always_identity))
    partial_identity = (conditional_helpers + source).replace(
        '    rows = data["rows"]\n',
        '    rows = np.asarray(partial_identity(data["rows"]))\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(partial_identity))

    zero_product = source.replace(
        "    axis.plot(values)\n", "    axis.plot(0 * values)\n", 1,
    )
    assert "json-role:JSON" not in emissions(zero_product)[0]["geometry"]
    bound_zero_product = source.replace(
        "    axis.plot(values)\n",
        "    zero = 0\n    axis.plot(zero * values)\n", 1,
    )
    assert "json-role:JSON" not in emissions(bound_zero_product)[0]["geometry"]
    cancelled = source.replace(
        "    axis.plot(values)\n", "    axis.plot(values - values)\n", 1,
    )
    assert "json-role:JSON" not in emissions(cancelled)[0]["geometry"]
    unit_product = source.replace(
        "    axis.plot(values)\n", "    axis.plot(1 * values)\n", 1,
    )
    assert "json-role:JSON" in emissions(unit_product)[0]["geometry"]

    try_else = source.replace(
        '    rows = data["rows"]\n',
        '    rows = []\n'
        '    try:\n'
        '        probe()\n'
        '    except Exception:\n'
        '        rows = []\n'
        '    else:\n'
        '        rows = data["rows"]\n', 1,
    )
    try_emissions = emissions(try_else)
    for leaf in ("line.png", "points.png"):
        owned = [item for item in try_emissions if item["leaf"] == leaf]
        assert len(owned) >= 2
        assert any("json-role:JSON" in item["geometry"] for item in owned)
        assert any("json-role:JSON" not in item["geometry"] for item in owned)
    try_finally = try_else.replace(
        '    else:\n        rows = data["rows"]\n',
        '    else:\n        rows = []\n'
        '    finally:\n        rows = data["rows"]\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(try_finally))
    try_prefix = source.replace(
        '    rows = data["rows"]\n',
        '    rows = data["rows"]\n'
        '    try:\n'
        '        rows = []\n'
        '        probe()\n'
        '    except Exception:\n'
        '        pass\n'
        '    else:\n'
        '        rows = data["rows"]\n', 1,
    )
    prefix_emissions = emissions(try_prefix)
    for leaf in ("line.png", "points.png"):
        owned = [item for item in prefix_emissions if item["leaf"] == leaf]
        assert any("json-role:JSON" in item["geometry"] for item in owned)
        assert any("json-role:JSON" not in item["geometry"] for item in owned)

    style_only = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot([0.0], color=values)\n", 1,
    )
    assert "json-role:JSON" not in emissions(style_only)[0]["geometry"]
    for invisible_call in (
        "    axis.plot(values, visible=False)\n",
        "    axis.plot(values, alpha=0)\n",
    ):
        invisible = source.replace("    axis.plot(values)\n", invisible_call, 1)
        assert "json-role:JSON" not in emissions(invisible)[0]["geometry"]
    bound_hidden = source.replace(
        "    axis.plot(values)\n",
        "    hidden = False\n    axis.plot(values, visible=hidden)\n", 1,
    )
    assert "json-role:JSON" not in emissions(bound_hidden)[0]["geometry"]
    bound_alpha_zero = source.replace(
        "    axis.plot(values)\n",
        "    zero = 0\n    axis.plot(values, alpha=zero)\n", 1,
    )
    assert "json-role:JSON" not in emissions(bound_alpha_zero)[0]["geometry"]
    bound_alpha_one = source.replace(
        "    axis.plot(values)\n",
        "    one = 1\n    axis.plot(values, alpha=one)\n", 1,
    )
    assert "json-role:JSON" in emissions(bound_alpha_one)[0]["geometry"]
    zero_alpha_loop = source.replace(
        "    axis.plot(values)\n",
        "    for opacity in (0.0,):\n"
        "        axis.plot(values, alpha=opacity)\n", 1,
    )
    assert "json-role:JSON" not in emissions(zero_alpha_loop)[0]["geometry"]
    visible_alpha_loop = source.replace(
        "    axis.plot(values)\n",
        "    for opacity in (1.0,):\n"
        "        axis.plot(values, alpha=opacity)\n", 1,
    )
    assert "json-role:JSON" in emissions(visible_alpha_loop)[0]["geometry"]
    final_clean_loop = source.replace(
        '    rows = data["rows"]\n',
        '    for rows in (data["rows"], []):\n'
        '        pass\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(final_clean_loop))
    final_tagged_loop = source.replace(
        '    rows = data["rows"]\n',
        '    for rows in ([], data["rows"]):\n'
        '        pass\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(final_tagged_loop))
    loop_destructured_clean = source.replace(
        '    rows = data["rows"]\n',
        '    for tagged, rows in ((data["rows"], []),):\n'
        '        pass\n', 1,
    )
    assert all("json-role:JSON" not in item["geometry"]
               for item in emissions(loop_destructured_clean))
    loop_destructured_tagged = source.replace(
        '    rows = data["rows"]\n',
        '    for clean, rows in (([], data["rows"]),):\n'
        '        pass\n', 1,
    )
    assert all("json-role:JSON" in item["geometry"]
               for item in emissions(loop_destructured_tagged))
    cleared = source.replace(
        "    axis.plot(values)\n",
        "    axis.plot(values)\n    axis.clear()\n"
        "    axis.plot([0.0])\n", 1,
    )
    assert "json-role:JSON" not in emissions(cleared)[0]["geometry"]

    direct = '''
from pathlib import Path
def main(output_dir):
    root = Path(output_dir)
    first, axis = plt.subplots()
    axis.plot([1.0])
    first.savefig(fname=root / "line.png")
    second, axis2 = plt.subplots()
    axis2.scatter([1.0], [2.0])
    second.save(fp=root / "points.png")
'''
    assert _task6_output_routes("direct.py", ast.parse(direct), contract) == \
        (("line.png", "points.png"), [])


@pytest.mark.parametrize("statement", (
    "if False:\n        axis.plot(label='dead-token')",
    "if 0:\n        axis.plot(label='dead-token')",
    "if None:\n        axis.plot(label='dead-token')",
    "if not True:\n        axis.plot(label='dead-token')",
    "if False and runtime:\n        axis.plot(label='dead-token')",
    "if 1 == 0:\n        axis.plot(label='dead-token')",
    "if []:\n        axis.plot(label='dead-token')",
    "if ():\n        axis.plot(label='dead-token')",
    "if {}:\n        axis.plot(label='dead-token')",
    "while False:\n        axis.plot(label='dead-token')",
    "while []:\n        axis.plot(label='dead-token')",
))
def test_task6_literal_false_visible_branches_are_dead(statement):
    tree = ast.parse(
        "def main():\n    " + statement.replace("\n", "\n    ")
        + "\n    axis.legend()\n"
    )
    assert "dead-token" not in _task6_visible_call_text(tree)


def test_task6_runtime_decided_visible_branch_remains_live():
    tree = ast.parse('''
def main(runtime_condition):
    if runtime_condition:
        axis.plot(label="live-token")
    axis.legend()
''')
    assert "live-token" in _task6_visible_call_text(tree)


def test_task6_plot_label_is_visible_only_when_a_legend_is_rendered():
    without = ast.parse('''
def main():
    axis.plot([0.0], label="caption-token")
''')
    with_legend = ast.parse('''
def main():
    axis.plot([0.0], label="caption-token")
    axis.legend()
''')
    assert "caption-token" not in _task6_visible_call_text(without)
    assert "caption-token" in _task6_visible_call_text(with_legend)


def test_task6_unreachable_expressions_and_empty_loops_are_not_visible():
    tree = ast.parse('''
def main(runtime):
    axis.plot([0.0], label=("dead-ifexp" if False else "live"))
    axis.plot([0.0], label=(False and "dead-boolop"))
    for unused in []:
        axis.plot([0.0], label="dead-empty-loop")
    for unused in range(0):
        axis.plot([0.0], label="dead-empty-range")
    axis.legend()
''')
    visible = _task6_visible_call_text(tree)
    assert "live" in visible
    for dead in (
        "dead-ifexp", "dead-boolop", "dead-empty-loop", "dead-empty-range",
    ):
        assert dead not in visible


@pytest.mark.parametrize("path", tuple(
    path for path, contract in TASK6_RENDER_SEAM_CONTRACTS.items()
    if contract["json"]
))
def test_task6_frozen_json_loader_is_fail_closed_before_parse(path, tmp_path):
    source = read_host(path)
    tree = ast.parse(source)
    loader = next(
        function for function in _task6_top_level_functions(tree).values()
        if {ast.unparse(node.func) for node in ast.walk(function)
            if isinstance(node, ast.Call)} >= {"hashlib.sha256", "json.loads"}
        and any(isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "read_bytes" for node in ast.walk(function))
    )
    names = {loader.name}
    if "json_path" in TASK6_RENDER_SEAM_CONTRACTS[path]["main_args"]:
        names.add("require_exact_json_path")
    copied = source_copy_definitions(
        source, names, tmp_path,
        prelude="from pathlib import Path\nimport hashlib\nimport json\n",
    )
    payload_path = tmp_path / "payload.json"
    payload_path.write_bytes(b'{"value": 7}\n')
    digest = hashlib.sha256(payload_path.read_bytes()).hexdigest().upper()
    assert copied[loader.name](payload_path, digest) == {"value": 7}
    wrong_one_position = (
        ("0" if digest[17] != "0" else "1").join(
            (digest[:17], digest[18:])
        )
    )
    for invalid_digest in ("0" * 64, digest[:-1], wrong_one_position):
        with pytest.raises((RuntimeError, ValueError)):
            copied[loader.name](payload_path, invalid_digest)
    if "require_exact_json_path" in names:
        copied["require_exact_json_path"](payload_path, payload_path)
        with pytest.raises((RuntimeError, ValueError)):
            copied["require_exact_json_path"](payload_path, tmp_path / "other.json")


@pytest.mark.parametrize("path", tuple(
    path for path, contract in TASK6_RENDER_SEAM_CONTRACTS.items()
    if contract["json"]
))
def test_task6_frozen_json_dataflow_mutations_fail(path):
    source = read_host(path)
    contract = TASK6_RENDER_SEAM_CONTRACTS[path]
    for _path_name, _digest_name, relative_path, digest in contract["json"]:
        for old, new in (
            (relative_path, relative_path.replace("202604", "202603", 1)),
            (digest, "0" * 64),
        ):
            mutant = source.replace(old, new, 1)
            assert mutant != source, (path, old)
            assert task6_writer_static_findings(path, mutant), (path, old)

    tree = ast.parse(source)
    functions = _task6_top_level_functions(tree)
    loader = next(
        function for function in functions.values()
        if any(isinstance(node, ast.Call)
               and ast.unparse(node.func) == "json.loads"
               for node in ast.walk(function))
        and any(isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "read_bytes" for node in ast.walk(function))
    )
    loader_name = loader.name
    loader_path_arg = (
        loader.args.posonlyargs + loader.args.args + loader.args.kwonlyargs
    )[0].arg

    read_tree = ast.parse(source)
    read_loader = _task6_top_level_functions(read_tree)[loader_name]
    read_call = next(node for node in ast.walk(read_loader)
                     if isinstance(node, ast.Call)
                     and isinstance(node.func, ast.Attribute)
                     and node.func.attr == "read_bytes")
    read_call.func.attr = "read_text"
    read_call.keywords.append(ast.keyword(arg="encoding", value=ast.Constant("utf-8")))
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(read_tree))
    )

    parse_tree = ast.parse(source)
    parse_loader = _task6_top_level_functions(parse_tree)[loader_name]
    loads_call = next(node for node in ast.walk(parse_loader)
                      if isinstance(node, ast.Call)
                      and ast.unparse(node.func) == "json.loads")
    loads_call.args[0] = ast.Call(
        func=ast.Attribute(
            value=ast.Call(func=ast.Name(id="Path", ctx=ast.Load()),
                           args=[ast.Name(id=loader_path_arg, ctx=ast.Load())],
                           keywords=[]),
            attr="read_text", ctx=ast.Load()),
        args=[], keywords=[ast.keyword(arg="encoding", value=ast.Constant("utf-8"))],
    )
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(parse_tree))
    )

    for label, replacement in (
        ("conditional", ast.IfExp(
            test=ast.Name(id="runtime_condition", ctx=ast.Load()),
            body=ast.Name(id="payload", ctx=ast.Load()),
            orelse=ast.Constant(b"{}"),
        )),
        ("slice", ast.Subscript(
            value=ast.Name(id="payload", ctx=ast.Load()),
            slice=ast.Slice(upper=ast.Constant(-1)), ctx=ast.Load(),
        )),
        ("hardcoded", ast.Constant(b"{}")),
    ):
        exact_tree = ast.parse(source)
        exact_loader = _task6_top_level_functions(exact_tree)[loader_name]
        exact_payload = next(
            node for node in ast.walk(exact_loader)
            if isinstance(node, ast.Assign) and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and any(isinstance(part, ast.Call)
                    and isinstance(part.func, ast.Attribute)
                    and part.func.attr == "read_bytes"
                    for part in ast.walk(node.value))
        ).targets[0].id
        candidate = ast.parse(ast.unparse(replacement)).body[0].value
        for name in ast.walk(candidate):
            if isinstance(name, ast.Name) and name.id == "payload":
                name.id = exact_payload
        exact_load = next(
            node for node in ast.walk(exact_loader)
            if isinstance(node, ast.Call)
            and ast.unparse(node.func) == "json.loads"
        )
        exact_load.args[0] = candidate
        exact_findings = task6_writer_static_findings(
            path, ast.unparse(ast.fix_missing_locations(exact_tree))
        )
        assert any("LOADER_JSON_PAYLOAD" in finding
                   for finding in exact_findings), (path, label, exact_findings)

    payload_rebind_tree = ast.parse(source)
    payload_rebind_loader = _task6_top_level_functions(
        payload_rebind_tree)[loader_name]
    payload_read_binding = next(
        node for node in ast.walk(payload_rebind_loader)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and any(isinstance(part, ast.Call)
                and isinstance(part.func, ast.Attribute)
                and part.func.attr == "read_bytes"
                for part in ast.walk(node.value))
    )
    payload_name = payload_read_binding.targets[0].id
    digest_if = next(
        node for node in ast.walk(payload_rebind_loader)
        if isinstance(node, ast.If)
        and any(isinstance(part, ast.Compare) and len(part.ops) == 1
                and isinstance(part.ops[0], ast.NotEq)
                for part in ast.walk(node.test))
    )
    assert _task6_insert_after_statement(
        payload_rebind_loader, digest_if,
        ast.Assign(targets=[ast.Name(id=payload_name, ctx=ast.Store())],
                   value=ast.Constant(b"{}")),
    )
    rebind_findings = task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(payload_rebind_tree))
    )
    assert any("LOADER_PAYLOAD_REBOUND" in finding
               for finding in rebind_findings), rebind_findings

    payload_early_tree = ast.parse(source)
    payload_early_loader = _task6_top_level_functions(payload_early_tree)[loader_name]
    early_read = next(
        node for node in payload_early_loader.body
        if isinstance(node, ast.Assign)
        and any(isinstance(part, ast.Call)
                and isinstance(part.func, ast.Attribute)
                and part.func.attr == "read_bytes"
                for part in ast.walk(node.value))
    )
    early_hash = next(
        node for node in payload_early_loader.body
        if isinstance(node, ast.Assign)
        and any(isinstance(part, ast.Call)
                and ast.unparse(part.func) == "hashlib.sha256"
                for part in ast.walk(node.value))
    )
    payload_early_loader.body.remove(early_read)
    payload_early_loader.body.insert(
        payload_early_loader.body.index(early_hash) + 1, early_read)
    early_findings = task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(payload_early_tree))
    )
    assert any("LOADER_ORDERED_VERIFY_THEN_PARSE" in finding
               or "HASH_NOT_BEFORE_PARSE" in finding
               for finding in early_findings), early_findings

    for label, replacement in (
        ("empty", ast.Dict(keys=[], values=[])),
        ("preparse", ast.Name(id=payload_name, ctx=ast.Load())),
        ("sentinel-equal", ast.Dict(
            keys=[ast.Constant("value")], values=[ast.Constant(7)])),
    ):
        result_tree = ast.parse(source)
        result_loader = _task6_top_level_functions(result_tree)[loader_name]
        result_payload = next(
            node.targets[0].id for node in ast.walk(result_loader)
            if isinstance(node, ast.Assign) and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and any(isinstance(part, ast.Call)
                    and isinstance(part.func, ast.Attribute)
                    and part.func.attr == "read_bytes"
                    for part in ast.walk(node.value))
        )
        candidate = ast.parse(ast.unparse(replacement)).body[0].value
        for name in ast.walk(candidate):
            if isinstance(name, ast.Name) and name.id == payload_name:
                name.id = result_payload
        result_return = next(node for node in ast.walk(result_loader)
                             if isinstance(node, ast.Return))
        result_return.value = candidate
        result_findings = task6_writer_static_findings(
            path, ast.unparse(ast.fix_missing_locations(result_tree))
        )
        assert any("LOADER_JSON_RESULT" in finding
                   for finding in result_findings), (
                       path, label, result_findings)

    compare_tree = ast.parse(source)
    compare_loader = _task6_top_level_functions(compare_tree)[loader_name]
    compare = next(node for node in ast.walk(compare_loader)
                   if isinstance(node, ast.Compare)
                   and len(node.ops) == 1 and isinstance(node.ops[0], ast.NotEq))
    compare.ops[0] = ast.Eq()
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(compare_tree))
    )

    truncated_tree = ast.parse(source)
    truncated_loader = _task6_top_level_functions(truncated_tree)[loader_name]
    truncated_binding = next(
        node for node in ast.walk(truncated_loader)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and any(isinstance(part, ast.Call)
                and isinstance(part.func, ast.Attribute)
                and part.func.attr == "hexdigest"
                for part in ast.walk(node.value))
    )
    truncated_binding.value = ast.Subscript(
        value=truncated_binding.value,
        slice=ast.Slice(upper=ast.Constant(63)), ctx=ast.Load(),
    )
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(truncated_tree))
    )

    prefix_tree = ast.parse(source)
    prefix_loader = _task6_top_level_functions(prefix_tree)[loader_name]
    prefix_compare = next(
        node for node in ast.walk(prefix_loader)
        if isinstance(node, ast.Compare) and len(node.ops) == 1
        and isinstance(node.ops[0], ast.NotEq)
    )
    prefix_compare.left = ast.Subscript(
        value=prefix_compare.left,
        slice=ast.Slice(upper=ast.Constant(8)), ctx=ast.Load(),
    )
    prefix_compare.comparators[0] = ast.Subscript(
        value=prefix_compare.comparators[0],
        slice=ast.Slice(upper=ast.Constant(8)), ctx=ast.Load(),
    )
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(prefix_tree))
    )

    discard_tree = ast.parse(source)
    discard_main = _task6_top_level_functions(discard_tree)["main"]
    discard_call = next(node for node in ast.walk(discard_main)
                        if isinstance(node, ast.Call)
                        and isinstance(node.func, ast.Name)
                        and node.func.id == loader_name)
    discard_assignment = next(
        node for node in ast.walk(discard_main) if isinstance(node, ast.Assign)
        and discard_call in tuple(ast.walk(node.value))
    )
    discard_assignment.targets[0].id = "discarded_json_payload"
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(discard_tree))
    )

    for loader_index, json_contract in enumerate(contract["json"]):
        for label in ("post-overwrite", "use-before-compute"):
            ordered_tree = ast.parse(source)
            ordered_main = _task6_top_level_functions(ordered_tree)["main"]
            ordered_calls = [
                node for node in _task6_live_nodes(ordered_main)
                if isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == loader_name
            ]
            ordered_call = ordered_calls[loader_index]
            ordered_assignment = next(
                node for node in ast.walk(ordered_main)
                if isinstance(node, (ast.Assign, ast.AnnAssign))
                and ordered_call in tuple(ast.walk(node.value))
            )
            ordered_target = (
                ordered_assignment.targets[0]
                if isinstance(ordered_assignment, ast.Assign)
                else ordered_assignment.target
            )
            assert isinstance(ordered_target, ast.Name)
            original_name = ordered_target.id
            if label == "post-overwrite":
                addition = ast.Assign(
                    targets=[ast.Name(id=original_name, ctx=ast.Store())],
                    value=ast.Dict(keys=[], values=[]),
                )
                assert _task6_insert_after_statement(
                    ordered_main, ordered_assignment, addition)
            else:
                delayed_name = f"delayed_{original_name}"
                ordered_target.id = delayed_name
                ordered_main.body.append(ast.Assign(
                    targets=[ast.Name(id=original_name, ctx=ast.Store())],
                    value=ast.Name(id=delayed_name, ctx=ast.Load()),
                ))
            ordered_findings = task6_writer_static_findings(
                path, ast.unparse(ast.fix_missing_locations(ordered_tree))
            )
            assert any(
                json_contract[0] in finding
                and "JSON_ROLE_TO_RASTER" in finding
                for finding in ordered_findings
            ), (path, json_contract[0], label, ordered_findings)

    for path_name, (role_key, _owned_leaves) in \
            TASK6_RENDER_JSON_ROLES[path].items():
        ignored_tree = ast.parse(source)
        candidates = [
            node for function in _task6_reachable_functions(ignored_tree).values()
            for node in _task6_live_nodes(function)
            if ((isinstance(node, ast.Call)
                 and isinstance(node.func, ast.Attribute)
                 and node.func.attr == "get" and node.args
                 and isinstance(node.args[0], ast.Constant)
                 and node.args[0].value == role_key)
                or (isinstance(node, ast.Subscript)
                    and isinstance(node.slice, ast.Constant)
                    and node.slice.value == role_key))
        ]
        assert candidates, (path, path_name, role_key)
        for role_access in candidates:
            if isinstance(role_access, ast.Call):
                role_access.func.value = ast.Dict(keys=[], values=[])
            else:
                role_access.value = ast.Dict(keys=[], values=[])
        ignored_findings = task6_writer_static_findings(
            path, ast.unparse(ast.fix_missing_locations(ignored_tree))
        )
        assert any(
            path_name in finding and "JSON_ROLE_TO_RASTER" in finding
            for finding in ignored_findings
        ), (path, path_name, "ignored-role", ignored_findings)

    if len(contract["json"]) > 1:
        swapped_tree = ast.parse(source)
        swapped_main = _task6_top_level_functions(swapped_tree)["main"]
        swapped_calls = [
            node for node in _task6_live_nodes(swapped_main)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            and node.func.id == loader_name
        ]
        swapped_assignments = [
            next(node for node in _task6_live_nodes(swapped_main)
                 if isinstance(node, ast.Assign)
                 and call in tuple(ast.walk(node.value)))
            for call in swapped_calls
        ]
        first, second = swapped_assignments[:2]
        first.targets[0], second.targets[0] = second.targets[0], first.targets[0]
        swapped_findings = task6_writer_static_findings(
            path, ast.unparse(ast.fix_missing_locations(swapped_tree))
        )
        assert any("JSON_ROLE_TO_RASTER" in finding
                   for finding in swapped_findings), \
            (path, "swapped-json-roles", swapped_findings)


def test_task6_precision_gamma_is_required_live_and_not_json_fallback(tmp_path):
    path = "simulations/plot_cusp_precision.py"
    source = read_host(path)
    assert not task6_writer_static_findings(path, source)
    copied = source_copy_definitions(
        source, {"cpsi_bellplus"}, tmp_path,
        prelude="import numpy as np\n",
    )
    times = np.array((0.0, 1.25, 17.0))
    gamma = 0.00165
    expected = (
        np.exp(-4.0 * gamma * times)
        * (1.0 + np.exp(-4.0 * gamma * times) ** 2) / 6.0
    )
    assert copied["cpsi_bellplus"](times, gamma) == pytest.approx(
        expected, rel=0, abs=1e-15)

    for old, new in (
        ("np.exp(-4.0 * gamma * t_us)",
         "np.exp(-2.0 * gamma * t_us)"),
        ("f * (1.0 + f * f) / 6.0", "np.zeros_like(t_us)"),
    ):
        helper_mutant = source.replace(old, new, 1)
        assert helper_mutant != source, old
        helper_findings = task6_writer_static_findings(path, helper_mutant)
        assert any("F25_HELPER_FORMULA" in finding
                   for finding in helper_findings), (old, helper_findings)
    pin_mutant = source.replace(
        "REQUIRED_GAMMA_T2ECHO_PER_US = 0.00165",
        "REQUIRED_GAMMA_T2ECHO_PER_US = 0.015", 1,
    )
    assert pin_mutant != source
    assert task6_writer_static_findings(path, pin_mutant)

    numerical_tree = ast.parse(source)
    numerical_call = next(
        node for function in _task6_reachable_functions(numerical_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[1]) == "declared_gamma"
    )
    numerical_call.args[1] = ast.Constant(0.015)
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(numerical_tree))
    )

    argument_tree = ast.parse(source)
    argument_call = next(
        node for function in _task6_reachable_functions(argument_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[0]) == "t_fine"
        and ast.unparse(node.args[1]) == "declared_gamma"
    )
    argument_call.args[0] = ast.Name(id="t", ctx=ast.Load())
    argument_findings = task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(argument_tree))
    )
    assert any("DECLARED_GAMMA_TIME_ARGUMENTS" in finding
               for finding in argument_findings), argument_findings

    discarded_tree = ast.parse(source)
    discarded_call = next(
        node for function in _task6_reachable_functions(discarded_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[1]) == "declared_gamma"
    )
    discarded_assignment = next(
        node for function in _task6_reachable_functions(discarded_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and discarded_call in tuple(ast.walk(node.value))
    )
    discarded_assignment.targets[0].id = "discarded_gamma_curve"
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(discarded_tree))
    )

    hardcoded_tree = ast.parse(source)
    hardcoded_functions = _task6_reachable_functions(hardcoded_tree)
    hardcoded_call = next(
        node for function in hardcoded_functions.values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[1]) == "declared_gamma"
    )
    owner_name, owner_function, hardcoded_assignment = next(
        (name, function, node)
        for name, function in hardcoded_functions.items()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and hardcoded_call in tuple(ast.walk(node.value))
    )
    preserved_call = ast.parse(ast.unparse(hardcoded_call)).body[0].value
    hardcoded_assignment.value = ast.Call(
        func=ast.Attribute(value=ast.Name(id="np", ctx=ast.Load()),
                           attr="full", ctx=ast.Load()),
        args=[ast.Constant(1), ast.Constant(0.25)], keywords=[],
    )
    owner_function.body.append(ast.Expr(value=preserved_call))
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(hardcoded_tree))
    ), owner_name

    crossing_tree = ast.parse(source)
    crossing_functions = _task6_reachable_functions(crossing_tree)
    crossing_division = next(
        node for function in crossing_functions.values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div)
        and isinstance(node.right, ast.Name)
        and node.right.id == "declared_gamma"
    )
    crossing_assignment = next(
        node for function in crossing_functions.values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and crossing_division in tuple(ast.walk(node.value))
    )
    crossing_assignment.targets[0].id = "discarded_crossing_time"
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(crossing_tree))
    )

    numerator_tree = ast.parse(source)
    numerator_division = next(
        node for function in _task6_reachable_functions(numerator_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div)
        and isinstance(node.left, ast.Name) and node.left.id == "K_CROSS"
        and isinstance(node.right, ast.Name)
        and node.right.id == "declared_gamma"
    )
    numerator_division.left = ast.Name(id="F_CROSS", ctx=ast.Load())
    numerator_findings = task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(numerator_tree))
    )
    assert any("DECLARED_GAMMA_K_CROSS_DIVISION" in finding
               for finding in numerator_findings), numerator_findings

    fake_k_tree = ast.parse(source)
    fake_k_assignment = next(
        node for function in _task6_reachable_functions(fake_k_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Assign) and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == "K_CROSS"
    )
    fake_k_assignment.value = ast.Constant(0.1)
    fake_k_findings = task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(fake_k_tree))
    )
    assert any("GAMMA_GEOMETRY_DATAFLOW" in finding
               for finding in fake_k_findings), fake_k_findings

    for scientific_kind, candidate_index in (
        ("curve-fine", 0), ("curve-sampled", 1), ("crossing", 2),
    ):
        for annihilator in ("literal-zero", "bound-zero", "self-subtraction"):
            annihilated_tree = ast.parse(source)
            reachable = _task6_reachable_functions(annihilated_tree)
            candidates = [
                node for function in reachable.values()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
                and ast.unparse(node.args[1]) == "declared_gamma"
            ] + [
                node for function in reachable.values()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div)
                and isinstance(node.left, ast.Name) and node.left.id == "K_CROSS"
                and isinstance(node.right, ast.Name)
                and node.right.id == "declared_gamma"
            ]
            candidate = candidates[candidate_index]
            owner_name, owner, assignment = next(
                (name, function, node)
                for name, function in reachable.items()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Assign) and len(node.targets) == 1
                and candidate in tuple(ast.walk(node.value))
            )
            original = ast.parse(ast.unparse(assignment.value)).body[0].value
            if annihilator == "literal-zero":
                assignment.value = ast.BinOp(
                    left=ast.Constant(0), op=ast.Mult(), right=original)
            elif annihilator == "bound-zero":
                zero_name = f"zero_{candidate_index}"
                assert _task6_insert_before_statement(
                    owner, assignment,
                    ast.Assign(
                        targets=[ast.Name(id=zero_name, ctx=ast.Store())],
                        value=ast.Constant(0),
                    ),
                )
                assignment.value = ast.BinOp(
                    left=ast.Name(id=zero_name, ctx=ast.Load()),
                    op=ast.Mult(), right=original)
            else:
                assignment.value = ast.BinOp(
                    left=original, op=ast.Sub(),
                    right=ast.parse(ast.unparse(original)).body[0].value,
                )
            annihilated_findings = task6_writer_static_findings(
                path, ast.unparse(ast.fix_missing_locations(annihilated_tree))
            )
            assert any("GAMMA_GEOMETRY_DATAFLOW" in finding
                       for finding in annihilated_findings), (
                           scientific_kind, annihilator, owner_name,
                           annihilated_findings)

    ordered_base = ast.parse(source)
    ordered_reachable = _task6_reachable_functions(ordered_base)
    ordered_calls = [
        node for function in ordered_reachable.values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[1]) == "declared_gamma"
    ]
    ordered_divisions = [
        node for function in ordered_reachable.values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div)
        and isinstance(node.left, ast.Name) and node.left.id == "K_CROSS"
        and isinstance(node.right, ast.Name)
        and node.right.id == "declared_gamma"
    ]
    assert len(ordered_calls) == 2 and len(ordered_divisions) == 1
    for kind, original_index in (
        ("curve-fine", 0), ("curve-sampled", 1), ("crossing", 2),
    ):
        for ordering in ("post-overwrite", "use-before-compute"):
            ordered_tree = ast.parse(source)
            reachable = _task6_reachable_functions(ordered_tree)
            candidates = [
                node for function in reachable.values()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
                and ast.unparse(node.args[1]) == "declared_gamma"
            ] + [
                node for function in reachable.values()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div)
                and isinstance(node.left, ast.Name) and node.left.id == "K_CROSS"
                and isinstance(node.right, ast.Name)
                and node.right.id == "declared_gamma"
            ]
            candidate = candidates[original_index]
            owner_name, owner, assignment = next(
                (name, function, node)
                for name, function in reachable.items()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Assign) and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)
                and candidate in tuple(ast.walk(node.value))
            )
            target_name = assignment.targets[0].id
            if ordering == "post-overwrite":
                assert _task6_insert_after_statement(
                    owner, assignment, ast.Assign(
                        targets=[ast.Name(id=target_name, ctx=ast.Store())],
                        value=ast.Constant(None),
                    ))
            else:
                delayed_name = f"delayed_{target_name}"
                assignment.targets[0].id = delayed_name
                owner.body.append(ast.Assign(
                    targets=[ast.Name(id=target_name, ctx=ast.Store())],
                    value=ast.Name(id=delayed_name, ctx=ast.Load()),
                ))
            ordered_findings = task6_writer_static_findings(
                path, ast.unparse(ast.fix_missing_locations(ordered_tree))
            )
            assert any("GAMMA_GEOMETRY_DATAFLOW" in finding
                       for finding in ordered_findings), (
                           kind, ordering, owner_name, ordered_findings)

    fallback_tree = ast.parse(source)
    fallback_call = next(
        node for function in _task6_reachable_functions(fallback_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
        and node.func.id == "cpsi_bellplus" and len(node.args) >= 2
        and ast.unparse(node.args[1]) == "declared_gamma"
    )
    fallback_call.args[1] = ast.Subscript(
        value=ast.Name(id="data", ctx=ast.Load()),
        slice=ast.Constant("gamma_calib"), ctx=ast.Load(),
    )
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(fallback_tree))
    )

    visible_tree = ast.parse(source)
    visible_call = next(
        node for function in _task6_reachable_functions(visible_tree).values()
        for node in _task6_live_nodes(function)
        if isinstance(node, ast.Call)
        and any(isinstance(part, ast.Constant)
                and isinstance(part.value, str)
                and "declared T2-echo input:" in part.value
                for part in ast.walk(node))
    )
    declared_name = next(part for part in ast.walk(visible_call)
                         if isinstance(part, ast.Name)
                         and part.id == "declared_gamma")
    declared_name.id = "gamma_fit"
    assert task6_writer_static_findings(
        path, ast.unparse(ast.fix_missing_locations(visible_tree))
    )


def test_task6_f97_render_constructions_are_source_bound(tmp_path):
    quarter_expected = np.array((0.25, 0.25j, -0.25, -0.25j, 0.25))
    cardioid_expected = np.array((0.25, 0.25 + 0.5j, -0.75,
                                  0.25 - 0.5j, 0.25))
    for path, contract in TASK6_F97_RENDER_CONTRACTS.items():
        source = read_host(path)
        tree = ast.parse(source)
        assert not _task6_f97_render_findings(path, tree), \
            _task6_f97_render_findings(path, tree)
        for helper_name in contract["helpers"]:
            copied = source_copy_definitions(
                source, {helper_name}, tmp_path,
                prelude=("import numpy as np\nCUSP = 0.25\n"
                         if helper_name == "quarter_circle"
                         else "import numpy as np\n"),
            )
            values = copied[helper_name](5)
            expected = (quarter_expected if helper_name == "quarter_circle"
                        else cardioid_expected)
            assert values == pytest.approx(expected, rel=0, abs=1e-14)
            if helper_name != "quarter_circle":
                theta = np.linspace(0.0, 2.0 * np.pi, 5)
                selected = np.exp(1j * theta) / 2.0
                assert values == pytest.approx(selected - selected * selected,
                                                rel=0, abs=1e-14)
                assert abs(values[0]) == pytest.approx(0.25, abs=1e-14)
                assert abs(values[1]) ** 2 == pytest.approx(5 / 16,
                                                           abs=1e-14)
                assert abs(values[2]) == pytest.approx(0.75, abs=1e-14)


def test_task6_f97_render_formula_and_object_swap_mutations_fail():
    for path, contract in TASK6_F97_RENDER_CONTRACTS.items():
        source = read_host(path)
        assert not _task6_f97_render_findings(path, ast.parse(source))
        for helper_name in contract["helpers"]:
            coefficient_tree = ast.parse(source)
            helper = _task6_top_level_functions(coefficient_tree)[helper_name]
            constants = [node for node in ast.walk(helper)
                         if isinstance(node, ast.Constant)
                         and node.value in {0.25, 2.0, 4.0}]
            assert constants, (path, helper_name)
            constants[-1].value = 3.0
            findings = _task6_f97_render_findings(
                path, ast.fix_missing_locations(coefficient_tree))
            assert any("F97_CONSTRUCTION" in finding
                       for finding in findings), (path, helper_name, findings)

            sign_tree = ast.parse(source)
            helper = _task6_top_level_functions(sign_tree)[helper_name]
            exponential = next(
                node for node in ast.walk(helper) if isinstance(node, ast.Call)
                and ast.unparse(node.func) == "np.exp"
            )
            exponential.args[0] = ast.UnaryOp(
                op=ast.USub(), operand=exponential.args[0])
            findings = _task6_f97_render_findings(
                path, ast.fix_missing_locations(sign_tree))
            assert any("F97_CONSTRUCTION" in finding
                       for finding in findings), (path, helper_name, findings)

        call_tree = ast.parse(source)
        expected_name, expected_arguments, _tag = contract["calls"][0]
        selected = next(
            node for function in _task6_reachable_functions(call_tree).values()
            for node in _task6_live_nodes(function)
            if _task6_direct_call_signature(node)
            == (expected_name, expected_arguments)
        )
        selected.func.id = ("main_cardioid" if expected_name == "quarter_circle"
                            else "quarter_circle")
        findings = _task6_f97_render_findings(
            path, ast.fix_missing_locations(call_tree))
        assert any("F97_CALLS" in finding or "F97_GEOMETRY" in finding
                   for finding in findings), (path, findings)


def test_task6_f25_render_helpers_and_control_values_are_source_bound(tmp_path):
    times = np.array((0.0, 0.125, 0.75))
    expected_f = np.exp(-4.0 * times)
    expected_radius = expected_f * (1.0 + expected_f * expected_f) / 6.0
    for path, contract in TASK6_F25_RENDER_CONTRACTS.items():
        source = read_host(path)
        tree = ast.parse(source)
        assert not _task6_f25_render_findings(path, tree), \
            _task6_f25_render_findings(path, tree)
        copied = source_copy_definitions(
            source, {contract["helper"]}, tmp_path,
            prelude="import numpy as np\n",
        )
        helper = copied[contract["helper"]]
        values = (helper(times, 1.0)
                  if len(contract["parameters"]) == 2 else helper(times))
        assert values == pytest.approx(expected_radius, rel=0, abs=1e-15)

    f_half = Fraction(1, 2)
    assert f_half * (1 + f_half * f_half) / 6 == Fraction(5, 48)
    f_star = brentq(lambda f: f * (1 + f * f) / 6 - 0.25, 0.0, 1.0)
    assert f_star == pytest.approx(0.8612240997395736, rel=0, abs=1e-15)
    assert (1 + 3 * f_star * f_star) / 6 > 0
    assert f_star > 0


def test_task6_f25_formula_and_result_to_geometry_mutations_fail():
    for path, contract in TASK6_F25_RENDER_CONTRACTS.items():
        source = read_host(path)
        assert not _task6_f25_render_findings(path, ast.parse(source))

        exponent_tree = ast.parse(source)
        helper = _task6_top_level_functions(exponent_tree)[contract["helper"]]
        exponent = next(
            node for node in ast.walk(helper) if isinstance(node, ast.Call)
            and ast.unparse(node.func) == "np.exp"
        )
        four = next(node for node in ast.walk(exponent.args[0])
                    if isinstance(node, ast.Constant) and node.value == 4.0)
        four.value = 2.0
        findings = _task6_f25_render_findings(
            path, ast.fix_missing_locations(exponent_tree))
        assert any("F25_CONSTRUCTION" in finding
                   for finding in findings), (path, "exponent", findings)

        coefficient_tree = ast.parse(source)
        helper = _task6_top_level_functions(coefficient_tree)[contract["helper"]]
        denominator = next(
            node for node in ast.walk(helper) if isinstance(node, ast.Constant)
            and node.value == 6.0
        )
        denominator.value = 3.0
        findings = _task6_f25_render_findings(
            path, ast.fix_missing_locations(coefficient_tree))
        assert any("F25_CONSTRUCTION" in finding
                   for finding in findings), (path, "coefficient", findings)

        for expected_arguments, _tag in contract["calls"]:
            hardcode_tree = ast.parse(source)
            reachable = _task6_reachable_functions(hardcode_tree)
            call = next(
                node for function in reachable.values()
                for node in _task6_live_nodes(function)
                if _task6_direct_call_signature(node)
                == (contract["helper"], expected_arguments)
            )
            owner_name, owner, assignment = next(
                (name, function, node)
                for name, function in reachable.items()
                for node in _task6_live_nodes(function)
                if isinstance(node, ast.Assign) and len(node.targets) == 1
                and call in tuple(ast.walk(node.value))
            )
            preserved = ast.parse(ast.unparse(call), mode="eval").body
            assignment.value = ast.Call(
                func=ast.Attribute(value=ast.Name(id="np", ctx=ast.Load()),
                                   attr="full_like", ctx=ast.Load()),
                args=[ast.parse(expected_arguments[0], mode="eval").body,
                      ast.Constant(0.25)], keywords=[],
            )
            owner.body.append(ast.Expr(value=preserved))
            findings = _task6_f25_render_findings(
                path, ast.fix_missing_locations(hardcode_tree))
            assert any("F25_GEOMETRY" in finding
                       for finding in findings), \
                (path, owner_name, expected_arguments, findings)


