def test_task6_each_quarter_site_and_role_mutation_fails():
    class ReplaceIdentity(ast.NodeTransformer):
        def __init__(self, target, replacement):
            self.target = target
            self.replacement = replacement

        def generic_visit(self, node):
            if node is self.target:
                return self.replacement
            return super().generic_visit(node)

    for path, contract in TASK6_QUARTER_PRIMITIVE_CONTRACTS.items():
        source = read_host(path)
        assert not _task6_quarter_primitive_findings(path, ast.parse(source))
        constant = contract.get("constant")
        if constant is not None:
            tree = ast.parse(source)
            assignment = next(
                node for node in tree.body if isinstance(node, ast.Assign)
                and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)
                and node.targets[0].id == constant[0]
            )
            assignment.value = ast.Constant(0.20)
            findings = _task6_quarter_primitive_findings(
                path, ast.fix_missing_locations(tree))
            assert any("QUARTER_CONSTANT" in finding for finding in findings), \
                (path, findings)

        for site in contract["sites"]:
            tree = ast.parse(source)
            _owner, target = _task6_quarter_site_node(tree, site)
            assert target is not None, (path, site["name"])
            tree = ReplaceIdentity(target, ast.Constant(0.20)).visit(tree)
            findings = _task6_quarter_primitive_findings(
                path, ast.fix_missing_locations(tree))
            assert any(site["name"] in finding or "QUARTER_" in finding
                       for finding in findings), (path, site["name"], findings)

            role_tree = ast.parse(source)
            owner, _target = _task6_quarter_site_node(role_tree, site)
            scope = (owner if site["role_scope"] == "call" else
                     _task6_top_level_functions(role_tree)[site["function"]])
            changed = False
            for literal in ast.walk(scope):
                if (isinstance(literal, ast.Constant)
                        and isinstance(literal.value, str)
                        and site["role"] in literal.value):
                    literal.value = literal.value.replace(
                        site["role"], "wrong quarter object")
                    changed = True
            assert changed, (path, site["name"], site["role"])
            findings = _task6_quarter_primitive_findings(
                path, ast.fix_missing_locations(role_tree))
            assert any(
                f"QUARTER_ROLE:{site['name']}" in finding
                or f"QUARTER_SITE:{site['name']}" in finding
                for finding in findings
            ), (path, site["name"], findings)


