def _task6_cpsi_phase_control(source, directory):
    directory.mkdir()
    copied = source_copy_definitions(
        source,
        {"site_op", "liouvillian", "cpsi_real", "cpsi_complex",
         "bell_plus_phased", "trajectory"},
        directory,
        prelude=(
            "import numpy as np\nfrom scipy.linalg import expm\n"
            "I2 = np.eye(2, dtype=complex)\n"
            "Z = np.array([[1, 0], [0, -1]], dtype=complex)\n"
        ),
    )
    phi, gamma, omega, elapsed = 0.37, 0.20, 0.60, 0.40
    rho0 = copied["bell_plus_phased"](phi)
    result = copied["trajectory"](gamma, omega, phi, elapsed, 2)
    return np.array((rho0[0, 3], result["cpsi_complex"][0],
                     result["cpsi_complex"][-1])), (phi, gamma, omega, elapsed)


def test_task6_cpsi_preparation_and_lindblad_phase_are_source_bound(tmp_path):
    path = "simulations/cpsi_complex_plane.py"
    source = read_host(path)
    assert not _task6_cpsi_dynamics_findings(path, ast.parse(source))
    observed, (phi, gamma, omega, elapsed) = _task6_cpsi_phase_control(
        source, tmp_path / "base")
    f = np.exp(-4.0 * gamma * elapsed)
    expected = np.array((
        np.exp(-1j * phi) / 2.0,
        np.exp(-1j * phi) / 3.0,
        f * (1.0 + f * f) * np.exp(-1j * (phi + omega * elapsed)) / 6.0,
    ))
    assert observed == pytest.approx(expected, rel=0, abs=2e-13)

    mutations = (
        ("np.exp(1j * phi)", "np.exp(-1j * phi)"),
        ("h = (detuning_sum / 4.0)", "h = -(detuning_sum / 4.0)"),
        ("np.sqrt(gamma) * site_op(Z, 0, 2)",
         "np.sqrt(gamma / 2.0) * site_op(Z, 0, 2)"),
        ("expm(L * t)", "expm(-L * t)"),
    )
    for index, (old, new) in enumerate(mutations):
        mutant = source.replace(old, new, 1)
        assert mutant != source, old
        findings = _task6_cpsi_dynamics_findings(path, ast.parse(mutant))
        assert findings, (old, findings)
        mutated, _ = _task6_cpsi_phase_control(mutant, tmp_path / f"mut-{index}")
        assert not np.allclose(mutated, expected, rtol=0, atol=2e-13), old


