def task6_text_writer_static_findings(path, source):
    findings = list(import_safety_findings(path, source))
    tree = ast.parse(source)
    mains = [node for node in tree.body
             if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
             and node.name == "main"]
    main = mains[0] if len(mains) == 1 else None
    if main is None:
        findings.append(f"{path}:MAIN_COUNT")
    elif "output_path" not in {
        arg.arg for arg in main.args.args + main.args.kwonlyargs
    }:
        findings.append(f"{path}:MAIN_OUTPUT_PATH")
    destination_assignments = [] if main is None else [
        node for node in ast.walk(main)
        if isinstance(node, ast.Assign)
        and any(isinstance(target, ast.Name) and target.id == "destination"
                for target in node.targets)
    ]
    if main is not None and len(destination_assignments) != 1:
        findings.append(
            f"{path}:DESTINATION_ASSIGNMENT_COUNT:{len(destination_assignments)}"
        )
    elif main is not None:
        assignment = destination_assignments[0]
        if not (
            len(assignment.targets) == 1
            and isinstance(assignment.targets[0], ast.Name)
            and isinstance(assignment.value, ast.Call)
            and isinstance(assignment.value.func, ast.Name)
            and assignment.value.func.id == "Path"
            and len(assignment.value.args) == 1
            and isinstance(assignment.value.args[0], ast.Name)
            and assignment.value.args[0].id == "output_path"
        ):
            findings.append(f"{path}:OUTPUT_PATH_NOT_ROUTED")
    if main is not None:
        writes = [node for node in ast.walk(main)
                  if isinstance(node, ast.Call)
                  and isinstance(node.func, ast.Attribute)
                  and isinstance(node.func.value, ast.Name)
                  and node.func.value.id == "destination"
                  and node.func.attr == "write_bytes"]
        if len(writes) != 1:
            findings.append(f"{path}:DESTINATION_WRITE_BYTES_COUNT:{len(writes)}")
        for node in ast.walk(main):
            if not isinstance(node, ast.Call):
                continue
            is_open = isinstance(node.func, ast.Name) and node.func.id == "open"
            is_write = isinstance(node.func, ast.Attribute) and node.func.attr in {
                "open", "write_bytes", "write_text"
            }
            if not (is_open or is_write):
                continue
            target = node.args[0] if is_open and node.args else (
                node.func.value if is_write else None
            )
            if target is not None and any(
                isinstance(part, ast.Name) and part.id in {"OUT_PATH", "output_path"}
                for part in ast.walk(target)
            ):
                findings.append(f"{path}:{node.lineno}:WRITE_BYPASSES_DESTINATION")
    cli_output = any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "add_argument"
        and node.args
        and isinstance(node.args[0], ast.Constant)
        and node.args[0].value == "--output"
        for node in ast.walk(tree)
    )
    if not cli_output:
        findings.append(f"{path}:NO_CLI_OUTPUT")

    for node in ast.walk(tree):
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "log"):
            continue
        payload = ast.unparse(node).lower()
        if re.search(r"total runtime|elapsed|results saved to|abspath|output_path|out_path", payload):
            findings.append(f"{path}:{node.lineno}:NONDETERMINISTIC_PAYLOAD")
    return tuple(findings)


def task6_active_log_source(source):
    calls = []

    class LiveLogVisitor(ast.NodeVisitor):
        def visit_If(self, node):
            if isinstance(node.test, ast.Constant) and node.test.value is False:
                for statement in node.orelse:
                    self.visit(statement)
                return
            if isinstance(node.test, ast.Constant) and node.test.value is True:
                for statement in node.body:
                    self.visit(statement)
                return
            self.generic_visit(node)

        def visit_Call(self, node):
            if isinstance(node.func, ast.Name) and node.func.id == "log":
                calls.append(ast.unparse(node))
            self.generic_visit(node)

    LiveLogVisitor().visit(ast.parse(source))
    return "\n".join(calls)


def task6_text_writer_semantic_findings(path, source):
    structural_required = {
        "simulations/monotonicity_remaining.py": (
            "eligible_count > 0",
            "crossed_count == eligible_count",
            "rising_steps_above_quarter",
            "above threshold / 2",
            "def task_a_random_density_matrices",
            "rng = np.random.RandomState(seed)",
            "rng.randn(dimension)",
            "task_a_random_density_matrices(dimension=d, count=10, seed=42)",
        ),
        "simulations/non_markovian_revival.py": (
            "cpsi_arr[i] > max_revival",
            "best_revival_row(revival_rows)",
            '(0.05, "|01>", rho0_01)',
            "markov_control = test_1_markovian()",
            "markov_control['cross_down']",
            "markov_control['cross_up']",
        ),
        "simulations/test2_no_signalling.py": (
            "def quarter_band",
            "def no_signalling_reading",
            "no_signalling_reading(rho_A_before, rho_A_after)",
            "return p0 @ rho @ p0.conj().T + p1 @ rho @ p1.conj().T",
        ),
    }.get(path, ())
    visible_required = {
        "simulations/monotonicity_remaining.py": (
            "Eligible pairs crossing 1/4: 0/0; all eligible crossed: not applicable (0 eligible).",
            "Finite catalogue: 19 initial states on the stated t=0..80, dt=0.02 grid.",
        ),
        "simulations/non_markovian_revival.py": (
            "constant-gamma Markovian |01> control:",
            "Recrossing alone does not classify memory.",
            "finite configured catalogue",
        ),
        "simulations/test2_no_signalling.py": (
            "No-signalling verdict: rho_A is unchanged",
            "The scalar quarter-band change is not a physical boundary.",
            "Global purity:",
            "Scalar readout:",
        ),
    }.get(path, ())
    forbidden = {
        "simulations/monotonicity_remaining.py": (
            "All subsystems cross 1/4",
            "#Osc",
            "n_osc",
            "default_rng",
            "standard_normal",
        ),
        "simulations/non_markovian_revival.py": (
            "NON-MARKOVIAN REVIVAL ABOVE 1/4 FOUND",
            "absorbing even non-Markovianly",
            "Layer 5 can be considered closed",
        ),
        "simulations/test2_no_signalling.py": (
            "CΨ Regime Change",
            "def regime",
            "quantum\"",
            "classical\"",
            "bridge",
            "Basis-specific scalar",
        ),
    }.get(path, ())
    visible_required = visible_required + TASK6_TEXT_WRITER_FOOTERS.get(path, ())
    active_logs = task6_active_log_source(source)
    findings = [f"{path}:MISSING_STRUCTURE:{token}"
                for token in structural_required if token not in source]
    findings.extend(f"{path}:MISSING_ACTIVE_LOG:{token}"
                    for token in visible_required if token not in active_logs)
    findings.extend(f"{path}:STALE:{token}" for token in forbidden if token in source)
    return tuple(findings)


def task6_unwrap_theta_pc_capture(raw):
    assert not raw.startswith(b"\xef\xbb\xbf")
    assert b"\r" not in raw
    assert raw.endswith(b"\n") and not raw.endswith(b"\n\n")
    begin = b"=== BEGIN CAPTURED PAYLOAD ===\n"
    end = b"=== END CAPTURED PAYLOAD ==="
    assert raw.count(begin) == raw.count(end) == 1
    before, rest = raw.split(begin, 1)
    payload, after = rest.split(end, 1)
    before_text = before.decode("utf-8")
    for token in (
        "QUARTER-CURRENT",
        "CAPTURED-ONLY",
        "derived scalar coordinate",
        "basis- and model-specific",
        "not a quantum/classical classification",
        "PCA uses AB features over 501 star-topology snapshots",
        "largest local theta-above count is SA=45",
        "r=0.87 is from a separate theta_SB versus F_channel selection",
        "24.3%=1-r^2 and is not evidence that omitted PCs cause the gap",
        "theta>0 = above-quarter samples; theta=0 = below-or-at-quarter samples",
    ):
        assert token in before_text
    assert after.startswith(b"\n")
    assert "never execute" in after.decode("utf-8").lower()
    return payload


