@pytest.mark.parametrize("path", TASK6_TEXT_RERUN_WRITERS)
def test_task6_output_path_cannot_be_dummy_read_then_bypassed(path):
    source = read_host(path)
    old = "destination = Path(output_path)"
    assert old in source
    mutants = (
        source.replace(old, "destination = Path(OUT_PATH)", 1),
        source.replace(
            old,
            "ignored = output_path\n"
            "    OUT_PATH.write_text('bypass')\n"
            "    destination = Path(OUT_PATH)",
            1,
        ),
    )
    for mutant in mutants:
        findings = task6_text_writer_static_findings(path, mutant)
        assert any(
            marker in finding
            for finding in findings
            for marker in ("OUTPUT_PATH_NOT_ROUTED", "DESTINATION_ASSIGNMENT_COUNT")
        )
        assert findings

    rebound = source.replace(
        old,
        "if False:\n"
        "        destination = Path(output_path)\n"
        "    destination = Path(OUT_PATH)",
        1,
    )
    assert "DESTINATION_ASSIGNMENT_COUNT" in "\n".join(
        task6_text_writer_static_findings(path, rebound)
    )


