def task6_text_payload_byte_findings(path, payload):
    findings = []
    if payload.startswith(b"\xef\xbb\xbf"):
        findings.append("BOM")
    if b"\r" in payload:
        findings.append("CR")
    if not payload.endswith(b"\n") or payload.endswith(b"\n\n"):
        findings.append("TERMINAL_LF")
    try:
        payload.decode("utf-8")
    except UnicodeDecodeError:
        findings.append("UTF8")
    footer = TASK6_TEXT_WRITER_FOOTERS.get(path)
    if footer is not None:
        expected = ("\n".join(footer) + "\n").encode("utf-8")
        if not payload.endswith(expected):
            findings.append("FOOTER")
    return tuple(findings)


def task6_text_result_semantic_findings(writer_path, text):
    required = {
        "simulations/two_qubits_no_noise.py": (
            "QUARTER-CURRENT: fixed N=2 Heisenberg chain",
            "63 down and 64 up crossings",
            "2 down and 2 up crossings",
            "not an absorbing boundary",
            "This count does not identify unordered pairs.",
            "16/16 entries about their own centres, 0 and -0.10.",
        ),
        "simulations/monotonicity_remaining.py": (
            "Finite catalogue: 19 initial states on the stated t=0..80, dt=0.02 grid.",
            "#Rise",
            "Eligible pairs crossing 1/4: 0/0",
            "not applicable (0 eligible)",
        ),
        "simulations/non_markovian_revival.py": (
            "Finite CΨ Recrossing Catalogue",
            "constant-gamma Markovian |01> control: 2 down, 2 up",
            "This is a finite configured catalogue, not a memory classifier.",
            "Recrossing alone does not classify memory.",
        ),
        "simulations/test2_no_signalling.py": (
            "No-signalling and a separate scalar quarter-band readout",
            "No-signalling verdict: rho_A is unchanged",
            "The exact reduced-state equality carries the no-signalling statement.",
            "The scalar quarter-band change is not a physical boundary.",
        ),
    }[writer_path] + TASK6_TEXT_WRITER_FOOTERS.get(writer_path, ())
    forbidden = {
        "simulations/two_qubits_no_noise.py": (
            "absorbing boundary: True",
        ),
        "simulations/monotonicity_remaining.py": (
            "#Osc",
            "All subsystems cross 1/4",
        ),
        "simulations/non_markovian_revival.py": (
            "NON-MARKOVIAN REVIVAL ABOVE 1/4 FOUND",
            "absorbing even non-Markovianly",
            "Layer 5 can be considered closed",
        ),
        "simulations/test2_no_signalling.py": (
            "CΨ Regime Change",
            "quantum    boundary",
            "classical    boundary",
            "Dynamic bridge eliminated",
        ),
    }[writer_path] + (
        "Total runtime:",
        "Results saved to:",
        str(ROOT),
    )
    normalized = re.sub(r"\s+", " ", text)
    findings = [f"{writer_path}:RESULT_MISSING:{token}"
                for token in required if token not in normalized]
    if writer_path == "simulations/test2_no_signalling.py":
        for name, pattern in (
            ("PURITY_1_TO_HALF", r"Global purity:\s+1\.000\s+->\s+0\.500"),
            ("SCALAR_HALF_TO_QUARTER", r"Scalar readout:\s+0\.500\s+->\s+0\.250"),
        ):
            if re.search(pattern, text) is None:
                findings.append(f"{writer_path}:RESULT_MISSING:{name}")
    findings.extend(f"{writer_path}:RESULT_STALE:{token}"
                    for token in forbidden if token in text)
    return tuple(findings)


