def task6_monotonicity_test_a_canonical_rows(text):
    lines = text.splitlines()
    header = next(i for i, line in enumerate(lines)
                  if re.match(r"^\s*State\s+CPsi0\s+t_cross\s+#(?:Osc|Rise)", line))
    end = next(i for i in range(header + 1, len(lines))
               if "All states starting above 1/4 cross:" in lines[i])
    rows = [re.sub(r"\s+", " ", line.strip())
            for line in lines[header + 2:end] if line.strip()]
    return ("\n".join(rows) + "\n").encode("utf-8")


def task6_monotonicity_test_a_table_findings(text):
    try:
        canonical = task6_monotonicity_test_a_canonical_rows(text)
    except (StopIteration, ValueError):
        return ("MONOTONICITY_TEST_A_TABLE_MISSING",)
    findings = []
    if canonical.count(b"\n") != 19:
        findings.append("MONOTONICITY_TEST_A_ROW_COUNT")
    if hashlib.sha256(canonical).hexdigest().upper() != \
            TASK6_MONOTONICITY_TEST_A_ROWS_SHA256:
        findings.append("MONOTONICITY_TEST_A_ROWS_SHA256")
    return tuple(findings)


def task6_text_temp_payload_findings(writer_path, payload):
    findings = list(task6_text_payload_byte_findings(writer_path, payload))
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        return tuple(findings)
    findings.extend(task6_text_result_semantic_findings(writer_path, text))
    if writer_path == "simulations/monotonicity_remaining.py":
        findings.extend(task6_monotonicity_test_a_table_findings(text))
    return tuple(findings)


