    rand9 = next(line for line in text.splitlines() if "Rand9" in line)
    rand7 = next(line for line in text.splitlines() if "Rand7" in line)
    rand8 = next(line for line in text.splitlines() if "Rand8" in line)
    late_row_mutant = text.replace(
        rand9, rand9.replace("0.6569", "0.6568", 1), 1
    )
    reordered = text.replace(rand7, "__TASK6_RAND7__", 1)
