def test_task6_monotonicity_random_catalogue_keeps_local_mt19937_sequence(tmp_path):
    path = "simulations/monotonicity_remaining.py"
    source = read_host(path)
    namespace = source_copy_definitions(
        source, {"task_a_random_density_matrices"}, tmp_path
    )
    build = namespace["task_a_random_density_matrices"]

    saved_global_state = np.random.get_state()
    try:
        np.random.seed(1729)
        expected_global_tail = np.random.random(4)
        np.random.seed(1729)
        densities = build(dimension=4, count=10, seed=42)
        actual_global_tail = np.random.random(4)
    finally:
        np.random.set_state(saved_global_state)

    assert len(densities) == 10
    assert np.allclose(actual_global_tail, expected_global_tail, rtol=0, atol=0)
    assert densities[0][0, 0] == pytest.approx(
        0.048657321917989986 + 7.944383763777769e-20j, rel=0, abs=1e-15
    )
    assert densities[0][0, 1] == pytest.approx(
        -0.0022354050129268265 + 0.023989461227523455j, rel=0, abs=1e-15
    )
    assert densities[0][2, 3] == pytest.approx(
        0.35472352238277 + 0.3078880059405847j, rel=0, abs=1e-15
    )

    pcg64_mutant = source.replace(
        "np.random.RandomState(seed)", "np.random.default_rng(seed)", 1
    ).replace("rng.randn(dimension)", "rng.standard_normal(dimension)")
    assert pcg64_mutant != source
    assert task6_text_writer_semantic_findings(path, pcg64_mutant)
    mutant_build = source_copy_definitions(
        pcg64_mutant, {"task_a_random_density_matrices"}, tmp_path
    )["task_a_random_density_matrices"]
    assert not np.allclose(mutant_build(4, 10, 42)[0], densities[0])


