def test_task6_no_signalling_averaged_channel_control_and_postselection_mutation(
    tmp_path,
):
    path = "simulations/test2_no_signalling.py"
    source = read_host(path)
    names = {
        "site_op", "ptrace_A", "purity", "apply_B_measurement_Z", "cpsi",
        "no_signalling_reading",
    }
    prelude = """import numpy as np
I2 = np.eye(2, dtype=complex)
up = np.array([1, 0], dtype=complex)
dn = np.array([0, 1], dtype=complex)
N = 2
"""

    def readings(candidate):
        namespace = source_copy_definitions(
            candidate, names, tmp_path, prelude=prelude
        )
        bell = (np.kron(up := np.array([1, 0], dtype=complex), up)
                + np.kron(dn := np.array([0, 1], dtype=complex), dn)) / np.sqrt(2)
        before = np.outer(bell, bell.conj())
        after = namespace["apply_B_measurement_Z"](before)
        rho_a_before = namespace["ptrace_A"](before)
        rho_a_after = namespace["ptrace_A"](after)
        return (
            namespace["no_signalling_reading"](rho_a_before, rho_a_after)[1],
            namespace["purity"](before),
            namespace["purity"](after),
            namespace["cpsi"](before),
            namespace["cpsi"](after),
        )

    assert readings(source) == pytest.approx((True, 1.0, 0.5, 0.5, 0.25))
    channel = "return p0 @ rho @ p0.conj().T + p1 @ rho @ p1.conj().T"
    assert channel in source
    postselected = source.replace(channel, "return p0 @ rho @ p0.conj().T", 1)
    assert readings(postselected) != pytest.approx((True, 1.0, 0.5, 0.5, 0.25))


