def test_task6_text_writer_two_fresh_process_payloads_match(path, tmp_path):
    if os.environ.get("TASK6_EXECUTE_TEXT_WRITER") != path:
        pytest.skip("explicit per-writer execution interlock is closed")
    before = artifact_hashes()
    outputs = []
    for index in (1, 2):
        output = tmp_path / f"run-{index}.txt"
        subprocess.run(
            [sys.executable, str(ROOT / path), "--output", str(output)],
            cwd=ROOT, check=True, capture_output=True, timeout=1800,
        )
        outputs.append(output.read_bytes())
    assert artifact_hashes() == before
    assert outputs[0] == outputs[1]
    for payload in outputs:
        findings = task6_text_temp_payload_findings(path, payload)
        assert not findings, findings


