def task6_unwrap_captured_payload(path, text):
    if path in TASK6_TORINO_CAPTURE_SHAPES:
        markers = (
            "=== BEGIN CURRENT READING ===",
            "=== END CURRENT READING ===",
            "=== BEGIN HISTORICAL PAYLOAD ===",
            "=== END HISTORICAL PAYLOAD ===",
        )
        assert all(text.count(marker) == 1 for marker in markers), path
        assert text.startswith(markers[0] + "\n"), path
        current, rest = text[len(markers[0]) + 1:].split("\n" + markers[1] + "\n", 1)
        assert "QUARTER-CURRENT" in current
        assert "normalized-purity proxy" in current
        assert "historical" in current.lower()
        assert rest.startswith(markers[2] + "\n"), path
        payload, after = rest[len(markers[2]) + 1:].split(markers[3], 1)
        expected_bytes, expected_lines = TASK6_TORINO_CAPTURE_SHAPES[path]
        assert len(payload.encode("utf-8")) == expected_bytes, path
        assert payload.count("\n") == expected_lines, path
        assert after.startswith("\n"), path
        return payload.encode("utf-8")

    begin = "=== BEGIN CAPTURED PAYLOAD ==="
    end = "=== END CAPTURED PAYLOAD ==="
    assert text.count(begin) == text.count(end) == 1, path
    before, rest = text.split(begin, 1)
    payload, after = rest.split(end, 1)
    assert "QUARTER-CURRENT" in before
    assert "historical" in before.lower() or "captured" in before.lower()
    assert "current" in after.lower()
    payload = payload.removeprefix("\n")
    expected_terminal = TASK6_CAPTURED_PAYLOADS[path][1]
    if expected_terminal:
        assert payload.endswith("\n")
    else:
        payload = payload.removesuffix("\n")
    return payload.encode("utf-8")


