def _task6_flat_csharp_source(source):
    return re.sub(r"\s+", " ", source.replace("///", " ")).strip()


def _task6_csharp_code_without_line_comments(source):
    return "\n".join(line.split("//", 1)[0] for line in source.splitlines())


def task6_mirror_system_findings(source):
    findings = []
    flat = _task6_flat_csharp_source(source)
    compact = re.sub(r"\s+", "", source)
    compact_folded = compact.casefold()

    for label, phrase in TASK6_MIRROR_SYSTEM_REQUIRED_PROSE:
        if phrase not in flat:
            findings.append(f"MIRROR_SYSTEM:MISSING_OWNER:{label}")

    stale_tokens = (
        ("OMEGA_EQUALS_2J", "ω=2J"),
        ("ARCTAN_Q", "arctan(Q)"),
        ("GENERIC_F95", "theF95angle"),
        ("F95_COMPOSITION", "canonicalandcomposingwithF95"),
        ("SAME_MODE_TAU", "Takt'sTautracks"),
        ("J_NOT_ZERO_EQUIVALENCE", "i.e.J≠0"),
        ("J_ZERO_EQUIVALENCE", "J=0"),
        ("UNCONDITIONAL_NO_DECAY_PI2",
         "anglereachesitsmaximumθ=π/2"),
        ("EVERY_POSITIVE_GAP", "everyGap>0"),
        ("EXACT_GAMMA_ZERO_BRANCH", "exactlygamma=0"),
        ("RECORD_NO_DECAY_SPECTRUM", "most-rotatingmodeintheno-decayspectrum"),
        ("RECORD_NO_DECAY_PI2", "π/2onlyforano-decayreading"),
        ("RECORD_UNIVERSAL_ATAN2",
         '<seecref="Angle"/>isθ=atan2(ω,Gap)'),
        ("OSCILLATORY_MODE_IMPLIES_PI2",
         "containsanoscillatorymode,itgivesθ=π/2"),
        ("COMMENT_OSCILLATORY_MODE_IMPLIES_PI2",
         "Onlyanoscillatorymodegivestheπ/2circle"),
        ("OMEGA_NONZERO_IMPLIES_TURNING",
         "istruewhentheselectedreadinghasω≠0"),
        ("TURNING_FALSE_IMPLIES_ZERO_ANGLE",
         "IfTurningisfalse,theangleis0"),
    )
    for label, token in stale_tokens:
        if token.casefold() in compact_folded:
            findings.append(f"MIRROR_SYSTEM:STALE:{label}")
    if re.search(
            r"(?:arc)?tan\(J/(?:γ₀|γ0|gamma0)\)", compact,
            flags=re.IGNORECASE):
        findings.append("MIRROR_SYSTEM:STALE:J_OVER_GAMMA_ANGLE")
    if source.count("F95") != 1:
        findings.append("MIRROR_SYSTEM:F95_CARDINALITY")

    method = re.search(
        r"private RotationReading ComputeRotation\(\)\s*\{(?P<body>.*?)\n    \}",
        source,
        flags=re.DOTALL,
    )
    if method is None:
        findings.append("MIRROR_SYSTEM:COMPUTE_ROTATION_METHOD")
        return tuple(findings)

    code = _task6_csharp_code_without_line_comments(method.group("body"))
    compact_code = re.sub(r"\s+", "", code)
    if "constdoubletol=1e-9;" not in compact_code:
        findings.append("MIRROR_SYSTEM:DATAFLOW:ROTATION_BOUNDARY_LITERAL")
    if "doublegap=Spectrum.SlowestRate;" not in compact_code:
        findings.append("MIRROR_SYSTEM:DATAFLOW:GAP_FROM_SPECTRUM")
    if "if(gap>tol)" not in compact_code or \
            "doublefreq=Spectrum.Modes" not in compact_code:
        findings.append("MIRROR_SYSTEM:DATAFLOW:BRANCH_BOUNDARY")
        return tuple(findings)

    positive_gap = compact_code.split("if(gap>tol)", 1)[1].split(
        "doublefreq=Spectrum.Modes", 1)[0]
    no_decay = compact_code.split("doublefreq=Spectrum.Modes", 1)[1]
    if ".Where(m=>Math.Abs(m.ActualDecayRate-gap)<=tol)" not in positive_gap:
        findings.append("MIRROR_SYSTEM:DATAFLOW:SLOW_SHELF_FILTER")
    if (".Select(m=>Math.Abs(m.OscillationFrequency))"
            ".DefaultIfEmpty(0.0).Max();" not in positive_gap):
        findings.append("MIRROR_SYSTEM:DATAFLOW:SHELF_MAX_IMAGINARY")
    if "Math.Atan2(frequency,gap)" not in positive_gap:
        findings.append("MIRROR_SYSTEM:DATAFLOW:MEASURED_ATAN2")
    if (".Select(m=>Math.Abs(m.OscillationFrequency))"
            ".DefaultIfEmpty(0.0).Max();" not in no_decay):
        findings.append("MIRROR_SYSTEM:DATAFLOW:NO_DECAY_MAX_IMAGINARY")
    if "boolturning=freq>tol;" not in no_decay:
        findings.append("MIRROR_SYSTEM:DATAFLOW:NO_DECAY_TURNING_READ")
    if "turning?Math.PI/2.0:0.0" not in no_decay:
        findings.append("MIRROR_SYSTEM:DATAFLOW:NO_DECAY_ANGLE_SPLIT")
    return tuple(findings)


def task6_f87_pi2_live_child_findings(source):
    findings = []
    flat = _task6_flat_csharp_source(source)
    compact_folded = re.sub(r"\s+", "", source).casefold()
    expected_row = (
        'yield return new InspectableNode("Marrakesh finite Δ row", '
        'summary: "hardware job d7mjnjjaq2pc73a1pk4g (2026-04-26): '
        'Δ(soft − truly) = −0.722");'
    )
    if flat.count(expected_row) != 1:
        findings.append("F87_PI2:FINITE_MARRAKESH_ROW")

    stale_tokens = (
        ("HARDWARE_CONFIRMATION", "F87hardwareconfirmation"),
        ("KINGSTON", "Kingston"),
        ("REGIME_UNIFORMITY", "regime-uniformity"),
    )
    for label, token in stale_tokens:
        if token.casefold() in compact_folded:
            findings.append(f"F87_PI2:STALE:{label}")
    return tuple(findings)


def task6_static_contract_findings():
    findings = defaultdict(list)
    for path in TASK6_IMAGE_WRITERS:
        findings["WRITER"].extend(task6_writer_static_findings(path, read_host(path)))
    for path in TASK6_TEXT_RERUN_WRITERS:
        source = read_host(path)
        findings["TEXT_WRITER"].extend(task6_text_writer_static_findings(path, source))
        findings["TEXT_SCOPE"].extend(task6_text_writer_semantic_findings(path, source))
    for path, (digest, _) in TASK6_CAPTURED_PAYLOADS.items():
        try:
            payload = task6_unwrap_captured_payload(path, read_host(path))
        except AssertionError as error:
            findings["CAPTURE"].append(str(error) or path)
            continue
        if hashlib.sha256(payload).hexdigest().upper() != digest:
            findings["CAPTURE"].append(f"{path}:PAYLOAD_SHA256")
    try:
        theta_payload = task6_unwrap_theta_pc_capture(
            (ROOT / TASK6_THETA_PC_CAPTURE["result"]).read_bytes()
        )
    except AssertionError:
        findings["THETA_PC_CAPTURE"].append("WRAPPER")
    else:
        if hashlib.sha256(theta_payload).hexdigest().upper() != \
                TASK6_THETA_PC_CAPTURE["payload_sha256"]:
            findings["THETA_PC_CAPTURE"].append("PAYLOAD_SHA256")
    theta_source = (ROOT / TASK6_THETA_PC_CAPTURE["source"]).read_bytes()
    if (len(theta_source) != TASK6_THETA_PC_CAPTURE["source_bytes"]
            or theta_source.count(b"\n") != TASK6_THETA_PC_CAPTURE["source_lf"]
            or b"\r" in theta_source
            or not theta_source.endswith(b"\n")
            or theta_source.startswith(b"\xef\xbb\xbf")
            or hashlib.sha256(theta_source).hexdigest().upper() !=
            TASK6_THETA_PC_CAPTURE["source_sha256"]):
        findings["THETA_PC_CAPTURE"].append("SOURCE_SHA256")
    findings["CLAIM"].extend(task6_claim_scope_findings())
    findings["MIRROR_SYSTEM"].extend(task6_mirror_system_findings(
        read_host(TASK6_MIRROR_SYSTEM_PATH)))
    findings["F87_PI2"].extend(task6_f87_pi2_live_child_findings(
        read_host(TASK6_F87_PI2_INHERITANCE_PATH)))
    return findings


