TASK7_REGION_MARKER = re.compile(
    r"(?:<!--\s*)?(/?)VEFFECT-(CURRENT|HISTORICAL|INTERPRETIVE)(?:\s*-->)?",
    re.I,
)


def _task7_normalize_paragraph(text):
    return re.sub(r"\s+", " ", text.replace("\r\n", "\n").replace("\r", "\n")).strip()


def _task7_markdown_row(source, link_fragment):
    rows = [line.strip() for line in source.splitlines()
            if line.lstrip().startswith("|") and link_fragment in line]
    assert len(rows) == 1, (link_fragment, rows)
    return _task7_normalize_paragraph(rows[0])


def _task7_region_paragraphs(source, *, require_first_marker=False):
    """Yield (region, normalized paragraph), using current as the safe default.

    Historical payloads must opt in with a marker.  Closing a bounded story
    region returns to current, which keeps the following prose fail-closed.
    """
    mode = None if require_first_marker else "CURRENT"
    for raw in re.split(r"\n\s*\n", source.replace("\r\n", "\n").replace("\r", "\n")):
        paragraph = _task7_normalize_paragraph(raw)
        if not paragraph:
            continue
        marker = TASK7_REGION_MARKER.fullmatch(paragraph)
        if marker:
            mode = "CURRENT" if marker.group(1) else marker.group(2).upper()
            yield "MARKER", paragraph
            continue
        yield mode, paragraph


def _task7_wrapper_findings(path, source):
    findings = []
    historical_marker = ("VEFFECT-HISTORICAL" if path.endswith("proton_water_chain.txt")
                         else "<!-- VEFFECT-HISTORICAL -->")
    current_marker = ("VEFFECT-CURRENT" if path.endswith("proton_water_chain.txt")
                      else "<!-- VEFFECT-CURRENT -->")
    if not source.startswith(current_marker):
        findings.append(f"{path}:MISSING_CURRENT_WRAPPER")
    if source.count(historical_marker) != 1:
        findings.append(f"{path}:MISSING_HISTORICAL_BOUNDARY")
        return findings
    current, body = source.split(historical_marker, 1)
    normalized_current = _task7_normalize_paragraph(current)
    for fragment in TASK7_WRAPPER_REQUIRED[path]:
        if fragment not in normalized_current:
            findings.append(f"{path}:MISSING_WRAPPER_SCOPE:{fragment}")
    digest = hashlib.sha256(body.encode("utf-8")).hexdigest().upper()
    if digest != TASK7_WRAPPER_BODY_SHA256[path]:
        findings.append(f"{path}:HISTORICAL_BODY_DRIFT:{digest}")
    return findings


def _task7_story_banner_findings(path, source):
    banner = "Interpretive invitation — not a result:"
    if source.count(banner) < 1:
        return [f"{path}:MISSING_INTERPRETIVE_INVITATION"]
    findings = []
    if path == "MIRROR_THEORY.md":
        paragraphs = [
            _task7_normalize_paragraph(raw)
            for raw in re.split(
                r"\n\s*\n", source.replace("\r\n", "\n").replace("\r", "\n")
            )
            if _task7_normalize_paragraph(raw)
        ]
        if (len(paragraphs) < 2
                or not paragraphs[0].startswith("# Mirror Theory")
                or not paragraphs[1].startswith(f"**{banner}")):
            findings.append(f"{path}:INTERPRETIVE_BANNER_NOT_FRONT_DOOR")
    before = source.split(banner, 1)[0]
    # H1/status metadata may precede the invitation.  A V-Effect/coupling
    # claim may not: moving the banner below such prose re-promotes the story.
    if re.search(
        r"(?:V[_\- ‑]?Effect|\b109\b|\b104\b|"
        r"(?:palindrome|pairing|coupling|connection).{0,100}"
        r"(?:creat|caus|produc|yield|release|rich|divers|mode|frequen))",
        _task7_normalize_paragraph(before), re.I,
    ):
        findings.append(f"{path}:INTERPRETIVE_BANNER_AFTER_CAUSAL_PROSE")
    return findings


