def _task7_current_surface(path, source):
    if path in TASK7_WRAPPER_REQUIRED:
        marker = ("VEFFECT-HISTORICAL" if path.endswith("proton_water_chain.txt")
                  else "<!-- VEFFECT-HISTORICAL -->")
        return source.split(marker, 1)[0]
    require_first = path == "experiments/V_EFFECT_PALINDROME.md"
    return "\n\n".join(
        paragraph
        for mode, paragraph in _task7_region_paragraphs(
            source, require_first_marker=require_first
        )
        if mode == "CURRENT"
    )


def _task7_restoration_findings(path, source):
    current = _task7_current_surface(path, source)
    findings = []
    for rule, pattern in TASK7_RESTORATION_RULES.get(path, ()):
        if re.search(pattern, current, re.I | re.S):
            findings.append(f"{path}:RESTORED_TASK7_CLAIM:{rule}")
    return findings


