def _task7_semantic_canonical(text):
    canonical = text.casefold()
    canonical = re.sub(
        r"\bone\s+hundred(?:\s+and)?\s+nine\b", "109", canonical
    )
    canonical = canonical.replace("cψ", "cpsi").replace("c_psi", "cpsi")
    canonical = canonical.replace("q_max", "qmax").replace("q_mean", "qmean")
    canonical = canonical.replace("->", " to ").replace("→", " to ").replace("⇒", " to ")
    canonical = re.sub(r"v[_\- ‑]?effect", "veffect", canonical)
    canonical = re.sub(r"\bn\s*=\s*([235])\b", r"n\1", canonical)
    for word, digit in (("three", "3"), ("four", "4"), ("five", "5"),
                        ("six", "6"), ("eight", "8"), ("eleven", "11"),
                        ("fifteen", "15")):
        canonical = re.sub(rf"\b{word}\b", digit, canonical)
    canonical = re.sub(r"(?<=\w)[‐‑–—-](?=\w)", " ", canonical)
    return re.sub(r"\s+", " ", canonical).strip()


