TASK7_RELEVANCE_ANCHOR_PATTERN = re.compile(
    r"(?:\bveffect\b|\bf6\b|\bf87\b|\bpi2?\b|\bniven\b|\bcpsi\b|"
    r"\bq(?:max|mean)?\b|\bcavit\w*\b|\bfrequenc\w*\b|\bspectr\w*\b|"
    r"\b(?:eigen)?modes?\b|\bbins?\b|\bpalindrom\w*\b|\bpairing\b|"
    r"\bcoupl\w*\b|\binteraction\b|\bgamma\b|\bdephas\w*\b|\btier\b|"
    r"\brich\w*\b|\bdivers\w*\b|\bvariety\b|\bgoldilocks\b|"
    r"\bsweet spot\b|\bsacrifice\b|\bphi\b|φ|\bgolden ratio\b|"
    r"\bcrystalli[sz]\w*\b|\bmass\b|\bwaves?\b|\bmirror\w*\b|\bfold\b|"
    r"\binformation\b|\bnoise\b|\btime\b|\bhierarch\w*\b|\batoms?\b|"
    r"\bmolecules?\b|\blife\b|\blevels?\b|\breson\w*\b|\bfabry perot\b|"
    r"\brecovered\b|\bmonoton\w*\b|\bextrem\w*\b|\binflection\b|"
    r"\bstationary point\b|\bselection bias\b|\bsystem size\b|"
    r"\b(?:winner|winning|wins|optimum|optimal|preferred|best)\b|"
    r"\b(?:special|exceptional\w*)\b|\b(?:112|109|104)\b|\b15\.5\b|"
    r"\b(?:14/36|11/4|8/4)\b|\bold/new\b|\bnew new\b|\bpauli\b|"
    r"\b(?:truly|soft|hard)\b|\babsorption\b|\besd\b|\bsoundbox\b|"
    r"\bmessage\b|\balgebra\b|\bmechanism\b|\bemergence\b|\bboundary\b|"
    r"\bstatus\b|\bverdict\b|\b(?:validated|confirmed|corroborated)\b|"
    r"\bsource\b|\borigin\b|\bstructure\b|\btransition\b|\bgeometry\b|"
    r"\b5 sites?\b)",
    re.I,
)


def _task7_normalize_bound_span(text):
    return re.sub(
        r"\s+", " ", text.replace("\r\n", "\n").replace("\r", "\n")
    ).strip()


def _task7_line_ranges(source):
    source = source.replace("\r\n", "\n").replace("\r", "\n")
    ranges = []
    offset = 0
    for raw in source.splitlines(keepends=True):
        body = raw[:-1] if raw.endswith("\n") else raw
        ranges.append((offset, offset + len(body), body))
        offset += len(raw)
    if not ranges and source == "":
        return source, []
    if source and not source.endswith("\n") and ranges[-1][1] != len(source):
        raise AssertionError("line range accounting drift")
    return source, ranges


def _task7_paragraph_ranges(source):
    source = source.replace("\r\n", "\n").replace("\r", "\n")
    ranges = []
    start = 0
    for boundary in re.finditer(r"\n[ \t]*\n+", source):
        if source[start:boundary.start()].strip():
            ranges.append((start, boundary.start(), source[start:boundary.start()]))
        start = boundary.end()
    if source[start:].strip():
        ranges.append((start, len(source), source[start:]))
    return source, ranges


def _task7_unique_span(matches, *, path, span_id, anchor):
    if len(matches) != 1:
        return None, (
            f"{span_id}\tBOUNDARY_ERROR:{path}:anchor={anchor!r}:count={len(matches)}"
        )
    return matches[0], None


def _task7_shared_fragment_spans(path, source):
    """Return ordered explicit Task-7 fragments with source offsets.

    Coverage is controlled solely by the path-local specs above.  No relevance
    selector participates in extraction, so deleting an anchor word from the
    lexical diagnostic cannot make an owned paragraph disappear.
    """
    normalized, lines = _task7_line_ranges(source)
    _, paragraphs = _task7_paragraph_ranges(normalized)
    spans = []
    for spec in TASK7_SHARED_FRAGMENT_SPECS[path]:
        kind, span_id, *args = spec
        error = None
        if kind == "line":
            anchor, = args
            match, error = _task7_unique_span(
                [row for row in lines if anchor in row[2]],
                path=path, span_id=span_id, anchor=anchor,
            )
            if match:
                start, end, _ = match
        elif kind == "paragraph":
            anchor, = args
            match, error = _task7_unique_span(
                [row for row in paragraphs if anchor in row[2]],
                path=path, span_id=span_id, anchor=anchor,
            )
            if match:
                start, end, _ = match
        elif kind == "heading":
            heading, = args
            match, error = _task7_unique_span(
                [(index, row) for index, row in enumerate(lines)
                 if row[2].strip() == heading],
                path=path, span_id=span_id, anchor=heading,
            )
            if match:
                index, (start, _, heading_line) = match
                level = len(re.match(r"^#+", heading_line.strip()).group())
                end = len(normalized)
                for next_start, _, next_line in lines[index + 1:]:
                    next_heading = re.match(r"^(#+)\s", next_line.strip())
                    if next_heading and len(next_heading.group(1)) <= level:
                        end = next_start
                        break
        elif kind in {"span", "python-claims-span"}:
            start_anchor, end_anchor = args
            start_match, start_error = _task7_unique_span(
                [row for row in lines if start_anchor in row[2]],
                path=path, span_id=span_id, anchor=start_anchor,
            )
            end_match, end_error = _task7_unique_span(
                [row for row in lines if end_anchor in row[2]],
                path=path, span_id=span_id, anchor=end_anchor,
            )
            error = start_error or end_error
            if start_match and end_match:
                start = start_match[0]
                end = end_match[0]
                if not start < end:
                    error = f"{span_id}\tBOUNDARY_ERROR:{path}:reversed"
        elif kind == "window":
            anchor, before, after = args
            match, error = _task7_unique_span(
                [(index, row) for index, row in enumerate(lines)
                 if anchor in row[2]],
                path=path, span_id=span_id, anchor=anchor,
            )
            if match:
                index, _ = match
                first = max(0, index - before)
                last = min(len(lines) - 1, index + after)
                start = lines[first][0]
                end = lines[last][1]
        else:
            raise AssertionError((path, spec))

        if error:
            spans.append((error, None, None, kind, span_id))
            continue
        if kind == "python-claims-span":
            body = "\n".join(_task7_python_claim_records(normalized[start:end]))
        else:
            body = _task7_normalize_bound_span(normalized[start:end])
        spans.append((f"{span_id}\t{body}", start, end, kind, span_id))
    return normalized, tuple(spans)


def _task7_python_claim_records(source):
    records = []
    claim_token_types = {
        tokenize.COMMENT,
        tokenize.STRING,
        getattr(tokenize, "FSTRING_MIDDLE", -1),
    }
    try:
        tokens = tokenize.generate_tokens(io.StringIO(source).readline)
        for token in tokens:
            if token.type not in claim_token_types:
                continue
            normalized = _task7_normalize_bound_span(token.string)
            if not normalized:
                continue
            records.append(
                f"{tokenize.tok_name[token.type]}\t"
                f"{normalized}"
            )
    except (tokenize.TokenError, IndentationError) as exc:
        records.append(f"TOKENIZE_ERROR\t{type(exc).__name__}:{exc}")
    return tuple(records)


def _task7_csharp_claim_records(source):
    records = []
    for raw in source.replace("\r\n", "\n").replace("\r", "\n").splitlines():
        if any(marker in raw for marker in ('"', "//", "/*", "*/")):
            records.append(f"CLAIM\t{_task7_normalize_bound_span(raw)}")
    return tuple(records)


def _task7_code_claim_records(path, source):
    if path.endswith(".py"):
        return _task7_python_claim_records(source)
    return _task7_csharp_claim_records(source)


def _task7_claim_record_payload(record):
    record_type, separator, payload = record.partition("\t")
    assert separator and record_type and payload, record
    return payload


def _task7_relevant_surface_records(path, source):
    """Return the ordered, path-bound Task-7 surface without lexical selection."""
    if path in TASK7_FULL_HOST_BOUND_PATHS:
        return (f"FULL\t{_task7_normalize_bound_span(source)}",)
    if path in TASK7_WRAPPER_BOUND_PATHS:
        current = _task7_current_surface(path, source)
        return (f"CURRENT_WRAPPER\t{_task7_normalize_bound_span(current)}",)
    if path in TASK7_CODE_CLAIM_BOUND_PATHS:
        return _task7_code_claim_records(path, source)
    if path in TASK7_SHARED_FRAGMENT_SPECS:
        _, spans = _task7_shared_fragment_spans(path, source)
        return tuple(record for record, _, _, _, _ in spans)
    return (f"UNCLASSIFIED\t{path}",)


def _task7_relevant_surface_signature(path, source):
    records = _task7_relevant_surface_records(path, source)
    payload = "\n\x1e\n".join(records).encode("utf-8")
    return len(records), hashlib.sha256(payload).hexdigest().upper()


def _task7_insert_into_shared_fragment(path, source, payload, span_id=None):
    normalized, spans = _task7_shared_fragment_spans(path, source)
    candidates = [
        span for span in spans
        if span[1] is not None and (span_id is None or span[4] == span_id)
    ]
    assert candidates, (path, span_id, spans)
    _, start, end, kind, _ = candidates[0]
    if kind in {"line", "window"}:
        newline = normalized.find("\n", start, end + 1)
        insert_at = end if newline < 0 else min(newline, end)
        return normalized[:insert_at] + "  " + payload + normalized[insert_at:]
    if kind == "paragraph":
        insert_at = end
        while insert_at > start and normalized[insert_at - 1] == "\n":
            insert_at -= 1
        return normalized[:insert_at] + "\n" + payload + normalized[insert_at:]
    first_newline = normalized.find("\n", start, end)
    assert first_newline >= 0, (path, kind, start, end)
    return (
        normalized[:first_newline + 1]
        + payload + "\n"
        + normalized[first_newline + 1:]
    )


