def _task7_approved_surface_findings(path, source):
    if path in TASK7_SHARED_FRAGMENT_SPECS:
        normalized, spans = _task7_shared_fragment_spans(path, source)
        boundary_errors = [
            record for record, start, _, _, _ in spans if start is None
        ]
        if boundary_errors:
            # A missing/duplicated/reversed owner boundary is an unconditional
            # structural failure.  An edited approval digest cannot license it.
            return [
                f"{path}:RELEVANT_SURFACE_{record}"
                for record in boundary_errors
            ]

        positive_findings = []
        required = TASK7_REQUIRED_SHARED_FRAGMENT_POSITIVES[path]
        for _, start, end, _, span_id in spans:
            body = _task7_normalize_bound_span(normalized[start:end])
            for positive in required[span_id]:
                if positive not in body:
                    positive_findings.append(
                        f"{path}:MISSING_POSITIVE_OBJECT:{span_id}:{positive}"
                    )
    else:
        positive_findings = []

    expected = TASK7_APPROVED_RELEVANT_SURFACE.get(path)
    actual = _task7_relevant_surface_signature(path, source)
    if expected is None:
        return positive_findings + [f"{path}:RELEVANT_SURFACE_UNAPPROVED"]
    if actual != expected:
        return positive_findings + [
            f"{path}:RELEVANT_SURFACE_DRIFT:count={actual[0]}:sha256={actual[1]}"
        ]
    return positive_findings


TASK7_BROAD_SEMANTIC_SCAN_RANGES = {
    # The shared-fragment records above still delimit their original owner
    # slices.  Independently, the fallback contract below freezes every
    # physical line from this H1 through the Tier boundary, up to but not
    # including §15; semantic predicates remain explanatory.
    "hypotheses/THE_OTHER_SIDE.md": (
        "# The Other Side of the Mirror: Z₂ Parity, the Two Sectors, and What Emerges Between Them",
        "## 15. The Same Language",
    ),
    # This living story host is likewise frozen from its current-reading H1
    # through EOF by the complete canonical carrier stream below.  Questions,
    # debt, headings, tables, quotations, footnotes and neutral prose stay in
    # the story, but any future content edit requires explicit review and repin.
    "hypotheses/RESONANCE_NOT_CHANNEL.md": (
        "# Finite resonance diagnostics beside the soundbox picture",
        None,
    ),
}

def _task7_broad_semantic_scan_surface(path, source):
    spec = TASK7_BROAD_SEMANTIC_SCAN_RANGES.get(path)
    if spec is None:
        return None, ()
    normalized = source.replace("\r\n", "\n").replace("\r", "\n")
    lines = normalized.split("\n")
    start_anchor, end_anchor = spec
    start_count = lines.count(start_anchor)
    if start_count != 1:
        return "", (
            f"{path}:SEMANTIC_SCAN_BOUNDARY:start:{start_count}",
        )
    start = lines.index(start_anchor)
    if end_anchor is None:
        return "\n".join(lines[start:]), ()
    end_count = lines.count(end_anchor)
    if end_count != 1:
        return "", (
            f"{path}:SEMANTIC_SCAN_BOUNDARY:end:{end_count}",
        )
    end = lines.index(end_anchor)
    if end <= start:
        return "", (f"{path}:SEMANTIC_SCAN_BOUNDARY:reversed",)
    return "\n".join(lines[start:end]), ()


def _task7_broad_clause_units(text):
    """Split one Markdown assertion carrier into clause-local semantic units."""
    paragraph = _task7_semantic_canonical(text)
    if not paragraph:
        return ()
    # A Markdown table row is not one sentence.  Each cell is an independent
    # assertion carrier, so debt in a neighbouring cell cannot qualify a claim.
    # CommonMark permits both outer pipes to be omitted independently; split on
    # every unescaped pipe and discard only empty outer cells.
    table_row = paragraph
    table_row = re.sub(r"^\|\s+", "", table_row)
    table_row = re.sub(r"\s+\|$", "", table_row)
    table_parts = re.split(r"(?<!\\)\s+\|\s+", table_row)
    if len(table_parts) > 1:
        cells = tuple(
            cell.strip() for cell in table_parts
            if cell.strip() and not re.fullmatch(r":?-{3,}:?", cell.strip())
        )
        if len(cells) >= 2:
            return tuple(
                unit
                for cell in cells
                for unit in _task7_broad_clause_units(cell)
            )
    pieces = []
    start = 0
    # A decimal point is followed by a digit and therefore cannot match this
    # boundary.  Do not suppress a real full stop merely because the preceding
    # token ends in a number (for example, ``8/4. Both ...``).  Markdown closing
    # emphasis belongs to the sentence on its left.
    for boundary in re.finditer(
        r";|…|(?:[!?]|[.])(?:[*_`]+)?(?:[\"'”’\)\]]+)?"
        r"(?:\[(?:\^)?[A-Za-z0-9_.:-]+\])?(?=\s|$)",
        paragraph,
    ):
        if not _task7_boundary_is_top_level(paragraph, boundary.start()):
            continue
        # Initialisms such as ``e.g.`` and ``i.e.`` are not sentence ends.
        if (
            boundary.group().startswith(".")
            and re.search(
                r"(?:\b[a-z]\.)+[a-z]$",
                paragraph[:boundary.start()],
                re.I,
            )
        ):
            continue
        # ``F6. V-Effect ...`` is a registry-label prefix, not a completed
        # sentence.  Keep the label and title in the same semantic unit.
        if (
            boundary.group().startswith(".")
            and boundary.end() < len(paragraph)
            and re.search(r"\bf\d+$", paragraph[:boundary.start()], re.I)
        ):
            continue
        piece = paragraph[start:boundary.start()].strip()
        if boundary.group().startswith("?"):
            piece += "?"
        if piece:
            pieces.append(piece)
        start = boundary.end()
    tail = paragraph[start:].strip()
    if tail:
        pieces.append(tail)

    units = []
    for piece in pieces:
        units.extend(_task7_relation_scope_units(piece))
    return tuple(units)


