def _task7_decode_canonical_carriers(encoded_chunks):
    payload = zlib.decompress(base64.b64decode("".join(encoded_chunks)))
    decoded = json.loads(payload.decode("utf-8"))
    if not isinstance(decoded, list) or not all(
        isinstance(item, str) and item for item in decoded
    ):
        raise AssertionError("invalid Task-7 canonical carrier fixture")
    return tuple(decoded)


def _task7_decode_canonical_layout(encoded_chunks):
    payload = zlib.decompress(base64.b64decode("".join(encoded_chunks)))
    decoded = json.loads(payload.decode("utf-8"))
    if not isinstance(decoded, list) or not all(
        isinstance(record, list)
        and len(record) in (1, 2)
        and all(isinstance(item, str) for item in record)
        for record in decoded
    ):
        raise AssertionError("invalid Task-7 canonical carrier layout fixture")
    return tuple(tuple(record) for record in decoded)


def _task7_apply_canonical_layout(contents, layout):
    content_iter = iter(contents)
    carriers = []
    for record in layout:
        if len(record) == 1:
            carriers.append(record[0])
        else:
            prefix, suffix = record
            try:
                content = next(content_iter)
            except StopIteration as exc:
                raise AssertionError("Task-7 carrier layout exceeds content") from exc
            carriers.append(prefix + content + suffix)
    try:
        next(content_iter)
    except StopIteration:
        return tuple(carriers)
    raise AssertionError("Task-7 carrier content exceeds layout")


TASK7_BROAD_RANGE_CANONICAL_CARRIERS = {
    path: _task7_apply_canonical_layout(
        _task7_decode_canonical_carriers(encoded),
        _task7_decode_canonical_layout(TASK7_BROAD_RANGE_CANONICAL_LAYOUT_B64[path]),
    )
    for path, encoded in TASK7_BROAD_RANGE_CANONICAL_CARRIERS_B64.items()
}


def _task7_canonical_carrier_digest(carriers):
    payload = "\x1e".join(carriers).encode("utf-8")
    return hashlib.sha256(payload).hexdigest().upper()


def _task7_broad_range_canonical_carriers(path, source):
    surface, boundary_findings = _task7_broad_semantic_scan_surface(path, source)
    if surface is None:
        return None, ()
    if boundary_findings:
        return (), boundary_findings
    lines = surface.split("\n")
    if path == "hypotheses/RESONANCE_NOT_CHANNEL.md":
        # Task 8 restores the QUARTER scanner to CURRENT before the original
        # story body.  This exact structural mode switch is owned and mutated
        # by the quarter-region gate; it is not a content-bearing Task-7 story
        # carrier and must not force a 632-line prose fixture repin.
        lines = [line for line in lines if line.strip() != "<!-- QUARTER-CURRENT -->"]
    carriers = tuple(lines)
    return carriers, ()


def _task7_encode_fixture_payload(value):
    payload = json.dumps(
        value, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    encoded = base64.b64encode(zlib.compress(payload, 9)).decode("ascii")
    return tuple(encoded[index:index + 96] for index in range(0, len(encoded), 96))


def _task7_review_only_canonical_carrier_proposal(path, source):
    """Return a review proposal; never install or learn it at gate runtime.

    Maintainer command (prints a proposed static fixture only):
      python simulations/tests/test_old_document_label_scope.py \
        --emit-task7-broad-carriers

    A legitimate edit still requires review plus an explicit update of both
    checked-in literal maps and metadata below.
    """
    carriers, boundary_findings = _task7_broad_range_canonical_carriers(path, source)
    if boundary_findings:
        raise ValueError(";".join(boundary_findings))
    contents = []
    layout = []
    for line in carriers:
        stripped = line.strip()
        if not stripped:
            layout.append([line])
            continue
        prefix = line[:len(line) - len(line.lstrip())]
        suffix = line[len(line.rstrip()):]
        contents.append(stripped)
        layout.append([prefix, suffix])
    return {
        "carriers": carriers,
        "content_encoded_chunks": _task7_encode_fixture_payload(contents),
        "layout_encoded_chunks": _task7_encode_fixture_payload(layout),
        "meta": (len(carriers), _task7_canonical_carrier_digest(carriers)),
    }


def _task7_emit_review_only_canonical_carrier_proposals():
    """Print deterministic literals for review; never modify repository files."""
    import pprint

    proposals = {
        path: _task7_review_only_canonical_carrier_proposal(path, read_host(path))
        for path in TASK7_BROAD_SEMANTIC_SCAN_RANGES
    }
    for label, key in (
        ("TASK7_BROAD_RANGE_CANONICAL_CARRIERS_B64", "content_encoded_chunks"),
        ("TASK7_BROAD_RANGE_CANONICAL_LAYOUT_B64", "layout_encoded_chunks"),
        ("TASK7_BROAD_RANGE_CANONICAL_CARRIER_META", "meta"),
    ):
        print(f"{label} = " + pprint.pformat(
            {path: proposal[key] for path, proposal in proposals.items()},
            sort_dicts=True,
            width=100,
        ))


def _task7_broad_range_canonical_carrier_findings(path, source):
    fixture_keys = set(TASK7_BROAD_SEMANTIC_SCAN_RANGES)
    if not (
        set(TASK7_BROAD_RANGE_CANONICAL_CARRIERS_B64)
        == set(TASK7_BROAD_RANGE_CANONICAL_LAYOUT_B64)
        == set(TASK7_BROAD_RANGE_CANONICAL_CARRIERS)
        == set(TASK7_BROAD_RANGE_CANONICAL_CARRIER_META)
        == fixture_keys
    ):
        if path in fixture_keys:
            return [f"{path}:BROAD_RANGE_CANONICAL_CARRIER:FIXTURE"]
    expected = TASK7_BROAD_RANGE_CANONICAL_CARRIERS.get(path)
    if expected is None:
        return (
            [f"{path}:BROAD_RANGE_CANONICAL_CARRIER:FIXTURE"]
            if path in fixture_keys else []
        )
    expected_meta = TASK7_BROAD_RANGE_CANONICAL_CARRIER_META[path]
    if (len(expected), _task7_canonical_carrier_digest(expected)) != expected_meta:
        return [f"{path}:BROAD_RANGE_CANONICAL_CARRIER:FIXTURE"]
    actual, boundary_findings = _task7_broad_range_canonical_carriers(path, source)
    if boundary_findings:
        return list(boundary_findings)
    if actual != expected:
        return [f"{path}:BROAD_RANGE_CANONICAL_CARRIER:DRIFT"]
    return []


def _task7_broad_range_structure_findings(path, source):
    """Stable call surface for the now-canonical broad-range contract."""
    return _task7_broad_range_canonical_carrier_findings(path, source)


# Kept only for relation-local semantic diagnostics below.  These qualifiers no
# longer grant an edit exemption in either canonical broad range.
TASK7_GENERIC_QUALIFIER_PATTERNS = (
    r"\b(?:might|could|perhaps|possibly)\b|\bmay\s+(?=[a-z])",
    r"\b(?:asks?|invites?|wonders?|explores?)\b.{0,100}\b(?:whether|if)\b",
    r"\b(?:question|issue|status)\s+(?:is\s+)?(?:open|unresolved|unknown)\b",
    r"\b(?:remains?|stays?)\s+(?:an?\s+)?open\b",
    r"\b(?:interpretive invitation|not a result|not derived|not proved|"
    r"not proven|no derived mechanism)\b",
)


def _task7_generic_qualifier_present(unit):
    qualifier_surface = re.sub(
        r"\b(?:in|during|from|since)\s+(?:the\s+)?may\b",
        " ",
        unit,
        flags=re.I,
    )
    return any(
        re.search(pattern, qualifier_surface, re.I)
        for pattern in TASK7_GENERIC_QUALIFIER_PATTERNS
    )


def _task7_semantic_units(path, source):
    broad_current, _ = _task7_broad_semantic_scan_surface(path, source)
    if broad_current is not None:
        current = broad_current
    elif path in TASK7_SHARED_FRAGMENT_SPECS:
        normalized, spans = _task7_shared_fragment_spans(path, source)
        current = "\n\n".join(
            normalized[start:end]
            for _, start, end, _, _ in spans
            if start is not None
        )
    else:
        current = _task7_current_surface(path, source)
    units = []
    for raw_paragraph in re.split(r"\n\s*\n", current.replace("\r\n", "\n")):
        paragraph = _task7_semantic_canonical(raw_paragraph)
        if not paragraph:
            continue
        units.extend(_task7_broad_clause_units(paragraph))
    return tuple(units)


def _task7_semantic_relation_qualified(unit, *, allow_question):
    original = unit.strip()
    if allow_question and original.endswith("?"):
        return True
    # Only epistemic/direct relation denials qualify.  Free-standing tails such
    # as "not noise", "not yet a theorem" or "not uniformity" deliberately do
    # not occur in this list and therefore cannot erase an asserted arrow.
    qualification = (
        r"\b(?:does|do|did|can|could|would|is|are|was|were|has|have|had)\s+not\s+"
        r"(?:establish|show|prove|derive|demonstrate|imply|support|isolate|confirm|verify|"
        r"determine|predict|identify|select|mean|attribute)\w*\b",
        r"\b(?:not evidence|insufficient|unestablished|not established|not derived|"
        r"not confirmed|not verified|open question|historical alias)\b",
        r"\b(?:is|are)\s+not\s+(?:yet\s+)?sufficient\s+to\s+"
        r"(?:predict|determine|establish|show|prove|derive|confirm|verify)\w*\b",
        r"\b(?:does|do|did)\s+not(?:\s+by\s+itself|\s+directly)?\s+"
        r"(?:create|cause|produce|yield|release|generate|render|make|force)\w*\b",
        r"\b(?:is|are|was|were)\s+not\s+(?:the\s+)?same\b",
        r"\b(?:is|are|was|were)\s+not\s+(?:thereby\s+)?(?:an?\s+)?"
        r"(?:irrevers\w+|crystalli[sz]\w+|physical\s+mirror|literal\s+resonator)\b",
        r"\bnot\s+c\s*\(\s*6\s*,\s*2\s*\)",
        r"\bno\s+(?:unique\s+)?(?:peak|maximum|optimum)\b",
        r"\bcannot be (?:attributed|identified|isolated|derived|established)\b",
        r"\bneither\b.{0,80}\b(?:shows?|establishes?|proves?|derives?|demonstrates?|"
        r"implies?|supports?|licenses?)\s+that\b",
        r"\bneither\b.{0,80}\blicenses?\b",
        r"\bno\b.{0,60}\b(?:shows?|establishes?|proves?|derives?|demonstrates?|"
        r"implies?|supports?|licenses?)\s+that\b",
        r"\b(?:ask\w*|invit\w*)\b.{0,100}\bwhether\b",
    )
    if any(re.search(pattern, original, re.I) for pattern in qualification):
        return True
    tested_image = re.search(
        r"\b(?:phrase|label|reading)\s+(?:is|are|remains?|stays?)\s+"
        r"(?:an?\s+)?(?:tested\s+)?(?:image(?:/question)?|question|analogy)\b",
        original,
        re.I,
    )
    if tested_image is None:
        return False
    # The label applies to this unit only.  It cannot launder a neighbouring
    # asserted proposition introduced later in the same carrier.
    tail = original[tested_image.end():]
    return not re.search(
        r"\b(?:claim|assert|state|say|declare)\w*\s+that\b",
        tail,
        re.I,
    )


def _task7_any_broad_qualification(unit):
    return (
        _task7_semantic_relation_qualified(unit, allow_question=True)
        or _task7_generic_qualifier_present(unit)
    )


def _task7_qualified_bracket_split(piece):
    """Split a qualified parenthetical/bracket from its surrounding claim."""
    pairs = {"(": ")", "[": "]"}
    closing = set(pairs.values())
    stack = []
    outer_start = None
    spans = []
    for index, char in enumerate(piece):
        if char in pairs:
            if not stack:
                outer_start = index
            stack.append(pairs[char])
        elif char in closing and stack and char == stack[-1]:
            stack.pop()
            if not stack and outer_start is not None:
                spans.append((outer_start, index + 1))
                outer_start = None
    for start, end in spans:
        inside = piece[start + 1:end - 1].strip()
        if not inside or not _task7_any_broad_qualification(inside):
            continue
        outside = (piece[:start] + " " + piece[end:]).strip()
        if not outside:
            continue
        return (
            *_task7_relation_scope_units(outside),
            *_task7_relation_scope_units(inside),
        )
    return None


def _task7_boundary_is_top_level(piece, offset):
    """Return whether ``offset`` is outside parameter/list delimiters.

    Clause punctuation inside ``(N, J)`` or a bracketed aside is not a
    syntactic boundary of the surrounding assertion.  Bracket contents remain
    part of the carrier and are still scanned; this helper only prevents their
    punctuation from tearing the carrier into artificial clauses.
    """
    pairs = {"(": ")", "[": "]", "{": "}"}
    closers = set(pairs.values())
    stack = []
    escaped = False
    for char in piece[:offset]:
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if char in pairs:
            stack.append(pairs[char])
        elif char in closers and stack and char == stack[-1]:
            stack.pop()
    return not stack


def _task7_relation_scope_units(piece):
    """Split a compound only where one syntactic side owns a qualification.

    A denial is not a licence for a second relation later in the sentence.  We
    therefore split adversative/coordinating clauses, qualifying subordinate
    clauses, dash joins, and qualifying parentheticals before asking whether a
    unit is epistemically fenced.  Ordinary conjunctions remain untouched when
    neither side contains a relation-bound qualifier.
    """
    piece = piece.strip()
    if not piece:
        return ()
    # These are already independently bound, approved structural labels.  Their
    # banner/debt scope applies to the labelled block; parsing an English clause
    # boundary through the Markdown syntax would manufacture assertions from
    # the label itself.
    if piece.startswith(("#", "<!--", "**interpretive invitation")) or re.match(
        r"^\*\*what remains open:\*\*", piece, re.I
    ):
        return (piece,)

    bracket_split = _task7_qualified_bracket_split(piece)
    if bracket_split is not None:
        return bracket_split

    initial = re.match(
        r"^((?:even\s+)?though|although|while|whereas|because)\s+(.+?),\s+(.+)$",
        piece,
        re.I,
    )
    if initial:
        qualifier = f"{initial.group(1)} {initial.group(2)}".strip()
        assertion = initial.group(3).strip()
        if _task7_any_broad_qualification(qualifier):
            return (
                *_task7_relation_scope_units(qualifier),
                *_task7_relation_scope_units(assertion),
            )

    boundaries = (
        (r"\s+(?:[\u2014\u2013]|--)\s+", "dash"),
        (r"\s*,?\s+\b(?:but|yet|however|nevertheless)\b\s+", "adversative"),
        (
            r"\s*,?\s+\b(?:(?:even\s+)?though|whereas|although|while|because)\b\s+",
            "subordinate",
        ),
        (r"\s*,\s+with\s+", "with"),
        (r"\s*,?\s+\band\b\s+", "and"),
        (r",\s+", "comma"),
    )
    for pattern, boundary_kind in boundaries:
        for match in re.finditer(pattern, piece, re.I):
            if not _task7_boundary_is_top_level(piece, match.start()):
                continue
            left = piece[:match.start()].strip(" ,")
            right = piece[match.end():].strip(" ,")
            if not left or not right:
                continue
            left_relation_qualified = _task7_semantic_relation_qualified(
                left, allow_question=True
            )
            right_relation_qualified = _task7_semantic_relation_qualified(
                right, allow_question=True
            )
            left_generic_qualified = _task7_generic_qualifier_present(left)
            right_generic_qualified = _task7_generic_qualifier_present(right)
            left_qualified = left_relation_qualified or left_generic_qualified
            right_qualified = right_relation_qualified or right_generic_qualified
            comma_boundary = "," in match.group()
            should_split = left_qualified or right_qualified
            if boundary_kind == "dash":
                should_split = (
                    left_qualified != right_qualified
                    and not _task7_boundary_keeps_qualifier_scope(left, right)
                )
            if boundary_kind == "and":
                should_split = (
                    left_relation_qualified
                    and _task7_qualifier_scope_is_complete(left)
                ) or (
                    right_relation_qualified and _task7_has_assertive_relation(left)
                ) or (
                    right_generic_qualified and not left_qualified
                ) or (
                    comma_boundary
                    and (left_generic_qualified or right_generic_qualified)
                )
                if _task7_and_stays_inside_qualifier_scope(left, right):
                    should_split = False
            elif boundary_kind == "subordinate":
                # A trailing epistemic subordinate cannot qualify the complete
                # main clause that precedes it (``claim, although open`` or
                # ``claim because this is not a result``).  Conversely, an
                # entirely qualified main clause followed by an unqualified
                # subordinate must not lend that qualification downstream.
                # This is a syntactic scope boundary, not a vocabulary test on
                # the main clause's verb.
                should_split = left_qualified != right_qualified
            elif boundary_kind in ("with", "comma"):
                # A comma-delimited clause does not inherit a qualification
                # merely because the other side names an open question.  The
                # introducer exception below is reserved for colon/dash forms
                # such as ``the question is: ...?`` where punctuation really
                # does bind the complement.
                should_split = (
                    left_qualified != right_qualified
                    and not (
                        boundary_kind == "comma"
                        and _task7_comma_stays_inside_qualifier_scope(left)
                    )
                )
            if should_split:
                return (
                    *_task7_relation_scope_units(left),
                    *_task7_relation_scope_units(right),
                )

    colon = piece.find(": ")
    if colon >= 0:
        left = piece[:colon].strip()
        right = piece[colon + 2:].strip()
        left_qualified = _task7_any_broad_qualification(left)
        right_qualified = _task7_any_broad_qualification(right)
        if (
            left
            and right
            and left_qualified != right_qualified
            and not _task7_boundary_keeps_qualifier_scope(left, right)
        ):
            return (
                *_task7_relation_scope_units(left),
                *_task7_relation_scope_units(right),
            )
    return (piece,)


def _task7_boundary_keeps_qualifier_scope(left, right):
    """Recognize a real question/denial introducer, not a trailing escape.

    A colon or dash can introduce the content of a question or of an explicitly
    denied proposition.  In those cases the right side is not an independent
    assertion.  Conversely, a complete assertion on the left cannot borrow a
    generic ``may/open/not-a-result`` debt clause on the right.
    """
    # An answered/resolved question is a declarative result claim, not open
    # debt that can qualify the complement after a colon or dash.
    if re.search(
        r"\b(?:question|issue|status)\b.{0,40}"
        r"\b(?:answer|resolv|clos|settl)\w*\b",
        left,
        re.I,
    ):
        return False
    if right.rstrip().endswith("?") and re.search(
        r"\b(?:ask\w*|question|invit\w*|wonder\w*|explor\w*)\b",
        left,
        re.I,
    ):
        return True
    if _task7_semantic_relation_qualified(left, allow_question=True) and re.search(
        r"\b(?:this|that|the)\s+"
        r"(?:mechanism|claim|proposition|hypothesis|statement|reading|idea|following)"
        r"\s*$",
        left,
        re.I,
    ):
        return True
    if _task7_any_broad_qualification(left) and re.search(
        r"\b(?:means?|asks?|question|invit\w*|wonder\w*|explor\w*|"
        r"tested?\s+whether)\b[^:]*$",
        left,
        re.I,
    ):
        return True
    return False


def _task7_comma_stays_inside_qualifier_scope(left):
    """Keep a comma list inside one denied/questioned complement.

    In ``does not prove that A, B, or C`` the epistemic operator scopes the
    complete complement list.  A comma alone must not turn B or C back into an
    assertion.  This is intentionally limited to an already relation-qualified
    complement introduced by ``that/whether/if``; generic nearby debt such as
    ``the status is open, claim`` still splits.
    """
    return _task7_has_qualified_complement_introducer(left)


def _task7_has_qualified_complement_introducer(fragment):
    """Recognize a grammatical epistemic complement, not demonstrative *that*.

    ``does not establish that X`` scopes X.  ``does not establish a mechanism
    in that row`` does not: its *that* modifies *row* and cannot license a later
    assertion.  Binding the complementizer directly to the epistemic verb keeps
    this distinction independent of the claim vocabulary.
    """
    return bool(
        _task7_semantic_relation_qualified(fragment, allow_question=True)
        and re.search(
            r"\b(?:establish|show|prove|derive|demonstrate|imply|support|"
            r"confirm|verify|mean|suggest)\w*\s+"
            r"(?:that|whether|if)\b",
            fragment,
            re.I,
        )
    )


def _task7_and_stays_inside_qualifier_scope(left, right):
    """Keep coordinated predicates under one explicit epistemic operator."""
    if _task7_has_qualified_complement_introducer(left):
        return True
    if re.match(r"^(?:that|whether|if)\b", right, re.I):
        return True
    if (
        re.search(r"\b(?:whether|if)\b", left, re.I)
        and _task7_any_broad_qualification(left)
    ):
        return True
    if (
        re.search(r"\b(?:may|might|could)\b", left, re.I)
        and re.match(
            r"^(?:ask|explore|invite|suggest|support|show|indicate|compare|"
            r"retain|remain|vary|move|change)\w*\b",
            right,
            re.I,
        )
    ):
        return True
    return False


def _task7_qualifier_scope_is_complete(fragment):
    """Reject a split inside a denied complement's compound subject."""
    complement = re.search(
        r"\b(?:establish|show|prove|derive|demonstrate|imply|support|confirm|"
        r"verify|mean)\w*\s+that\s+(.+)$",
        fragment,
        re.I,
    )
    if complement is None:
        return True
    return bool(re.search(
        r"\b(?:is|are|was|were|has|have|does|do|did|can|could|would|will|"
        r"create\w*|cause\w*|produce\w*|yield\w*|raise\w*|engender\w*|"
        r"beget\w*|become\w*|remain\w*)\b",
        complement.group(1),
        re.I,
    ))


def _task7_has_assertive_relation(fragment):
    """Identify a declarative causal/identity relation before a trailing fence."""
    return bool(re.search(
        r"\b(?:create\w*|cause\w*|produce\w*|yield\w*|release\w*|raise\w*|"
        r"engender\w*|beget\w*|spawn\w*|generate\w*|constitute\w*|"
        r"identical|same|persist\w*|surviv\w*|preserv\w*|derive\w*)\b",
        fragment,
        re.I,
    ))


def _task7_semantic_concept_findings(path, source):
    _, boundary_findings = _task7_broad_semantic_scan_surface(path, source)
    findings = list(boundary_findings)
    if not boundary_findings:
        findings.extend(_task7_broad_range_structure_findings(path, source))
    seen = set()
    for unit in _task7_semantic_units(path, source):
        for family, groups, allow_question in TASK7_SEMANTIC_CONCEPT_RULES.get(path, ()):
            if family in seen or not all(re.search(group, unit, re.I) for group in groups):
                continue
            if _task7_semantic_relation_qualified(unit, allow_question=allow_question):
                continue
            seen.add(family)
            findings.append(f"{path}:TASK7_SEMANTIC_REPROMOTION:{family}")
    return findings


def _task7_semantic_root_findings(path, source):
    current = _task7_current_surface(path, source)
    findings = []
    for family, pattern in TASK7_SEMANTIC_ROOT_RULES.get(path, ()):
        if re.search(pattern, current, re.I | re.S):
            findings.append(f"{path}:TASK7_SEMANTIC_REPROMOTION:{family}")
    findings.extend(
        finding for finding in _task7_semantic_concept_findings(path, source)
        if finding not in findings
    )
    return findings


def task7_experiment_index_findings(source):
    findings = []
    row = _task7_markdown_row(source, "[V-Effect](V_EFFECT_PALINDROME.md)")
    required = (
        "finite broken/control census", "14/36", "four-decimal", "11/4",
        "three-decimal", "8/4", "simultaneous Hamiltonian and dephasing-profile changes",
        "prevent attributing the extra bins to palindrome failure",
    )
    for fragment in required:
        if fragment.lower() not in row.lower():
            findings.append(f"experiments/README.md:V_EFFECT_ROW:{fragment}")
    for sentence in re.split(r"(?<=[.;])\s+", row):
        if re.search(
            r"(?:pairing failure|palindrome (?:failure|break(?:s|ing)?)).{0,80}"
            r"(?:releases?|creates?|causes?|produces?|yields?).{0,60}"
            r"(?:bins?|frequenc(?:y|ies))",
            sentence, re.I,
        ) and not re.search(r"(?:cannot|does not|not)\b.{0,80}\battribut", sentence, re.I):
            findings.append("experiments/README.md:V_EFFECT_ROW:CAUSAL_ATTRIBUTION")

    n5 = _task7_markdown_row(source, "[N=5 Optimal Cavity Size](N5_OPTIMAL_CAVITY_SIZE.md)")
    for fragment in (
        "tested image/question", "N=(3,4,5)", "omega_2/omega_1=2+phi",
        "F6 Q-edge gain=1+phi/2", "does not select a global N-optimum",
    ):
        if fragment.lower() not in n5.lower():
            findings.append(f"experiments/README.md:N5_ROW:{fragment}")
    if re.search(r"\bN=5 is (?:the )?Goldilocks\b", n5, re.I):
        findings.append("experiments/README.md:N5_ROW:GOLDILOCKS_ASSERTION")
    return findings


def task7_glossary_owner_findings(source):
    row = _task7_markdown_row(source, "**V-Effect**")
    findings = []
    for fragment in ("14/36", "four-decimal", "11/4", "three-decimal", "8/4"):
        if fragment.lower() not in row.lower():
            findings.append(f"docs/GLOSSARY.md:V_EFFECT_OWNER_ROW:{fragment}")
    if not re.search(r"four-decimal.{0,80}11/4", row, re.I):
        findings.append("docs/GLOSSARY.md:V_EFFECT_OWNER_ROW:FINE_TUPLE")
    if not re.search(r"three-decimal.{0,80}8/4", row, re.I):
        findings.append("docs/GLOSSARY.md:V_EFFECT_OWNER_ROW:COARSE_TUPLE")
    return findings


def task7_palindrome_block_residual_findings(source):
    path = "experiments/V_EFFECT_PALINDROME.md"
    residuals = {}
    for line in source.replace("\r\n", "\n").splitlines():
        if not line.lstrip().startswith("|"):
            continue
        cells = tuple(cell.strip() for cell in line.strip().strip("|").split("|"))
        if len(cells) != 3 or not re.fullmatch(r"[0-3]", cells[0]):
            continue
        try:
            residuals[int(cells[0])] = float(cells[2])
        except ValueError:
            continue
    findings = []
    if set(residuals) != {0, 1, 2, 3}:
        findings.append(f"{path}:RESIDUAL_BLOCK_TABLE")
    elif not (
        residuals[0] == residuals[3] == 0.0
        and residuals[1] > 0.0
        and residuals[2] > 0.0
    ):
        findings.append(f"{path}:RESIDUAL_BLOCK_TABLE")
    normalized = _task7_normalize_paragraph(source).lower()
    if (
        "the interior blocks carry the nonzero operator residual" not in normalized
        or "the two extreme blocks do not" not in normalized
        or "boundary blocks carry the nonzero operator residual" in normalized
        or "the nonzero interior-block residual" not in normalized
        or "the nonzero boundary residual" in normalized
    ):
        findings.append(f"{path}:RESIDUAL_BLOCK_LABEL")
    return findings


def task7_precision_local_findings(path, source):
    if path not in TASK7_PRECISION_HOSTS:
        return []
    findings = []
    for sentence in _task7_semantic_units(path, source):
        direct = re.search(r"\b4\s+to\s+11\b", sentence)
        word_relation = (
            re.search(r"\b4\b", sentence)
            and re.search(r"\b11\b", sentence)
            and re.search(r"\bfrequenc(?:y|ies)\b", sentence)
            and re.search(
                r"\b(?:send\w*|turn\w*|tak\w*|becom\w*|creat\w*|"
                r"produc\w*|yield\w*|map\w*|encod\w*)\b",
                sentence,
            )
        )
        if ((direct or word_relation)
                and not re.search(
                    r"four\s+decimal|three\s+decimal|at (?:three|four) decimals",
                    sentence, re.I,
                )
                and not sentence.rstrip().endswith("?")):
            findings.append(f"{path}:PRECISION_LOCAL:UNQUALIFIED_4_TO_11")
            break
    if path == "docs/GLOSSARY.md":
        row = _task7_markdown_row(source, "**V-Effect**")
        if "14/36" not in row:
            findings.append(f"{path}:PRECISION_LOCAL:SCOPE_14_OF_36")
        return findings
    paragraphs = re.split(
        r"\n\s*\n", source.replace("\r\n", "\n").replace("\r", "\n")
    )
    owners = [paragraph for paragraph in paragraphs
              if "precision fence:" in paragraph.lower()]
    if not owners:
        owners = [
            paragraph for paragraph in paragraphs
            if all(token in paragraph.lower() for token in (
                "four-decimal", "11/4", "three-decimal", "8/4",
            ))
        ]
    if len(owners) != 1:
        return [f"{path}:PRECISION_LOCAL:OWNER_COUNT:{len(owners)}"]
    owner = _task7_normalize_paragraph(owners[0])
    if "14/36" not in owner:
        findings.append(f"{path}:PRECISION_LOCAL:SCOPE_14_OF_36")
    if not re.search(r"four-decimal.{0,100}\b11/4\b", owner, re.I):
        findings.append(f"{path}:PRECISION_LOCAL:FINE_11_OVER_4")
    if not re.search(r"three-decimal.{0,100}\b8/4\b", owner, re.I):
        findings.append(f"{path}:PRECISION_LOCAL:COARSE_8_OVER_4")
    return findings


