def _task7_import_module(path):
    source = read_host(path)
    tree = ast.parse(source)
    guarded = any(
        isinstance(node, ast.If)
        and isinstance(node.test, ast.Compare)
        and isinstance(node.test.left, ast.Name)
        and node.test.left.id == "__name__"
        for node in tree.body
    )
    assert guarded, f"{path} has no main guard; RED must not execute it"
    stream = io.StringIO()
    old_stdout, old_stderr = sys.stdout, sys.stderr
    try:
        sys.stdout = stream
        sys.stderr = stream
        namespace = runpy.run_path(str(ROOT / path))
    finally:
        sys.stdout = old_stdout
        sys.stderr = old_stderr
    assert stream.getvalue() == "", f"{path} emitted output during import"
    return namespace


def test_task7_immutable_controls_are_canonical_lf_exact():
    for path, expected in TASK7_IMMUTABLE_CONTROLS.items():
        actual = _canonical_lf_sha256((ROOT / path).read_bytes()).upper()
        assert actual == expected, path


def test_task9_control_pins_are_checkout_eol_portable_and_mutation_sensitive():
    task4_shared = {row[0] for row in TASK4_SHARED_CONTROL_FRAGMENTS}
    controls = {
        path: expected.lower()
        for path, expected in TASK4_CONTROL_HASHES.items()
        if path not in task4_shared
    }
    controls.update(
        (path, expected.lower())
        for path, expected in TASK7_IMMUTABLE_CONTROLS.items()
    )
    for path, expected in controls.items():
        raw = (ROOT / path).read_bytes()
        lf = raw.replace(b"\r\n", b"\n").replace(b"\r", b"\n")
        crlf = lf.replace(b"\n", b"\r\n")
        assert _canonical_lf_sha256(lf) == expected, path
        assert _canonical_lf_sha256(crlf) == expected, path
        offset = next(index for index, value in enumerate(lf) if value not in (10, 13))
        mutant = lf[:offset] + bytes((lf[offset] ^ 1,)) + lf[offset + 1:]
        assert _canonical_lf_sha256(mutant) != expected, path


def test_task7_python_n3_distinct_pair_census_is_exact():
    sys.path.insert(0, str(ROOT / "simulations"))
    import framework as fw
    from itertools import combinations

    labels = tuple(a + b for a in "XYZ" for b in "XYZ")
    routed = {
        f"{left}+{right}": fw.classify_two_term_palindrome(left, right)["fate"]
        for left, right in combinations(labels, 2)
    }
    assert len(routed) == 36
    assert {key for key, fate in routed.items() if fate == "truly"} == {
        "XX+YY", "XX+ZZ", "YY+ZZ",
    }
    assert [*routed.values()].count("truly") == 3
    assert [*routed.values()].count("soft") == 19
    assert [*routed.values()].count("hard") == 14


def test_task7_csharp_router_includes_self_pairs_and_exact_split():
    source = read_host(
        "compute/RCPsiSquared.Diagnostics.Tests/F87/TwoTermPalindromeRoutingTests.cs"
    )
    entries = dict(re.findall(
        r'\["([A-Z]{2}\+[A-Z]{2})"\]\s*=\s*\("(truly|soft|hard)"', source
    ))
    assert len(entries) == 45
    assert list(entries.values()).count("truly") == 6
    assert list(entries.values()).count("soft") == 25
    assert list(entries.values()).count("hard") == 14
    assert {key for key, fate in entries.items() if fate == "truly"} == {
        "XX+XX", "XX+YY", "XX+ZZ", "YY+YY", "YY+ZZ", "ZZ+ZZ",
    }
    assert "OverAll45Combos" in source
    assert "OverAll36Combos" not in source
    claim = read_host(
        "compute/RCPsiSquared.Diagnostics/F87/TwoTermPalindromeRoutingClaim.cs"
    )
    assert "Routing_AgreesWithSpectralAuthority_OverAll45Combos_N4" in claim
    assert "OverAll36Combos" not in claim


def test_task7_historical_120_catalog_has_exact_alphabet_membership_and_split():
    namespace = _task7_import_module("simulations/pi_protected_test_n4.py")
    assert tuple(namespace["TWO_SITE_PAULI_WORDS"]) == TASK7_TWO_SITE_WORDS
    catalog = namespace["historical_two_site_pair_catalog"]()
    assert len(catalog) == 120
    assert len(set(catalog)) == 120
    assert sum(left == right for left, right, _ in catalog) == 15
    classes = {
        f"{left}+{right}": fate for left, right, fate in catalog
    }
    assert {key for key, fate in classes.items() if fate == "truly"} == TASK7_TRULY_120
    assert {key for key, fate in classes.items() if fate == "soft"} == TASK7_SOFT_120
    assert [*classes.values()].count("hard") == 59
    for path in (
        "compute/RCPsiSquared.Diagnostics/F87/F87TrichotomyClassification.cs",
        "compute/RCPsiSquared.Diagnostics/F87/F87Pi2Inheritance.cs",
        "docs/ANALYTICAL_FORMULAS.md",
        "review/EMERGING_QUESTIONS.md",
    ):
        text = read_host(path)
        assert "15/46/59" in text, path
        assert "120" in text, path
        assert "combinations with replacement" in text.lower(), path
        assert "C(6,2)" not in text, path
        assert "six two-site operators" not in text.lower(), path
        assert "II, IX, XI, XX, YY, ZZ" not in text, path


