def test_task7_pi_spectrum_pairing_is_global_one_use_and_order_invariant():
    namespace = _task7_import_module("simulations/pi_protected_test_n4.py")
    pairing_error = namespace["spectrum_pair_max_err"]
    eigenvalues = np.array([-1.000001, 1.0000005, -1.0, 1.0000019])
    expected = pytest.approx(9.0e-7, abs=2e-16)
    errors = []
    for permutation in (
        (0, 1, 2, 3),
        (2, 1, 0, 3),
        (3, 0, 2, 1),
        (1, 3, 0, 2),
    ):
        matrix = np.diag(eigenvalues[list(permutation)]).astype(complex)
        errors.append(pairing_error(matrix, 0.0))
    assert errors == [expected] * 4
    assert all(error < 1e-6 for error in errors)


def test_task7_historical_catalog_summary_label_flows_from_actual_selected_n(tmp_path):
    source = read_host("simulations/pi_protected_test_n4.py")
    namespace = _task7_import_module("simulations/pi_protected_test_n4.py")
    output = io.StringIO()
    with contextlib.redirect_stdout(output):
        rows = namespace["main"](selected_n=3)
    emitted = output.getvalue()
    assert len(rows) == 120
    assert [row["verdict"] for row in rows].count("truly") == 15
    assert [row["verdict"] for row in rows].count("soft") == 46
    assert [row["verdict"] for row in rows].count("hard") == 59
    assert {row["label"]: row["verdict"] for row in rows} == {
        f"{left}+{right}": fate
        for left, right, fate in namespace["historical_two_site_pair_catalog"]()
    }
    assert "selected N=3" in emitted
    assert "N=3: 15 truly, 46 soft, 59 hard" in emitted
    assert "N=4: 15 truly" not in emitted
    assert "results = compute_historical_catalog_results(" in source
    assert "format_historical_catalog_comparison(N, results)" in source

    old = 'f"  N={N}: {n_truly} truly, {n_soft} soft, {n_hard} hard"'
    hardcoded = 'f"  N=4: {n_truly} truly, {n_soft} soft, {n_hard} hard"'
    mutant_source = source.replace(old, hardcoded, 1)
    assert mutant_source != source
    mutant = source_copy_definitions(
        mutant_source, {"format_historical_catalog_comparison"}, tmp_path,
        prelude="",
    )["format_historical_catalog_comparison"]
    main_globals = namespace["main"].__globals__
    original_formatter = main_globals["format_historical_catalog_comparison"]
    try:
        main_globals["format_historical_catalog_comparison"] = mutant
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            mutant_rows = namespace["main"](selected_n=3)
    finally:
        main_globals["format_historical_catalog_comparison"] = original_formatter
    assert len(mutant_rows) == 120
    assert "N=3: 15 truly, 46 soft, 59 hard" not in output.getvalue()
    assert "N=4: 15 truly, 46 soft, 59 hard" in output.getvalue()

    # A controlled change to the computed rows must reach the emitted footer;
    # formatting a separate hand-coded catalog would leave 15/46/59 unchanged.
    altered_rows = [dict(row) for row in rows]
    assert altered_rows[0]["verdict"] == "truly"
    altered_rows[0]["verdict"] = "hard"
    original_compute = main_globals["compute_historical_catalog_results"]
    try:
        main_globals["compute_historical_catalog_results"] = (
            lambda N, gamma, coupling: altered_rows
        )
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            disconnected_probe_rows = namespace["main"](selected_n=3)
    finally:
        main_globals["compute_historical_catalog_results"] = original_compute
    assert disconnected_probe_rows is altered_rows
    assert "N=3: 14 truly, 46 soft, 60 hard" in output.getvalue()


def test_task7_d02_phase_identity_is_exact_and_sign_sensitive(tmp_path):
    namespace = _task7_import_module("simulations/verify_derivations.py")
    residual = namespace["d02_geometric_series_residual"]
    for x in (sp.pi / 2, sp.pi / 3, sp.pi / 5, sp.pi / 11):
        assert sp.simplify(residual(x)) == 0
    x = sp.pi / 2
    w = sp.cos(x) + sp.I * sp.sin(x)
    wrong_sign = sp.simplify((w + 1) + sp.I * sp.cot(x / 2) * (1 - w))
    assert wrong_sign == 2 + 2 * sp.I
    producer_source = read_host("simulations/verify_derivations.py")
    correct = "(w + 1) - sp.I * (1 / half_tangent) * (1 - w)"
    wrong = "(w + 1) + sp.I * (1 / half_tangent) * (1 - w)"
    assert producer_source.count(correct) == 1
    mutant_source = producer_source.replace(correct, wrong, 1)
    mutant_residual = source_copy_definitions(
        mutant_source,
        {"d02_geometric_series_residual"},
        tmp_path,
        prelude="import sympy as sp\n",
    )["d02_geometric_series_residual"]
    assert sp.simplify(mutant_residual(sp.pi / 2)) == 2 + 2 * sp.I
    doc = read_host("docs/proofs/derivations/D02_VEFFECT_QMAX_QMEAN.md")
    assert "+i * cot(pi/(2N))" in doc
    assert "complexity explosion" not in doc.lower()
    assert (
        "Source formulas:** 6 (F6 Q-edge gain; historical alias: V-Effect gain)"
        in doc
    )
    unqualified = doc.replace(
        "6 (F6 Q-edge gain; historical alias: V-Effect gain)",
        "6 (V-Effect gain)",
        1,
    )
    assert unqualified != doc
    assert task7_veffect_scope_findings(
        "docs/proofs/derivations/D02_VEFFECT_QMAX_QMEAN.md", unqualified
    )


def test_task7_cavity_neighbourhood_is_one_sided_strict_and_measured(tmp_path):
    namespace = _task7_import_module("simulations/veffect_cavity_modes.py")
    neighbourhood = namespace["cold_warm_frequency_neighbourhood"]
    expected = (0.0, 0.0016193, 0.0226557, 0.0289709)
    readings = [neighbourhood(n, gamma=0.05, match_radius=0.1)
                for n in range(2, 6)]
    assert tuple(row["matched_count"] for row in readings) == tuple(
        row["cold_count"] for row in readings
    )
    assert np.allclose(
        [row["max_nearest_distance"] for row in readings], expected,
        rtol=0.0, atol=5e-7,
    )
    assert all(not neighbourhood(n, gamma=0.05, match_radius=1e-6)["fully_covered"]
               for n in range(3, 6))
    boundary = neighbourhood(
        0, gamma=0.05, match_radius=0.125,
        cold_frequencies=np.array([1.0]),
        warm_frequencies=np.array([1.125]),
    )
    assert boundary["nearest_distances"][0] == 0.125
    assert boundary["matched_count"] == 0
    assert boundary["fully_covered"] is False

    reusable = neighbourhood(
        0, gamma=0.05, match_radius=0.125,
        cold_frequencies=np.array([1.0, 1.125]),
        warm_frequencies=np.array([1.0625]),
    )
    assert reusable["cold_count"] == 2 and reusable["warm_count"] == 1
    assert reusable["nearest_distances"] == (0.0625, 0.0625)
    assert reusable["matched_count"] == 2
    assert reusable["fully_covered"] is True

    source = read_host("simulations/veffect_cavity_modes.py")
    mutant_source = source.replace(
        "covered = nearest < match_radius",
        "covered = nearest <= match_radius",
        1,
    )
    assert mutant_source != source
    mutant = source_copy_definitions(
        mutant_source, {"cold_warm_frequency_neighbourhood"}, tmp_path,
        prelude="import numpy as np\nGAMMA=0.05\nMATCH_RADIUS=0.1\n",
    )["cold_warm_frequency_neighbourhood"]
    admitted = mutant(
        0, gamma=0.05, match_radius=0.125,
        cold_frequencies=np.array([1.0]),
        warm_frequencies=np.array([1.125]),
    )
    assert admitted["matched_count"] == 1
    assert admitted["fully_covered"] is True


