def test_task7_pi_import_does_not_reconfigure_stdout(monkeypatch):
    class StdoutSpy:
        calls = 0

        def reconfigure(self, *args, **kwargs):
            self.calls += 1
            raise AssertionError("import must not reconfigure stdout")

        def write(self, value):
            return len(value)

        def flush(self):
            return None

    spy = StdoutSpy()
    monkeypatch.setattr(sys, "stdout", spy)
    runpy.run_path(
        str(ROOT / "simulations/pi_protected_test_n4.py"),
        run_name="task7_pi_import_probe",
    )
    assert spy.calls == 0


