def test_task7_cockpit_pca_signs_are_canonical_and_flip_invariant():
    namespace = _task7_import_module("simulations/cockpit_n5.py")
    canonicalize = namespace["canonicalize_pca_signs"]
    loadings = np.array([[-0.9, 0.1, 0.2], [0.2, -0.8, 0.3]])
    scores = np.array([[1.0, 2.0], [-3.0, 4.0]])
    expected_loadings, expected_scores = canonicalize(loadings, scores)
    signs = np.array([-1.0, 1.0])
    flipped_loadings = loadings * signs[:, None]
    flipped_scores = scores * signs[None, :]
    actual_loadings, actual_scores = canonicalize(
        flipped_loadings, flipped_scores
    )
    assert np.array_equal(actual_loadings, expected_loadings)
    assert np.array_equal(actual_scores, expected_scores)
    assert expected_loadings[0, 0] > 0 and expected_loadings[1, 1] > 0


