def test_task7_n5_producer_exposes_bounded_domain_and_exact_identities():
    namespace = _task7_import_module("simulations/n5_optimal_cavity_size.py")
    assert tuple(namespace["DENSE_CENSUS_N"]) == (3, 4, 5)
    assert tuple(namespace["SACRIFICE_SCAN_N"]) == (3, 4, 5)
    f6 = namespace["f6_q_edge_gain"]
    ratios = namespace["cold_frequency_ratios"]
    phi = (1 + np.sqrt(5)) / 2
    assert f6(5) == pytest.approx(1 + phi / 2, abs=1e-14)
    assert ratios(5)[0] == pytest.approx(2 + phi, abs=1e-13)
    exact_phi = (1 + sp.sqrt(5)) / 2
    exact_ratio = (1 - sp.cos(2 * sp.pi / 5)) / (1 - sp.cos(sp.pi / 5))
    assert sp.simplify(exact_ratio - (2 + exact_phi)) == 0
    assert sp.simplify(1 + sp.cos(sp.pi / 5) - (1 + exact_phi / 2)) == 0
    wrong_index = (1 - sp.cos(3 * sp.pi / 5)) / (1 - sp.cos(sp.pi / 5))
    assert sp.simplify(wrong_index - (2 + exact_phi)) != 0
    assert namespace["fixed_index_ratio_limit"](4, 3) == Fraction(16, 9)
    assert namespace["fixed_index_ratio_limit"](3, 2) == Fraction(9, 4)
    source = read_host("simulations/n5_optimal_cavity_size.py").lower()
    for stale in (
        "n=5 is the goldilocks zone", "sacrifice zone peak shifts",
        "universally the sacrifice zone peak", "mode frequency ratios do not contain phi",
    ):
        assert stale not in source
    result = read_host("simulations/results/n5_optimal_cavity_size.txt").lower()
    assert "sampled n=(3,4,5)" in result
    assert "not select n=5 as an optimum" in result
    assert "2 + phi" in result
    assert "16/9" in result and "9/4" in result


