@pytest.mark.parametrize("path", tuple(p for p in TASK7_PRECISION_HOSTS if p != "docs/GLOSSARY.md"))
def test_task7_precision_fence_mutations_fail_in_the_local_owner_paragraph(path):
    source = read_host(path)
    paragraphs = re.split(r"\n\s*\n", source.replace("\r\n", "\n").replace("\r", "\n"))
    owners = [paragraph for paragraph in paragraphs
              if "precision fence:" in paragraph.lower()]
    if not owners:
        owners = [
            paragraph for paragraph in paragraphs
            if all(token in paragraph.lower() for token in (
                "four-decimal", "11/4", "three-decimal", "8/4",
            ))
        ]
    assert len(owners) == 1, (path, len(owners))
    owner = owners[0]
    for mutant_owner in (
        owner.replace("11/4", "8/4", 1),
        re.sub("four-decimal", "unspecified", owner, count=1, flags=re.I),
        owner.replace("8/4", "11/4", 1),
        re.sub("three-decimal", "coarse", owner, count=1, flags=re.I),
    ):
        assert mutant_owner != owner
        mutant = source.replace(owner, mutant_owner, 1)
        findings = task7_veffect_scope_findings(path, mutant)
        assert any("PRECISION_LOCAL" in row for row in findings), (path, findings)


