def _task7_insert_current_claim(path, source, claim):
    """Insert one syntactically inert claim into the real host's current surface."""
    if path.endswith(".py"):
        payload = f"# {claim}"
    elif path.endswith(".cs"):
        payload = f"// {claim}"
    else:
        payload = claim

    if path in TASK7_WRAPPER_REQUIRED:
        marker = ("VEFFECT-HISTORICAL" if path.endswith("proton_water_chain.txt")
                  else "<!-- VEFFECT-HISTORICAL -->")
        assert source.count(marker) == 1, path
        return source.replace(marker, payload + "\n\n" + marker, 1)
    if path in TASK7_SHARED_FRAGMENT_SPECS:
        return _task7_insert_into_shared_fragment(path, source, payload)
    return source.rstrip() + "\n\n" + payload + "\n"


