def _task7_read_entry_head(path):
    completed = subprocess.run(
        ["git", "show", f"{TASK7_ENTRY_HEAD}:{path}"],
        cwd=ROOT,
        check=True,
        capture_output=True,
    )
    return completed.stdout.decode("utf-8")


def _task7_entry_head_removed_opcodes(path, current):
    old_lines = _task7_read_entry_head(path).replace("\r\n", "\n").splitlines()
    new_lines = current.replace("\r\n", "\n").splitlines()
    return old_lines, new_lines, tuple(
        difflib.SequenceMatcher(
            None, old_lines, new_lines, autojunk=False
        ).get_opcodes()
    )


def _task7_restore_entry_head_opcode(path, current, disposition):
    (record_path, old_start, old_end, new_start, new_end, _decision,
     expected_old_sha, expected_new_sha) = disposition
    assert record_path == path
    old_lines, new_lines, opcodes = _task7_entry_head_removed_opcodes(
        path, current
    )
    assert ("replace", old_start, old_end, new_start, new_end) in opcodes
    old_payload = "\n".join(old_lines[old_start:old_end])
    new_payload = "\n".join(new_lines[new_start:new_end])
    assert hashlib.sha256(old_payload.encode("utf-8")).hexdigest().upper() == (
        expected_old_sha
    )
    assert hashlib.sha256(new_payload.encode("utf-8")).hexdigest().upper() == (
        expected_new_sha
    )
    restored_lines = (
        new_lines[:new_start]
        + old_lines[old_start:old_end]
        + new_lines[new_end:]
    )
    trailing_newline = "\n" if current.endswith(("\n", "\r")) else ""
    return "\n".join(restored_lines) + trailing_newline


def _task7_mixed_opcode_disposition_findings(dispositions):
    findings = []
    if len(dispositions) != 56:
        findings.append(f"MIXED_OPCODE_COUNT:{len(dispositions)}")
    payload = json.dumps(
        dispositions, separators=(",", ":")
    ).encode("utf-8")
    digest = hashlib.sha256(payload).hexdigest().upper()
    if digest != TASK7_ENTRY_HEAD_MIXED_OPCODE_DISPOSITION_SHA256:
        findings.append(f"MIXED_OPCODE_DISPOSITION_SHA256:{digest}")
    return findings


def _task7_python_claim_line_indexes(source, *, line_offset=0):
    indexes = set()
    claim_token_types = {
        tokenize.COMMENT,
        tokenize.STRING,
        getattr(tokenize, "FSTRING_MIDDLE", -1),
    }
    tokens = tokenize.generate_tokens(io.StringIO(source).readline)
    for token in tokens:
        if token.type not in claim_token_types:
            continue
        indexes.update(
            line_offset + row
            for row in range(token.start[0] - 1, token.end[0])
        )
    return indexes


def _task7_owned_new_line_indexes(path, current):
    """Map the final structural owner contract to current-source line indexes."""
    normalized, lines = _task7_line_ranges(current)
    if path in TASK7_FULL_HOST_BOUND_PATHS:
        return set(range(len(lines)))
    if path in TASK7_WRAPPER_BOUND_PATHS:
        marker = (
            "VEFFECT-HISTORICAL"
            if path.endswith("proton_water_chain.txt")
            else "<!-- VEFFECT-HISTORICAL -->"
        )
        assert normalized.count(marker) == 1, (path, marker)
        boundary = normalized.index(marker)
        return {index for index, (start, _, _) in enumerate(lines) if start < boundary}
    if path in TASK7_CODE_CLAIM_BOUND_PATHS:
        if path.endswith(".py"):
            return _task7_python_claim_line_indexes(normalized)
        return {
            index
            for index, (_, _, raw) in enumerate(lines)
            if any(marker in raw for marker in ('"', "//", "/*", "*/"))
        }
    if path in TASK7_SHARED_FRAGMENT_SPECS:
        _, spans = _task7_shared_fragment_spans(path, normalized)
        indexes = set()
        for record, start, end, kind, _ in spans:
            assert start is not None and end is not None, (path, record)
            if kind == "python-claims-span":
                line_offset = normalized[:start].count("\n")
                indexes.update(
                    _task7_python_claim_line_indexes(
                        normalized[start:end], line_offset=line_offset
                    )
                )
                continue
            indexes.update(
                index
                for index, (line_start, _, _) in enumerate(lines)
                if start <= line_start < end
            )
        return indexes
    raise AssertionError(f"unclassified Task-7 owner surface: {path}")


def _task7_expected_mixed_opcode_keys():
    """Recompute every raw replace that straddles an owned current surface.

    The frozen disposition rows are an audit of boundary-spanning opcodes, not
    a hand-maintained sample.  Recomputing the keys makes an omitted row (or a
    stale row that is now wholly owned) visible even when the literal count and
    table digest are updated together.
    """
    keys = set()
    excluded_classes = set(TASK7_FULL_HOST_BOUND_PATHS) | set(
        TASK7_WRAPPER_BOUND_PATHS
    )
    excluded_paths = TASK7_ENTRY_HEAD_UNCHANGED | TASK7_ENTRY_HEAD_ADDITION_ONLY
    for path in TASK7_SEMANTIC_HOSTS:
        if path in excluded_classes or path in excluded_paths:
            continue
        current = read_host(path)
        owned = _task7_owned_new_line_indexes(path, current)
        _, _, opcodes = _task7_entry_head_removed_opcodes(path, current)
        for tag, old_start, old_end, new_start, new_end in opcodes:
            if tag != "replace":
                continue
            replacement = set(range(new_start, new_end))
            if replacement & owned and not replacement <= owned:
                keys.add((path, old_start, old_end, new_start, new_end))
    return keys


def _task7_normalized_entry_head_removed_surface_unscoped(path, current):
    """Return every real replaced/deleted entry-HEAD hunk for audit only."""
    old_lines, _, opcodes = _task7_entry_head_removed_opcodes(path, current)
    chunks = []
    for tag, old_start, old_end, _, _ in opcodes:
        if tag not in {"delete", "replace"}:
            continue
        normalized = re.sub(r"\s+", " ", " ".join(old_lines[old_start:old_end])).strip()
        if normalized:
            chunks.append(normalized)
    return tuple(chunks)


def _task7_normalized_entry_head_removed_surface(path, current):
    """Return only entry-HEAD hunks wholly inside the final Task-7 owner surface.

    Exact old-copy restoration is a byte-level backstop, not authority to freeze
    another task's slice.  FULL hosts own every hunk.  All other classes retain
    a hunk only when its complete current-side replacement lies in the final
    wrapper, code-claim, or explicit shared span.  A pure deletion is retained
    only when both surviving neighbours are owned, avoiding boundary guesses.
    """
    if path in TASK7_CODE_CLAIM_BOUND_PATHS:
        old_records = _task7_code_claim_records(
            path, _task7_read_entry_head(path)
        )
        current_records = _task7_code_claim_records(path, current)
        removed = []
        for tag, old_start, old_end, _, _ in difflib.SequenceMatcher(
            None, old_records, current_records, autojunk=False
        ).get_opcodes():
            if tag not in {"delete", "replace"}:
                continue
            removed.extend(
                _task7_claim_record_payload(record)
                for record in old_records[old_start:old_end]
            )
        return tuple(removed)

    old_lines, new_lines, opcodes = _task7_entry_head_removed_opcodes(
        path, current
    )
    if path in TASK7_FULL_HOST_BOUND_PATHS:
        return _task7_normalized_entry_head_removed_surface_unscoped(path, current)
    owned = _task7_owned_new_line_indexes(path, current)
    chunks = []
    for tag, old_start, old_end, new_start, new_end in opcodes:
        if tag not in {"delete", "replace"}:
            continue
        if new_start < new_end:
            replacement = set(range(new_start, new_end))
            structural_markers = {
                index for index in replacement
                if re.fullmatch(
                    r"<!-- (?:QUARTER|CROSSING|F14)-"
                    r"(?:CURRENT|HISTORICAL|INTERPRETIVE) -->",
                    new_lines[index].strip(),
                )
            }
            semantic_replacement = replacement - structural_markers
            is_owned = (
                bool(semantic_replacement)
                and semantic_replacement <= owned
            )
        else:
            is_owned = new_start - 1 in owned and new_start in owned
        if not is_owned:
            continue
        normalized = re.sub(
            r"\s+", " ", " ".join(old_lines[old_start:old_end])
        ).strip()
        if normalized:
            chunks.append(normalized)
    return tuple(chunks)


def _task7_entry_head_restoration_findings(path, source):
    """Fail closed on any exact normalized hunk removed from entry HEAD.

    This exact-byte layer is deliberately paired with the semantic relation /
    object mutations below.  It makes real old-copy restoration independently
    falsifiable without pretending exact wording catches paraphrases.
    """
    if path not in TASK7_SEMANTIC_HOSTS or path in (
        TASK7_ENTRY_HEAD_UNCHANGED | TASK7_ENTRY_HEAD_ADDITION_ONLY
    ):
        return []
    source_normalized = re.sub(r"\s+", " ", source).strip()
    findings = []
    for chunk in TASK7_ENTRY_HEAD_ABSENT_CHUNKS.get(path, ()):
        if chunk not in source_normalized:
            continue
        digest = hashlib.sha256(chunk.encode("utf-8")).hexdigest().upper()
        findings.append(f"{path}:ENTRY_HEAD_RESTORATION:{digest}")
    return findings


@pytest.mark.parametrize("path", TASK7_SEMANTIC_HOSTS)
def test_task7_entry_head_real_host_restoration_is_rejected(path):
    """The literal pre-Task7 host is the authoritative restoration mutant."""
    current = read_host(path)
    assert task7_veffect_scope_findings(path, current) == []
    entry_head = _task7_read_entry_head(path)
    if path in TASK7_ENTRY_HEAD_UNCHANGED:
        assert entry_head.replace("\r\n", "\n") == current.replace("\r\n", "\n")
        return
    assert entry_head.replace("\r\n", "\n") != current.replace("\r\n", "\n")
    findings = task7_veffect_scope_findings(path, entry_head)
    assert findings, f"literal entry-HEAD restoration escaped for {path}"
    assert all(finding.startswith(f"{path}:") for finding in findings)


@pytest.mark.parametrize(
    "path", tuple(path for path in TASK7_SEMANTIC_HOSTS
                  if path not in (TASK7_ENTRY_HEAD_UNCHANGED
                                  | TASK7_ENTRY_HEAD_ADDITION_ONLY))
)
def test_task7_normalized_entry_head_removed_surface_is_rejected(path):
    """Every frozen absent removed/replaced paragraph must fail locally."""
    current = read_host(path)
    assert task7_veffect_scope_findings(path, current) == []
    chunks = TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path]
    if path in TASK7_ENTRY_HEAD_CURRENT_ONLY_OWNER_DISPOSITIONS:
        assert chunks == ()
        return
    assert chunks, f"no literal entry-HEAD removed surface recovered for {path}"
    for index, chunk in enumerate(chunks):
        mutant = _task7_insert_current_claim(path, current, chunk)
        findings = task7_veffect_scope_findings(path, mutant)
        digest = hashlib.sha256(chunk.encode("utf-8")).hexdigest().upper()
        expected = f"{path}:ENTRY_HEAD_RESTORATION:{digest}"
        assert expected in findings, (
            f"normalized entry-HEAD chunk {index}/{len(chunks)} escaped for {path}"
        )


def test_task7_entry_head_chunks_slice_one_mutation_is_killed(monkeypatch):
    """A checker reduced to cached_chunks[:1] misses this late real hunk."""
    path = "experiments/V_EFFECT_PALINDROME.md"
    current = read_host(path)
    chunks = TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path]
    assert len(chunks) > 1
    assert chunks[-1] not in chunks[:1]
    digest = hashlib.sha256(chunks[-1].encode("utf-8")).hexdigest().upper()
    mutant = _task7_insert_current_claim(path, current, chunks[-1])
    expected = f"{path}:ENTRY_HEAD_RESTORATION:{digest}"
    assert expected in task7_veffect_scope_findings(path, mutant)

    original = TASK7_ENTRY_HEAD_ABSENT_CHUNKS
    reduced = dict(original)
    reduced[path] = original[path][:1]
    monkeypatch.setattr(
        sys.modules[__name__],
        "TASK7_ENTRY_HEAD_ABSENT_CHUNKS",
        reduced,
    )
    assert expected not in task7_veffect_scope_findings(path, mutant)


def test_task7_entry_head_restoration_dispositions_cover_semantic70():
    removed = set(TASK7_SEMANTIC_HOSTS) - TASK7_ENTRY_HEAD_UNCHANGED \
        - TASK7_ENTRY_HEAD_ADDITION_ONLY
    assert removed | TASK7_ENTRY_HEAD_UNCHANGED \
        | TASK7_ENTRY_HEAD_ADDITION_ONLY == set(TASK7_SEMANTIC_HOSTS)
    assert not (removed & TASK7_ENTRY_HEAD_UNCHANGED)
    assert not (removed & TASK7_ENTRY_HEAD_ADDITION_ONLY)
    assert not (TASK7_ENTRY_HEAD_UNCHANGED & TASK7_ENTRY_HEAD_ADDITION_ONLY)


@pytest.mark.parametrize("path,rule,claim", TASK7_RESTORATION_MUTATION_MATRIX)
def test_task7_design_restoration_matrix_is_path_local(path, rule, claim):
    source = read_host(path)
    assert task7_veffect_scope_findings(path, source) == []
    mutant = _task7_insert_current_claim(path, source, claim)
    assert mutant != source
    findings = task7_veffect_scope_findings(path, mutant)
    assert f"{path}:RESTORED_TASK7_CLAIM:{rule}" in findings


def test_task7_restoration_matrix_covers_every_semantic_disposition():
    assert {path for path, _, _ in TASK7_RESTORATION_MUTATION_MATRIX} == set(
        TASK7_SEMANTIC_HOSTS
    )


