def test_task7_relevant_surface_edit_delete_move_and_region_move_fail():
    path = "experiments/V_EFFECT_PALINDROME.md"
    source = read_host(path)
    paragraphs = source.replace("\r\n", "\n").split("\n\n")
    selected = [
        paragraph for paragraph in paragraphs
        if TASK7_RELEVANCE_ANCHOR_PATTERN.search(
            _task7_semantic_canonical(paragraph)
        )
        and not TASK7_REGION_MARKER.fullmatch(_task7_normalize_paragraph(paragraph))
    ]
    assert len(selected) > 3
    edit = source.replace(selected[1], selected[1] + " Edited.", 1)
    delete = source.replace(selected[1], "", 1)
    first_index = paragraphs.index(selected[1])
    second_index = paragraphs.index(selected[2])
    moved_paragraphs = list(paragraphs)
    moved_paragraphs[first_index], moved_paragraphs[second_index] = (
        moved_paragraphs[second_index], moved_paragraphs[first_index]
    )
    move = "\n\n".join(moved_paragraphs)
    region_move = source.replace(
        "<!-- VEFFECT-CURRENT -->", "<!-- VEFFECT-INTERPRETIVE -->", 1
    )
    for mutant in (edit, delete, move, region_move):
        assert _task7_approved_surface_findings(path, mutant)


