def test_task7_c1_historical_helper_and_schema_remain_compatible():
    """The label repair must not silently break the historical producer API."""
    path = "simulations/c1_veffect_scaling.py"
    source = read_host(path)
    tree = ast.parse(source, filename=path)
    functions = [
        node for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name in {"v_effect", "f6_q_edge_gain"}
    ]
    assert {node.name for node in functions} == {"v_effect", "f6_q_edge_gain"}
    namespace = {"np": np}
    exec(compile(ast.Module(functions, type_ignores=[]), path, "exec"), namespace)
    for n in (3, 4, 5, 7):
        expected = 1.0 + np.cos(np.pi / n)
        assert namespace["v_effect"](n) == pytest.approx(expected)
        assert namespace["f6_q_edge_gain"](n) == pytest.approx(expected)
    assert source.count('"V_N": f6_q_edge_gain(N)') == 2
    assert '"F6_Q_edge_gain": f6_q_edge_gain(N)' not in source


