def test_task7_mixed_opcode_disposition_table_is_frozen_and_nonvacuous():
    dispositions = TASK7_ENTRY_HEAD_MIXED_OPCODE_DISPOSITIONS
    assert _task7_mixed_opcode_disposition_findings(dispositions) == []
    assert {row[5] for row in dispositions} == {
        "EXCLUDE_LITERAL_MIXED_CURRENT_RANGE_OWNER_GATE"
    }
    frozen_keys = {row[:5] for row in dispositions}
    assert len(frozen_keys) == len(dispositions)
    assert frozen_keys == _task7_expected_mixed_opcode_keys()

    assert _task7_mixed_opcode_disposition_findings(dispositions[:-1])
    same_count_missing_one = dispositions[:-1] + (dispositions[0],)
    findings = _task7_mixed_opcode_disposition_findings(
        same_count_missing_one
    )
    assert any("DISPOSITION_SHA256" in finding for finding in findings)


def test_task7_docs_readme_current_only_owner_has_independent_restore_gate():
    path = "docs/README.md"
    assert TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path] == ()
    assert path in TASK7_ENTRY_HEAD_CURRENT_ONLY_OWNER_DISPOSITIONS
    disposition = next(
        row for row in TASK7_ENTRY_HEAD_MIXED_OPCODE_DISPOSITIONS
        if row[0] == path
    )
    source = read_host(path)
    assert _task7_approved_surface_findings(path, source) == []
    mutant = _task7_restore_entry_head_opcode(path, source, disposition)
    findings = task7_veffect_scope_findings(path, mutant)
    assert any(":ENTRY_HEAD_RESTORATION:" not in item for item in findings)


@pytest.mark.parametrize(
    "disposition", TASK7_ENTRY_HEAD_MIXED_OPCODE_DISPOSITIONS
)
def test_task7_every_mixed_opcode_restore_hits_independent_owner_gate(
    disposition,
):
    path = disposition[0]
    source = read_host(path)
    assert task7_veffect_scope_findings(path, source) == []
    mutant = _task7_restore_entry_head_opcode(path, source, disposition)
    assert mutant != source
    findings = task7_veffect_scope_findings(path, mutant)
    independent = [
        finding for finding in findings
        if ":ENTRY_HEAD_RESTORATION:" not in finding
    ]
    assert independent, (path, disposition[1:5], findings)


def test_task7_heisenberg_restored_unowned_section_two_remains_editable():
    """One of the 19 intentionally restored §2/outside chunks is permitted."""
    path = "hypotheses/HEISENBERG_RELOADED.md"
    source = read_host(path)
    restored = (
        "The physical exchange-derivation is correct, but it is downstream "
        "of the math, not upstream. Atoms are not where Heisenberg begins; "
        "they are where Level 0 first reappears in macroscopic matter."
    )
    normalized = _task7_normalize_bound_span(source)
    assert restored in normalized
    assert restored in _task7_normalize_bound_span(_task7_read_entry_head(path))
    assert restored not in TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path]
    mutant = source.replace(
        "The physical exchange-derivation is correct",
        "The physical exchange-derivation remains correct",
        1,
    )
    assert mutant != source
    assert _task7_approved_surface_findings(path, mutant) == []
    assert task7_veffect_scope_findings(path, mutant) == []


