def test_task7_frozen_old_chunk_survives_approval_digest_update(monkeypatch):
    path = "experiments/V_EFFECT_PALINDROME.md"
    source = read_host(path)
    chunk = TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path][-1]
    mutant = _task7_insert_current_claim(path, source, chunk)
    approvals = dict(TASK7_APPROVED_RELEVANT_SURFACE)
    approvals[path] = _task7_relevant_surface_signature(path, mutant)
    monkeypatch.setattr(
        sys.modules[__name__], "TASK7_APPROVED_RELEVANT_SURFACE", approvals
    )
    digest = hashlib.sha256(chunk.encode("utf-8")).hexdigest().upper()
    assert f"{path}:ENTRY_HEAD_RESTORATION:{digest}" in (
        task7_veffect_scope_findings(path, mutant)
    )


def test_task7_frozen_old_chunk_is_not_excused_by_restored_real_file(
    monkeypatch,
):
    path = "experiments/V_EFFECT_PALINDROME.md"
    source = read_host(path)
    chunk = TASK7_ENTRY_HEAD_ABSENT_CHUNKS[path][-1]
    restored = _task7_insert_current_claim(path, source, chunk)
    monkeypatch.setattr(
        sys.modules[__name__],
        "read_host",
        lambda candidate_path: restored if candidate_path == path else source,
    )
    digest = hashlib.sha256(chunk.encode("utf-8")).hexdigest().upper()
    assert f"{path}:ENTRY_HEAD_RESTORATION:{digest}" in (
        _task7_entry_head_restoration_findings(path, restored)
    )


