    altered[0] += " altered"
    approvals = dict(TASK7_BROAD_RANGE_CANONICAL_CARRIERS)
    approvals[path] = tuple(altered)
    monkeypatch.setattr(
        sys.modules[__name__], "TASK7_BROAD_RANGE_CANONICAL_CARRIERS", approvals
    )
    assert _task7_broad_range_canonical_carrier_findings(path, read_host(path)) == [
        f"{path}:BROAD_RANGE_CANONICAL_CARRIER:FIXTURE"
    ]


