def test_task7_canonical_fixture_initializer_has_no_live_host_dependency():
    source = read_host("simulations/tests/test_old_document_label_scope.py")
    tree = ast.parse(source)
    assignments = {
        target.id: node.value
        for node in tree.body
        if isinstance(node, ast.Assign)
        for target in node.targets
        if isinstance(target, ast.Name)
        and target.id in {
            "TASK7_BROAD_RANGE_CANONICAL_CARRIERS_B64",
            "TASK7_BROAD_RANGE_CANONICAL_LAYOUT_B64",
            "TASK7_BROAD_RANGE_CANONICAL_CARRIER_META",
        }
    }
    assert set(assignments) == {
        "TASK7_BROAD_RANGE_CANONICAL_CARRIERS_B64",
        "TASK7_BROAD_RANGE_CANONICAL_LAYOUT_B64",
        "TASK7_BROAD_RANGE_CANONICAL_CARRIER_META",
    }
    for value in assignments.values():
        ast.literal_eval(value)
        names = {node.id for node in ast.walk(value) if isinstance(node, ast.Name)}
        assert not names

    decoded_assignment = next(
        node.value
        for node in tree.body
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name)
            and target.id == "TASK7_BROAD_RANGE_CANONICAL_CARRIERS"
            for target in node.targets
        )
    )
    decoded_names = {
        node.id for node in ast.walk(decoded_assignment) if isinstance(node, ast.Name)
    }
    assert "read_host" not in decoded_names
    assert "_task7_broad_range_canonical_carriers" not in decoded_names
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr in {"read_text", "read_bytes", "open"}
        for node in ast.walk(decoded_assignment)
    )


