def _task7_single_function_namespace(source, path, name, globals_=None):
    tree = ast.parse(source, filename=path)
    node = next(
        item for item in tree.body
        if isinstance(item, ast.FunctionDef) and item.name == name
    )
    namespace = dict(globals_ or {})
    exec(compile(ast.Module([node], type_ignores=[]), path, "exec"), namespace)
    return namespace


def test_task7_cockpit_uniform_fastest_rate_is_2n_gamma_and_operator_exact():
    path = "simulations/cockpit_n5.py"
    namespace = _task7_import_module(path)
    rate = namespace["uniform_dephasing_fastest_rate"]
    n_qubits, gamma = 3, 0.05
    assert rate(n_qubits, gamma) == pytest.approx(2 * n_qubits * gamma)

    x_all = namespace["X"]
    for _ in range(1, n_qubits):
        x_all = np.kron(x_all, namespace["X"])
    hamiltonian = namespace["build_chain_H"](n_qubits)
    assert np.max(np.abs(hamiltonian @ x_all - x_all @ hamiltonian)) < 1e-13
    generator_on_x = -1j * (hamiltonian @ x_all - x_all @ hamiltonian)
    for jump in namespace["z_dephasing_ops"]([gamma] * n_qubits, n_qubits):
        jump_square = jump.conj().T @ jump
        generator_on_x += (
            jump @ x_all @ jump.conj().T
            - 0.5 * (jump_square @ x_all + x_all @ jump_square)
        )
    assert np.max(np.abs(generator_on_x + 2 * n_qubits * gamma * x_all)) < 1e-13

    source = read_host(path)
    old = "return 2 * n_qubits * gamma"
    mutant = source.replace(old, "return 2 * (n_qubits - 1) * gamma", 1)
    assert mutant != source and mutant.count("return 2 * (n_qubits - 1) * gamma") == 1
    mutated = _task7_single_function_namespace(
        mutant, path, "uniform_dephasing_fastest_rate"
    )
    assert mutated["uniform_dephasing_fastest_rate"](5, 0.05) != pytest.approx(0.5)
    assert task7_veffect_scope_findings(path, mutant)


def test_task7_cockpit_entanglement_status_distinguishes_never_dead_and_alive():
    path = "simulations/cockpit_n5.py"
    namespace = _task7_import_module(path)
    status = namespace["entanglement_threshold_status"]
    times = np.array([0.0, 1.0, 2.0])
    assert status(np.array([0.0, 0.005, 0.001]), times) == "never>0.01"
    assert status(np.array([0.0, 0.01, 0.01]), times) == "never>0.01"
    assert status(np.array([0.2, 0.02, 0.0]), times) == "t=2.00"
    assert status(np.array([0.2, 0.1, 0.02]), times) == "alive@end"
    assert status(np.array([0.2, 0.0, 0.02]), times) == "alive@end"

    source = read_host(path)
    mutant = source.replace(
        'return f"never>{threshold:g}"', 'return "alive@end"', 1
    )
    assert mutant != source
    mutated = _task7_single_function_namespace(
        mutant, path, "entanglement_threshold_status", {"np": np}
    )
    assert mutated["entanglement_threshold_status"](
        np.array([0.0, 0.005]), np.array([0.0, 1.0])
    ) != "never>0.01"
    assert task7_veffect_scope_findings(path, mutant)


