def test_task7_cockpit_bures_failure_is_visible(monkeypatch):
    namespace = _task7_import_module("simulations/cockpit_n5.py")

    pure_zero = np.array([[1.0, 0.0], [0.0, 0.0]], dtype=complex)
    pure_one = np.array([[0.0, 0.0], [0.0, 1.0]], dtype=complex)
    maximally_mixed = np.eye(2, dtype=complex) / 2
    assert namespace["bures_distance"](maximally_mixed, maximally_mixed) == pytest.approx(0.0)
    with pytest.warns(namespace["linalg"].LinAlgWarning):
        assert namespace["bures_distance"](pure_zero, pure_one) == pytest.approx(np.sqrt(2))
    with pytest.raises(ValueError, match="finite"):
        namespace["bures_distance"](
            np.array([[np.nan, 0.0], [0.0, 1.0]]), pure_zero
        )

    def fail_sqrtm(_):
        raise RuntimeError("intentional Bures control")

    monkeypatch.setattr(namespace["linalg"], "sqrtm", fail_sqrtm)
    with pytest.raises(RuntimeError, match="intentional Bures control"):
        namespace["bures_distance"](np.eye(2) / 2, np.eye(2) / 2)

    source = read_host("simulations/cockpit_n5.py")
    assert "except Exception" not in ast.get_source_segment(
        source,
        next(
            node for node in ast.walk(ast.parse(source))
            if isinstance(node, ast.FunctionDef) and node.name == "bures_distance"
        ),
    )


