def test_task7_import_does_not_mutate_sys_path(path):
    before = list(sys.path)
    try:
        _task7_import_module(path)
        assert sys.path == before
    finally:
        sys.path[:] = before
    tree = ast.parse(read_host(path), filename=path)
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and isinstance(node.func.value, ast.Attribute)
        and isinstance(node.func.value.value, ast.Name)
        and node.func.value.value.id == "sys"
        and node.func.value.attr == "path"
        and node.func.attr in {"insert", "append", "extend"}
        for node in ast.walk(tree)
    )


def test_task7_cockpit_universality_pair_table_is_complete_and_unique():
    source = read_host("experiments/COCKPIT_UNIVERSALITY.md")
    start = source.index("**All 10 qubit pairs at N=5")
    end = source.index("\n\n", source.index("| (3,4)", start))
    table = source[start:end]
    pairs = re.findall(r"^\| \((\d),(\d)\) \|", table, re.MULTILINE)
    expected = [(str(i), str(j)) for i in range(5) for j in range(i + 1, 5)]
    assert pairs == expected
    mutant = source.replace("| (1,3) | 2 | 0.260 | 11 | 0.000 | never above 0.01 |\n", "", 1)
    assert mutant != source
    assert task7_veffect_scope_findings("experiments/COCKPIT_UNIVERSALITY.md", mutant)


