def _task7_q52_entry(source, entry):
    marker = f"### {entry}"
    if source.count(marker) != 1:
        return ""
    tail = source.split(marker, 1)[1]
    return marker + tail.split("\n### OQ-", 1)[0]


def _task7_q52_current_truth_findings(path, source):
    if path not in TASK7_Q52_COMMIT_A_CURRENT_TRUTH_HOSTS:
        return []
    findings = []
    if TASK7_Q52_AUTHORITY_SENTENCE not in source:
        findings.append(f"{path}:Q52_CURRENT_TRUTH:MISSING_AUTHORITY")
    q52_surface = source
    proposal_authority_surface = source
    if path == "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md":
        if source.count("### OQ-026") != 1:
            findings.append(f"{path}:Q52_CURRENT_TRUTH:OQ026_BOUNDARY")
        else:
            proposal_authority_surface = source.split("### OQ-026", 1)[1].split("\n---", 1)[0]
    lowered = q52_surface.casefold()
    for stale in TASK7_Q52_FORBIDDEN_CURRENT:
        if stale.casefold() in lowered:
            findings.append(f"{path}:Q52_CURRENT_TRUTH:STALE:{stale}")
    if path in {
        "review/OPEN_QUESTIONS_INDEX.md",
        "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md",
    }:
        oq033 = _task7_q52_entry(source, "OQ-033")
        oq098 = _task7_q52_entry(source, "OQ-098")
        for entry, block in (("OQ-033", oq033), ("OQ-098", oq098)):
            if not block:
                findings.append(f"{path}:Q52_CURRENT_TRUTH:{entry}_BOUNDARY")
                continue
            for required in (
                TASK7_Q52_DETUNING_SCOPE,
                TASK7_Q52_MECHANISM_SCOPE,
                TASK7_Q52_WITNESS_SCOPE,
            ):
                if required not in block:
                    findings.append(
                        f"{path}:Q52_CURRENT_TRUTH:{entry}:MISSING:{required}"
                    )
        status_by_path = {
            "review/OPEN_QUESTIONS_INDEX.md": (
                TASK7_Q52_INDEX_OQ033_STATUS,
                TASK7_Q52_INDEX_OQ098_STATUS,
            ),
            "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md": (
                TASK7_Q52_PROPOSAL_OQ033_STATUS,
                "**Proposed Status:** open",
            ),
        }
        for entry, required in zip(("OQ-033", "OQ-098"), status_by_path[path]):
            if required not in _task7_q52_entry(source, entry):
                findings.append(
                    f"{path}:Q52_CURRENT_TRUTH:{entry}:MISSING_STATUS:{required}"
                )
    if path == "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md":
        for required in (
            TASK7_Q52_PROPOSAL_REGISTRY_PROVENANCE,
            TASK7_Q52_PROPOSAL_DOCUMENT_PROVENANCE,
        ):
            if required not in proposal_authority_surface:
                findings.append(
                    f"{path}:Q52_CURRENT_TRUTH:MISSING_PROVENANCE:"
                    f"{hashlib.sha256(required.encode('utf-8')).hexdigest().upper()}"
                )
    return findings


def test_task7_q52_registry_authority_is_qualitative_not_point_three_percent():
    python_registry = read_host("simulations/framework/confirmations.py")
    block = python_registry.split(
        "'cpsi_quarter_crossing_torino_feb2026': {", 1
    )[1].split("\n        '", 1)[0]
    for fragment in (
        "t*/T₂* = 0.936",
        "t* = 114.7 μs",
        "t*/T₂* = 1.036",
        "10.7% above the generalized prediction",
        "A QUALITATIVE confirmation",
        "not a precision match",
    ):
        assert fragment in block
    assert "0.3%" not in block

    csharp_registry = read_host(
        "compute/RCPsiSquared.Core/Confirmations/ConfirmationsRegistry.cs"
    )
    csharp_block = csharp_registry.split(
        'Name: "cpsi_quarter_crossing_torino_feb2026"', 1
    )[1].split("new Confirmation(", 1)[0]
    for fragment in (
        "t*/T₂* = 0.936",
        "t* = 114.7 μs",
        "t*/T₂* = 1.036",
        "10.7% above the generalized prediction",
        "A QUALITATIVE confirmation",
        "not a precision match",
    ):
        assert fragment in csharp_block
    assert "0.3%" not in csharp_block


