    assert set(TASK7_Q52_COMMIT_B_DEBT).isdisjoint(TASK7_VEFFECT_DISPOSITIONS)
    assert set(TASK7_Q52_COMMIT_B_DEBT).isdisjoint(
        path for path, _, _ in TASK7_RESTORATION_MUTATION_MATRIX
    )


