def test_task10_q52_predictions_summary_tail_cannot_overclaim_behind_same_prefix():
    path = "docs/PREDICTIONS.md"
    source = read_host(path)
    assert _task10_q52_summary_findings(path, source) == []
    summary_line = next(
        line for line in source.splitlines()
        if line.startswith(TASK10_Q52_PREDICTIONS_SUMMARY_PREFIX)
    )
    stale = (
        TASK10_Q52_PREDICTIONS_SUMMARY_PREFIX
        + " The late-time excess is conclusively attributed to detuning, "
        "with a known, per-qubit cause (§3) |"
    )
    mutant = source.replace(summary_line, stale, 1)
    assert mutant != source
    assert _task10_q52_summary_findings(path, mutant)


def test_task10_q52_complete_required_sentences_cannot_be_relocated_outside_owner_block():
    path = "docs/proofs/COMPLETE_MATHEMATICAL_DOCUMENTATION.md"
    source = read_host(path)
    assert _task10_q52_summary_findings(path, source) == []
    block_start = "**Q52 shadow record.**"
    block_end = "\n\n**CΨ > ¼ under active dynamics.**"
    block = block_start + source.split(block_start, 1)[1].split(block_end, 1)[0]
    overclaim = (
        "**Q52 shadow record.** The named analysis conclusively attributes "
        "the Q52 late-time excess mechanism to qubit-specific detuning."
    )
    relocated = "\n<!-- " + " ".join(TASK10_Q52_SUMMARY_REQUIRED) + " -->\n"
    mutant = source.replace(block, overclaim, 1) + relocated
    assert mutant != source
    assert _task10_q52_summary_findings(path, mutant)


def test_task10_q52_complete_alias_restoration_fails_in_its_owned_section():
    path = "docs/proofs/COMPLETE_MATHEMATICAL_DOCUMENTATION.md"
    source = read_host(path)
    assert _task10_q52_summary_findings(path, source) == []
    assert source.count(TASK10_Q52_COMPLETE_ALIAS) == 1
    mutant = source.replace(
        TASK10_Q52_COMPLETE_ALIAS,
        "shadow = qubit detuning",
        1,
    )
    assert mutant != source
    assert _task10_q52_summary_findings(path, mutant)


