def test_task10_q52_oq033_resolving_document_restoration_fails_same_gate(monkeypatch):
    path = "review/OPEN_QUESTIONS_INDEX_PROPOSAL_hardware-test.md"
    source = read_host(path)
    entry = _task7_q52_entry(source, "OQ-033")
    current = "**Resolving documents:** none"
    assert entry.count(current) == 1
    mutant_entry = entry.replace(current, "**Resolving documents:** `experiments/FIXED_POINT_SHADOW.md`", 1)
    mutant = source.replace(entry, mutant_entry, 1)
    assert mutant != source
    original = read_host
    monkeypatch.setitem(globals(), "read_host", lambda p: mutant if p == path else original(p))
