def _task7_fallback_import_try(path, source=None):
    tree = ast.parse(read_host(path) if source is None else source)
    candidates = []
    for node in tree.body:
        if not isinstance(node, ast.Try):
            continue
        if any(
            isinstance(handler.type, ast.Name)
            and handler.type.id == "ModuleNotFoundError"
            for handler in node.handlers
        ):
            candidates.append(node)
    assert len(candidates) == 1, (path, len(candidates))
    return candidates[0]


def _task7_execute_fallback_import(path, missing_name, source=None):
    import builtins
    import types

    node = _task7_fallback_import_try(path, source)
    module = ast.Module(body=[node], type_ignores=[])
    ast.fix_missing_locations(module)
    first_package_import = True

    class ImportStub(types.ModuleType):
        def __getattr__(self, name):
            value = object()
            setattr(self, name, value)
            return value

    def fake_import(name, globals=None, locals=None, fromlist=(), level=0):
        nonlocal first_package_import
        if first_package_import and name.startswith("simulations"):
            first_package_import = False
            raise ModuleNotFoundError(
                f"No module named {missing_name!r}", name=missing_name
            )
        stub = ImportStub(name)
        for requested in fromlist or ():
            setattr(stub, requested, object())
        return stub

    safe_builtins = dict(vars(builtins))
    safe_builtins["__import__"] = fake_import
    namespace = {"__builtins__": safe_builtins}
    exec(compile(module, path, "exec"), namespace)
    return namespace


@pytest.mark.parametrize(
    "path,expected_names",
    (
        ("simulations/cockpit_n5.py", {"gpt"}),
        ("simulations/pi_protected_test_n4.py", {"fw", "spectrum_pairing_error"}),
        (
            "simulations/n5_optimal_cavity_size.py",
            {"J", "TOL_FREQ", "build_hamiltonian", "chain_bonds", "distinct_frequencies"},
        ),
    ),
)
def test_task7_direct_script_import_fallback_is_narrow_and_transitive_safe(
    path, expected_names
):
    namespace = _task7_execute_fallback_import(path, "simulations")
    assert expected_names <= set(namespace)

    with pytest.raises(ModuleNotFoundError) as caught:
        _task7_execute_fallback_import(path, "synthetic_dependency")
    assert caught.value.name == "synthetic_dependency"

    source = read_host(path)
    assert "except ModuleNotFoundError as exc:" in source
    assert 'if exc.name != "simulations":' in source
    mutant, count = re.subn(
        r"except ModuleNotFoundError as exc:[^\n]*\n"
        r'    if exc\.name != "simulations":\n'
        r"        raise\n",
        "except ModuleNotFoundError:\n",
        source,
        count=1,
    )
    assert count == 1 and mutant != source
    # The old broad fallback swallows the synthetic transitive failure and
    # continues through the direct-script branch.  Execute the mutant rather
    # than merely comparing source/AST text so this mutation can genuinely fail.
    mutant_namespace = _task7_execute_fallback_import(
        path, "synthetic_dependency", mutant
    )
    assert expected_names <= set(mutant_namespace)


