def _task10_niven_canonical_surface(path, source):
    if path == "docs/ANALYTICAL_FORMULAS.md":
        return "### F65." + source.split("### F65.", 1)[1].split("### F66.", 1)[0]
    if path.endswith("OpenArcsRegistry.cs"):
        return source.split('Name: "n3_special_cases"', 1)[1].split(
            "\n        new OpenArc(", 1
        )[0]
    if path.endswith("InspectCommand.cs"):
        return source.split('new("niven",', 1)[1].split('new("transition",', 1)[0]
    if path.endswith("KnowledgeRegistryFactory.cs"):
        return source.split("// The Niven root (Tier1Derived", 1)[1].split(
            ".RegisterNivenRationalityRootClaim()", 1
        )[0]
    return source


def _task10_niven_canonical_findings(path, source):
    surface = _task10_niven_canonical_surface(path, source)
    findings = []
    for phrase in TASK10_NIVEN_CANONICAL_CONTRACT:
        present = phrase in surface
        if phrase.startswith("exact Niven"):
            present = phrase.casefold() in surface.casefold()
        if not present:
            findings.append(("canonical-contract", phrase))
    for headline in TASK10_NIVEN_LOCAL_HEADLINES.get(path, ()):
        if headline not in surface:
            findings.append(("local-headline", headline))
    return findings


