def _task8_niven_python_root_association_findings(source):
    tree = ast.parse(source, filename="simulations/niven_rationality_root.py")
    print_strings = tuple(
        node.args[0].value
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "print"
        and node.args
        and isinstance(node.args[0], ast.Constant)
        and isinstance(node.args[0].value, str)
    )
    shared_root = tuple(
        value for value in print_strings if value.lstrip().startswith("ROOT:")
    )
    re_model = tuple(
        value
        for value in print_strings
        if value.startswith("For ") and "RE face" in value
    )
    findings = []
    if shared_root != (TASK8_NIVEN_SHARED_ROOT_SENTENCE,):
        findings.append(("shared-root-sentence", shared_root))
    if any(
        "uniform open XX chain with one dephased endpoint" in value
        for value in shared_root
    ):
        findings.append(("shared-root-model-qualifier", shared_root))
    if re_model != (TASK8_NIVEN_RE_MODEL_SENTENCE,):
        findings.append(("re-only-model-sentence", re_model))
    return findings


