def _task10_niven_gate_inventory_findings(claim_source, producer_source):
    declared = tuple(
        re.findall(r"(?m)^\s*# (G[0-9]+[a-z]?):", producer_source)
    )
    reported = tuple(
        re.findall(r'(?m)^\s*print\("(G[0-9]+[a-z]?) PASS', producer_source)
    )
    findings = []
    if declared != TASK10_NIVEN_NAMED_GATES:
        findings.append(("producer-declarations", declared))
    if reported != TASK10_NIVEN_NAMED_GATES:
        findings.append(("producer-pass-labels", reported))
    if "(7/7 gates)" not in claim_source:
        findings.append(("claim-count", "missing 7/7 gates"))
    if "(6/6 gates)" in claim_source:
        findings.append(("claim-count", "stale 6/6 gates"))
    for phrase in (
        "complete low-totient classification",
        "bounded SymPy minimal-polynomial cross-check through N=10",
    ):
        if phrase not in claim_source:
            findings.append(("claim-proof-scope", phrase))
    return findings


