def _task10_niven_quantifier_findings(path, source):
    """Read the actual comb sentence / conditional row labels, not a disclaimer."""
    if path == "docs/ANALYTICAL_FORMULAS.md":
        surface = _task10_source_slice(source, "**Niven rationality.**", "**Verified coefficient values:**")
        if "For all other N the comb contains algebraic irrational coefficients" not in surface:
            return ["NIVEN_COMB_QUANTIFIER:missing-existential"]
        if "For all other N the coefficients are algebraic irrationals" in surface:
            return ["NIVEN_COMB_QUANTIFIER:all-irrational"]
        return []
    if path.endswith("NivenRationalityRootWitness.cs"):
        surface = _task10_source_slice(source, "private InspectableNode ReFace()", "private static string[] FirstOrderCombList")
        branches = re.findall(r'rat\s*\?\s*"([^"]+)"\s*:\s*"([^"]+)"', surface)
    else:
        tree = ast.parse(source, filename=path)
        main = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == "main")
        branches = [
            (node.body.value, node.orelse.value)
            for node in ast.walk(main)
            if isinstance(node, ast.IfExp)
            and isinstance(node.test, ast.Name) and node.test.id == "re_rat"
            and isinstance(node.body, ast.Constant) and isinstance(node.body.value, str)
            and isinstance(node.orelse, ast.Constant) and isinstance(node.orelse.value, str)
        ]
    if branches != [("all rational", "contains irrational coefficients")]:
        return [f"NIVEN_COMB_QUANTIFIER:row-labels:{branches}"]
    return []


def test_task10_niven_n7_exact_comb_has_rational_and_irrational_coefficients():
    source = read_host("simulations/niven_rationality_root.py")
    tree = ast.parse(source)
    coefficient = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == "f65_first_order_coefficient")
    namespace = {"sp": sp}
    exec(compile(ast.Module(body=[coefficient], type_ignores=[]), "niven-coefficient", "exec"), namespace)
    actual = [namespace["f65_first_order_coefficient"](7, k) for k in range(1, 8)]
    # Independent exact cosine form plus a literal mixed comb: no float recognition.
    expected = [
        sp.Rational(1, 4) - sp.sqrt(2) / 8, sp.Rational(1, 4),
        sp.Rational(1, 4) + sp.sqrt(2) / 8, sp.Rational(1, 2),
        sp.Rational(1, 4) + sp.sqrt(2) / 8, sp.Rational(1, 4),
        sp.Rational(1, 4) - sp.sqrt(2) / 8,
    ]
    cosine_form = [sp.simplify((1 - sp.cos(sp.pi * k / 4)) / 4) for k in range(1, 8)]
    assert actual == cosine_form == expected
    assert [value.is_rational for value in actual] == [False, True, False, True, False, True, False]


