def _task9_front_door_count_findings(path, source):
    findings = []
    for required in TASK9_FRONT_DOOR_STABLE_LABELS[path]:
        if required not in source:
            findings.append(f"{path}: missing stable front-door wording: {required}")
    for label, pattern in (
        ("numbered F-result count", r"\b\d+\s+F-numbered results\b"),
        ("parenthesized inventory count", r"\([^\n)]*\b\d+\s+documents?\)"),
        ("experiment approximation", r"`experiments/`\s*~\d+"),
        ("script approximation", r"`simulations/`[^\n]*~\d+"),
    ):
        if re.search(pattern, source):
            findings.append(f"{path}: volatile {label}")
    return tuple(findings)


