@pytest.mark.parametrize("path", TASK9_TRANSITIVE_IMPORT_HOSTS)
def test_task9_heavy_producer_import_is_silent_in_fresh_process(path, tmp_path):
    work = tmp_path / Path(path).stem
    work.mkdir()
    launcher = (
        "import runpy, sys\n"
        "from pathlib import Path\n"
        "before = tuple(sys.path)\n"
        "class QuietProbe:\n"
        "    def write(self, value):\n"
        "        if value: raise AssertionError('import wrote output')\n"
        "        return 0\n"
        "    def flush(self): return None\n"
        "    def reconfigure(self, *args, **kwargs):\n"
        "        raise AssertionError('import reconfigured stdout')\n"
        "sys.stdout = QuietProbe()\n"
        "runpy.run_path(sys.argv[1], run_name='task9_import_probe')\n"
        "assert tuple(sys.path) == before\n"
    )
    result = subprocess.run(
        [sys.executable, "-c", launcher, str(ROOT / path)],
        cwd=work, text=True, capture_output=True, timeout=90,
    )
    assert result.returncode == 0, (path, result.stdout, result.stderr)
    assert result.stdout == result.stderr == ""
    assert tuple(work.iterdir()) == ()


