def _a391_assert_pipe_table_owner(surface, label):
    body_lines = surface.splitlines()[1:]
    while body_lines and not body_lines[0].strip():
        body_lines.pop(0)
    while body_lines and not body_lines[-1].strip():
        body_lines.pop()
    if len(body_lines) < 3:
        raise AssertionError(f"A391_{label}_OWNER_WIDENED:incomplete pipe table")
    if any(not line.strip() for line in body_lines):
        raise AssertionError(f"A391_{label}_OWNER_WIDENED:split pipe table")

    rows = []
    for line in body_lines:
        indentation = re.match(r"^[ \t]*", line).group(0)
        if "\t" in indentation or len(indentation) > 3:
            raise AssertionError(f"A391_{label}_OWNER_WIDENED:pipe indentation")
        stripped = line.strip()
        if not stripped.startswith("|") or not stripped.endswith("|"):
            raise AssertionError(f"A391_{label}_OWNER_WIDENED:{line}")
        rows.append(tuple(cell.strip() for cell in stripped[1:-1].split("|")))

    column_count = len(rows[0])
    if column_count < 2 or any(len(row) != column_count for row in rows):
        raise AssertionError(f"A391_{label}_OWNER_WIDENED:pipe column count")
    if not all(
        A391_PIPE_TABLE_DELIMITER_CELL_RE.fullmatch(cell) for cell in rows[1]
    ):
        raise AssertionError(f"A391_{label}_OWNER_WIDENED:pipe delimiter row")


def _a391_concept_surface(source):
    unemphasized = A391_MARKDOWN_EMPHASIS_RE.sub("", source)
    separated = A391_DASH_SEPARATOR_RE.sub(" ", unemphasized)
    return re.sub(r"\s+", " ", separated).strip()


def _a391_concept_clauses(source):
    return tuple(
        normalized
        for part in A391_CONCEPT_CLAUSE_SEPARATOR_RE.split(source)
        if (normalized := _a391_concept_surface(part))
    )


def _a391_concept_words(clause):
    return tuple(
        match.group(0).lower() for match in A391_CONCEPT_WORD_RE.finditer(clause)
    )


def _a391_words_have_explicit_hardware_context(words):
    word_set = frozenset(words)
    if A391_EXPLICIT_HARDWARE_CONTEXT_WORDS & word_set:
        return True
    return any(
        tuple(words[index : index + len(phrase)]) == phrase
        for phrase in A391_EXPLICIT_HARDWARE_CONTEXT_PHRASES
        for index in range(len(words) - len(phrase) + 1)
    )


def _a391_explicit_hardware_context_indices(words):
    indices = {
        index
        for index, word in enumerate(words)
        if word in A391_EXPLICIT_HARDWARE_CONTEXT_WORDS
    }
    for phrase in A391_EXPLICIT_HARDWARE_CONTEXT_PHRASES:
        for index in range(len(words) - len(phrase) + 1):
            if tuple(words[index : index + len(phrase)]) == phrase:
                indices.add(index + len(phrase) - 1)
    return tuple(sorted(indices))


def _a391_hardware_context_is_locally_negated(words, context_index):
    for negation_index in range(max(0, context_index - 6), context_index):
        if words[negation_index] not in A391_NEGATION_WORDS:
            continue
        bridge = words[negation_index + 1 : context_index]
        if all(
            word in A391_HARDWARE_CONTEXT_NEGATION_BRIDGE_WORDS
            for word in bridge
        ):
            return True
    return False


def _a391_normalized_relative_path_count(source, target):
    normalized_target = posixpath.normpath(target)
    return sum(
        posixpath.normpath(match.group("path")) == normalized_target
        for match in A391_RELATIVE_PATH_RE.finditer(source)
    )


def _a391_reference_label(label):
    return re.sub(r"\s+", " ", label).strip().casefold()


def _a391_normalized_target_count(source, owner_surface, target):
    normalized_target = posixpath.normpath(target)
    count = _a391_normalized_relative_path_count(owner_surface, target)
    definitions = {}
    for match in A391_COMMONMARK_REFERENCE_DEFINITION_RE.finditer(source):
        label = _a391_reference_label(match.group("label"))
        destination = match.group("angle") or match.group("bare")
        definitions.setdefault(label, posixpath.normpath(destination))
    for match in A391_COMMONMARK_REFERENCE_USE_RE.finditer(owner_surface):
        label = match.group("label") or match.group("text")
        if definitions.get(_a391_reference_label(label)) == normalized_target:
            count += 1
    for match in A391_COMMONMARK_SHORTCUT_REFERENCE_RE.finditer(owner_surface):
        if definitions.get(
            _a391_reference_label(match.group("label"))
        ) == normalized_target:
            count += 1
    return count


def _a391_validation_is_locally_negated(clause, words, validation_index):
    for negation_index in range(max(0, validation_index - 6), validation_index):
        if words[negation_index] not in A391_NEGATION_WORDS:
            continue
        bridge = words[negation_index + 1 : validation_index]
        if all(word in A391_NEGATION_BRIDGE_WORDS for word in bridge):
            return True

    suffix = words[validation_index + 1 : validation_index + 5]
    if len(suffix) >= 3 and suffix[0] in A391_VALIDATION_RESULT_AUXILIARIES:
        if suffix[1] in A391_NEGATION_WORDS:
            if suffix[2] in A391_NEGATED_VALIDATION_RESULT_WORDS:
                return True
            if len(suffix) >= 4 and suffix[2] in A391_INDEPENDENCE_WORDS:
                return suffix[3] in A391_NEGATED_VALIDATION_RESULT_WORDS
    return False


def _a391_clause_establishes_hardware_context(clause):
    words = _a391_concept_words(clause)
    context_indices = _a391_explicit_hardware_context_indices(words)
    if not context_indices:
        return False
    has_positive_context = any(
        not _a391_hardware_context_is_locally_negated(words, index)
        for index in context_indices
    )
    if not has_positive_context:
        return False
    validation_indices = tuple(
        index
        for index, word in enumerate(words)
        if word in A391_ALL_VALIDATION_WORDS
    )
    if not validation_indices:
        return True
    return any(
        not _a391_validation_is_locally_negated(clause, words, index)
        for index in validation_indices
    )


def _a391_clause_promotes_hardware(clause, *, implicit_hardware=False):
    words = _a391_concept_words(clause)
    context_indices = _a391_explicit_hardware_context_indices(words)
    has_explicit_hardware = bool(context_indices)
    has_positive_explicit_hardware = any(
        not _a391_hardware_context_is_locally_negated(words, index)
        for index in context_indices
    )
    context_available = has_positive_explicit_hardware or (
        implicit_hardware and not has_explicit_hardware
    )
    if not context_available:
        return False
    return any(
        word in A391_ALL_VALIDATION_WORDS
        and not _a391_validation_is_locally_negated(clause, words, index)
        for index, word in enumerate(words)
    )


def _a391_is_allowed_validation_clause(clause, allowed_validation):
    words = _a391_concept_words(clause)
    normalized_allowed = _a391_concept_surface(allowed_validation).casefold()
    return (
        any(word in A391_ALL_VALIDATION_WORDS for word in words)
        and clause.casefold() == normalized_allowed
    )


def _a391_has_hardware_promotion(
    source, *, implicit_hardware=False, allowed_validations=()
):
    clauses = _a391_concept_clauses(source)
    remaining_allowances = list(allowed_validations)
    allowed_clause_flags = []
    for clause in clauses:
        match = next(
            (
                index
                for index, allowed in enumerate(remaining_allowances)
                if _a391_is_allowed_validation_clause(clause, allowed)
            ),
            None,
        )
        allowed_clause_flags.append(match is not None)
        if match is not None:
            remaining_allowances.pop(match)
    owner_has_explicit_hardware = any(
        _a391_clause_establishes_hardware_context(clause)
        for clause, is_allowed in zip(clauses, allowed_clause_flags)
        if not is_allowed
    )
    for clause, is_allowed in zip(clauses, allowed_clause_flags):
        if is_allowed and not owner_has_explicit_hardware:
            continue
        if _a391_clause_promotes_hardware(
            clause,
            implicit_hardware=(implicit_hardware or owner_has_explicit_hardware),
        ):
            return True
    return False


def _a391_exact_owner_slice(
    source, start, stop, label, *, require_pipe_table=False
):
    start_count = source.count(start)
    assert start_count == 1, f"A391_{label}_START_COUNT:{start_count}"
    tail = source.split(start, 1)[1]
    stop_count = tail.count(stop)
    assert stop_count == 1, f"A391_{label}_STOP_COUNT:{stop_count}"
    surface = start + tail.split(stop, 1)[0]
    heading = A391_COMMONMARK_HEADING_RE.match(start)
    if heading is not None:
        owner_level = len(heading.group(1))
        lines = surface.splitlines()
        for index, line in enumerate(lines[1:], start=1):
            nested_heading = A391_COMMONMARK_HEADING_RE.match(line)
            if nested_heading is not None and len(nested_heading.group(1)) <= owner_level:
                raise AssertionError(f"A391_{label}_OWNER_WIDENED:{line}")
            if index + 1 < len(lines) and line.strip():
                indentation = re.match(r"^[ \t]*", line).group(0)
                setext = A391_COMMONMARK_SETEXT_RE.match(lines[index + 1])
                if "\t" not in indentation and len(indentation) <= 3 and setext:
                    setext_level = 1 if setext.group("underline").startswith("=") else 2
                    if setext_level <= owner_level:
                        raise AssertionError(f"A391_{label}_OWNER_WIDENED:{line}")
    if require_pipe_table:
        _a391_assert_pipe_table_owner(surface, label)
    return surface
def _a391_unique_paragraph(source, token, label):
    matches = [paragraph for paragraph in source.split("\n\n") if token in paragraph]
    assert len(matches) == 1, f"A391_{label}_PARAGRAPH_COUNT:{len(matches)}"
    return matches[0]


def _a391_unique_line(source, prefix, label):
    matches = []
    for line in source.splitlines():
        indentation = re.match(r"^[ \t]*", line).group(0)
        if "\t" in indentation or len(indentation) > 3:
            continue
        if line[len(indentation) :].startswith(prefix):
            matches.append(line)
    assert len(matches) == 1, f"A391_{label}_LINE_COUNT:{len(matches)}"
    return matches[0]


def _a391_hardware_label_owner_surfaces(path, source):
    if path == A391_PREDICTIONS_PATH:
        preamble = _a391_exact_owner_slice(
            source, A391_PREAMBLE_START, A391_PREAMBLE_STOP, "PREAMBLE"
        )
        section1 = _a391_exact_owner_slice(
            source, A391_SECTION1_START, A391_SECTION1_STOP, "SECTION1"
        )
        q52 = _a391_exact_owner_slice(
            source, A391_Q52_START, A391_Q52_STOP, "Q52"
        )
        summary = _a391_exact_owner_slice(
            source,
            A391_SUMMARY_START,
            A391_SUMMARY_STOP,
            "SUMMARY",
            require_pipe_table=True,
        )
        return {
            "preamble": _a391_unique_paragraph(
                preamble, "This is the master catalog", "PREAMBLE_COPY"
            ),
            "section_scope": _a391_unique_paragraph(
                section1, "**Scope of this section:**", "SECTION1_SCOPE"
            ),
            "algebraic_row": _a391_unique_line(
                section1, "| x³ + x", "ALGEBRAIC_ROW"
            ),
            "registry_scope": _a391_unique_paragraph(
                section1, "`fw.Confirmations`", "REGISTRY_SCOPE"
            ),
            "calibration_proxy": _a391_unique_paragraph(
                section1, "24,073 historical calibration", "CALIBRATION_PROXY"
            ),
            "q52_interval": _a391_unique_line(
                q52, "| Rising coherence trend", "Q52_INTERVAL"
            ),
            "generalized_row": _a391_unique_line(
                section1, "| Generalized crossing equation", "GENERALIZED_ROW"
            ),
            "absorption_row": _a391_unique_line(
                section1, "| Absorption Theorem ratio", "ABSORPTION_ROW"
            ),
            "absorption_paragraph": _a391_unique_paragraph(
                section1, "**The Absorption Theorem**", "ABSORPTION_PARAGRAPH"
            ),
            "summary_hardware": _a391_unique_line(
                summary, A391_SUMMARY_HARDWARE_CATEGORY_CELL, "SUMMARY_HARDWARE"
            ),
        }
    if path == A391_FORMULAS_PATH:
        return {
            "f13": _a391_exact_owner_slice(
                source, A391_F13_START, A391_F13_STOP, "F13"
            ),
            "f24": _a391_exact_owner_slice(
                source, A391_F24_START, A391_F24_STOP, "F24"
            )
        }
    raise AssertionError(f"A391_UNOWNED_PATH:{path}")


def _a391_hardware_label_findings(path, source):
    surfaces = _a391_hardware_label_owner_surfaces(path, source)
    findings = []
    for name, surface in surfaces.items():
        semantic_surface = _task7_normalize_paragraph(surface)
        for phrase in A391_REQUIRED[name]:
            if _task7_normalize_paragraph(phrase) not in semantic_surface:
                findings.append(f"A391:{name}:MISSING:{phrase}")
        for phrase in A391_FORBIDDEN[name]:
            if _task7_normalize_paragraph(phrase) in semantic_surface:
                findings.append(f"A391:{name}:STALE:{phrase}")
        if name == "absorption_row":
            link_count = _a391_normalized_target_count(
                source, surface, A391_Q52_HARDWARE_TARGET
            )
            if link_count != 1:
                findings.append(
                    f"A391:absorption_row:Q52_LINK_COUNT:{link_count}"
                )
        if name in A391_HARDWARE_PROMOTION_SURFACES:
            concept_owner = surface
            if name == "summary_hardware":
                concept_owner = concept_owner.replace(
                    A391_SUMMARY_HARDWARE_CATEGORY_CELL, "| |", 1
                )
            if _a391_has_hardware_promotion(
                concept_owner,
                implicit_hardware=(
                    name in A391_IMPLICIT_HARDWARE_CONTEXT_SURFACES
                ),
                allowed_validations=A391_ALLOWED_VALIDATION_CLAUSES.get(
                    name, ()
                ),
            ):
                findings.append(f"A391:{name}:CONCEPT:CLAUSE")
    return findings


def _a391_replace_in_owner(source, path, name, current, stale):
    surface = _a391_hardware_label_owner_surfaces(path, source)[name]
    assert surface.count(current) == 1, (name, current)
    mutant_surface = surface.replace(current, stale, 1)
    assert source.count(surface) == 1, name
    return source.replace(surface, mutant_surface, 1)


def _a391_append_claim_to_owner(surface, claim):
    if surface.endswith("|"):
        return surface[:-1].rstrip() + ". " + claim + " |"
    return surface + " " + claim


