def _a394_cli_spiral_label_findings(source):
    start_marker = "/// <c>--axis spiral</c>"
    stop_marker = "/// <c>--axis approach</c>"
    findings = []
    if source.count(start_marker) != 1:
        findings.append(f"A394:SPIRAL_START_COUNT:{source.count(start_marker)}")
        return tuple(findings)
    start = source.index(start_marker)
    stop_count = source[start:].count(stop_marker)
    if stop_count != 1:
        findings.append(f"A394:SPIRAL_STOP_COUNT:{stop_count}")
        return tuple(findings)
    stop = source.index(stop_marker, start)
    owner = source[start:stop]
    if "the radial readout circle |CΨ|=¼" not in owner:
        findings.append("A394:SPIRAL_RADIAL_LABEL")
    if "only c=+¼ is the period-one cardioid cusp" not in owner:
        findings.append("A394:SPIRAL_CARDIOID_LABEL")
    if "the cusp ¼ as a circle" in owner:
        findings.append("A394:SPIRAL_OLD_IDENTITY")
    return tuple(findings)


def test_a394_cli_spiral_doc_keeps_radial_circle_and_cardioid_cusp_distinct():
    source = read_host("compute/RCPsiSquared.Cli/Commands/InspectCommand.cs")
    assert not _a394_cli_spiral_label_findings(source)


@pytest.mark.parametrize(
    "current,replacement,expected",
    (
        (
            "the radial readout circle |CΨ|=¼ crossed by every plotted spiral;",
            "the cusp ¼ as a circle |CΨ|=¼ that every spiral crosses;",
            {"A394:SPIRAL_RADIAL_LABEL", "A394:SPIRAL_OLD_IDENTITY"},
        ),
        (
            "only c=+¼ is the period-one cardioid cusp",
            "the circle supplies the cardioid cusp",
            {"A394:SPIRAL_CARDIOID_LABEL"},
        ),
    ),
)
def test_a394_cli_spiral_doc_rejects_identity_and_missing_point_scope(
    current, replacement, expected
):
    source = read_host("compute/RCPsiSquared.Cli/Commands/InspectCommand.cs")
    mutant = source.replace(current, replacement, 1)
    assert mutant != source
    assert expected <= set(_a394_cli_spiral_label_findings(mutant))


